	Config.Combat = {
		ComboWindow = 1.6,          -- seconds to chain a swing
		-- One more swing animation than there are combo stacks, because stack 0 is
		-- the first swing of a chain. Stacks 0,1,2,3 map to SwingAnim.SWINGS 1..4,
		-- so the chain plays diagonal / backhand / sweep / slam and then repeats.
		ComboMaxStacks = 3,
		SwingSteps = 4,             -- must equal #SwingAnim.SWINGS; both sides assert it
		ComboDamagePerStack = 0.18, -- +18% per stack
		HitboxSize = Vector3.new(7, 7, 1),
		ArenaPvP = true,            -- PvP only inside the arena ring
		RespawnCash = 0,            -- cash lost on death (0 = friendly)

		-- SWING TIMING, as fractions of the bat's cooldown. The hitbox used to be
		-- evaluated on the same frame the swing started, i.e. a whole animation
		-- BEFORE the bat visibly reached the target — which is most of why the old
		-- combat read as clicking rather than as hitting. Damage now lands on the
		-- strike frame.
		SwingWindUp = 0.26,         -- fraction spent winding up
		SwingStrikeAt = 0.40,       -- fraction at which the bat is at the end of its arc
		-- The strike is a moving arc, so one instantaneous box misses targets that
		-- are a few frames early or late. Sample twice, this far apart.
		SwingSampleGap = 0.07,
		HitStop = 0.07,             -- seconds the swing freezes on a landed hit

		CritMultiplier = 2,
		CritKnockback = 1.6,

		-- The last step of a combo is the overhead slam. It is slower to reach (it
		-- is the fourth click) so it pays out.
		FinisherDamage = 1.5,
		FinisherKnockback = 1.8,
		FinisherReach = 1.25,

		-- Roblox's default is 16. The plot grew by a third, and 22 keeps the walk
		-- from the gateway to the last dropper at about six seconds. Above ~32 a
		-- humanoid starts clipping through 4-stud walls.
		WalkSpeed = 22,
		JumpPower = 52,
	}

	Config.Waves = {
		Enabled = true,

		-- PACING. There used to be one number here, `Interval = 210`, and the loop
		-- was `while true do startWave(); task.wait(Interval) end` — no check that
		-- the last wave had been cleared, against a 420s straggler despawn, so two
		-- or three waves legally coexisted and the banner attributed leftovers from
		-- one to another. Waves now run one at a time, and the gap is measured from
		-- YOUR clear rather than from a wall clock.
		FirstWaveDelay = 30,
		-- Quiet time between a wave clearing and the next warning going up.
		--
		-- 18 + WarningTime 12 = THIRTY SECONDS from your clear to the next raid
		-- landing, which is the number this is set against. The verifier already
		-- defines dead air as RestTime + WarningTime, so the two agree on what is
		-- being measured. It was 20, for 32.
		RestTime = 18,
		-- A boss wave is the one you actually need to bank and heal after.
		RestTimeAfterBoss = 35,
		-- DO NOT SHORTEN WarningTime TO CLOSE THE GAP. It is load-bearing:
		-- 12 x Combat.WalkSpeed = 264 studs against a MinPlotRadius of 210, which
		-- is what lets a player standing on their own plot get back to the arena
		-- before the raiders land. Shorten RestTime instead; the verifier asserts
		-- this relationship.
		WarningTime = 12,
		-- Deadlock breaker, not a pacing tool. Raider pathfinding is still naive
		-- MoveTo, so one snagged on geometry must not stop the schedule forever.
		-- Note this WILL occasionally cut a legitimately hard solo wave short —
		-- 26 wave-20 raiders is about 340s of solo attention — and that is the
		-- intended trade. The banner says "TIMED OUT" rather than "CLEARED".
		MaxWaveTime = 300,
		-- Per-raider backstop, strictly after the wave deadline so it can only
		-- catch an entry whose wave record was somehow lost.
		StragglerGrace = 45,
		ClearBannerTime = 4,        -- how long CLEARED stays up; must be < RestTime
		SpawnGap = 0.12,            -- between raiders in the drip
		JoinGrace = 20,             -- grace before the first wave on a waking server
		BroadcastInterval = 0.5,    -- coalesce the per-death counter updates
		EmptyResetAfter = 180,      -- empty this long and the wave counter resets

		-- WAVE SIZE. Bigger, and it climbs faster: the first raid is six rather
		-- than four, and it grows by four a wave to a ceiling of forty.
		--
		-- THIS DOES NOT UNDO THE ANTI-SWARM WORK, and it is worth knowing that
		-- before the two changes look like they are fighting each other. MaxChasers
		-- is still 8, so no matter how many are alive only eight can engage any one
		-- player. A bigger wave is therefore more REINFORCEMENTS — bodies milling
		-- at their home patches and stepping in as slots free — not more people
		-- hitting you at once. The verifier asserts the two stay far enough apart
		-- for that to remain the shape of it.
		BaseCount = 6,
		CountPerWave = 4,
		MaxCount = 40,
		-- Parts in one raider, counted rather than guessed: 26 in the visible Tung
		-- (invisible core, 2 legs + 2 feet, 8-part bat body, face plate, 2 arms +
		-- 2 hands, and another 8-part bat in its hand) plus the 7-part invisible R6
		-- rig underneath it. Recount in TungModels.build/buildBatBody/buildNPC if
		-- you change the silhouette.
		--
		-- The verifier cannot see TungModels, so this is the only way the part
		-- budget is checkable at all — and a wave cap is exactly the number someone
		-- raises without thinking about what it costs on a full server.
		PartsPerRaider = 33,
		MaxRaiderParts = 1600,
		BaseHealth = 90,
		HealthGrowth = 1.20,        -- wave 20 raider ~2.9k HP: ~13s for one player
		BaseDamage = 9,
		DamageGrowth = 1.07,
		-- A player has 100 HP. These are ABSOLUTE ceilings: the boss multiplier used
		-- to be applied to the cap as well as to the damage, so a wave-20 boss hit
		-- for 61 and killed a full-health player in two swings — exactly what the
		-- cap was written to prevent.
		MaxDamage = 34,
		MaxBossDamage = 45,
		BossHealthMultiplier = 6,
		BossDamageMultiplier = 1.8,
		WalkSpeed = 13,
		RewardBase = 150,
		RewardGrowth = 2.3,         -- reward scales with wave number
		StealPerHit = 0.006,        -- fraction of a player's cash a raider steals on hit
		BossEvery = 5,

		-- RAIDER ATTACKS. Damage used to land on the same tick the raider decided
		-- to attack, with no wind-up and no animation, so being hit was pure
		-- proximity: you could not see it coming and you could not step out of it.
		-- Raiders now raise the bat, hold, and only then swing — and they stand
		-- still while they do it, which is the window you punish.
		AttackRange = 8,
		AttackWindUp = 0.45,        -- seconds of telegraph before the hit lands
		AttackRecover = 0.35,       -- seconds rooted after swinging
		AttackCooldown = 1.35,
		AttackKnockback = 28,
		BossWindUpScale = 1.35,     -- bosses telegraph LONGER; they hit much harder

		-- RAIDER AI. Every raider used to call nearestPlayer(position, 500) every
		-- 0.6 seconds — a radius bigger than the whole map — so all 26 of them
		-- beelined the same player from anywhere, forever, with no wander, no
		-- aggro range and no way to break contact. They now spawn on the rim, walk
		-- in to a home patch in the arena, mill around it, and only commit to a
		-- player who comes close enough.
		--
		-- The whole design rests on the raiders being SLOWER than the players
		-- (13-17 against 22). Without that gap, de-aggro is unreachable and the
		-- leash is the only thing that ever fires. The verifier asserts it.
		AggroRadius = 55,           -- a raider notices you across its own patch...
		DeAggroRadius = 85,         -- ...and needs a real run to lose you again
		-- Measured from the raider's HOME PATCH, not from where it spawned and not
		-- from the world origin. Home patches are scattered within HomeSpread of
		-- the arena centre, so the furthest a leashed raider can ever swing at
		-- something is HomeSpread + LeashRadius + AttackRange = 124 studs — against
		-- a nearest plot EDGE of 140 (MinPlotRadius 210 less half a plot depth).
		-- That 16-stud clearance is what makes plots provably safe, and it is
		-- asserted rather than commented.
		LeashRadius = 72,
		HomeSpread = 44,            -- home patches fill the arena, clear of the wall
		WanderRadius = 18,          -- 44 + 18 = 62 < ArenaRadius 70
		WanderDwellMin = 2.5,
		WanderDwellMax = 5.0,
		WanderSpeedScale = 0.55,    -- idling is visibly slower; that reads the flip
		ReturnSpeedScale = 1.2,     -- and going home is brisk, so the arena refills
		HomeArrive = 8,
		-- A returning raider must get most of the way back before it can bite
		-- again, or a player parked on the leash line yo-yos it forever.
		ReAggroFrac = 0.6,
		RepathChase = 0.35,         -- a 22 studs/s player covers 7.7 studs; at 0.6 it was 13
		RepathWander = 1.2,
		RepathReturn = 0.8,
		AggroCheck = 0.25,          -- how often an idling raider looks around
		SnapshotInterval = 0.1,     -- how often the shared player snapshot rebuilds

		-- ANTI-SWARM. An aggro radius alone does not fix the pile-up: raiders that
		-- spawn on one evenly-divided ring all cross the same threshold on the same
		-- tick and then converge on one point, so the wave arrives as a wall and
		-- fights as a single blob standing inside itself.
		SpawnGroupSize = 4,         -- clusters, not one synchronised ring
		SpawnGroupGap = 0.6,        -- pause between clusters
		GroupArc = 0.35,            -- radians of jitter within a cluster (~18 studs at r=52)
		AggroStagger = 1.8,         -- each raider holds you this long, at random, before committing
		-- Raiders MoveTo a point on a ring around you rather than to you. Under
		-- AttackRange, so a raider parked on its slot is already in swing range and
		-- the ring costs no damage output — it only stops 26 bodies occupying one
		-- stud.
		ApproachStandoff = 6.5,
		OrbitSpeed = 0.35,          -- rad/sec of drift, so the ring reads as a mob not a formation
		-- How many may engage one player at once. Not arbitrary: a 6.5-stud ring
		-- has a circumference of 40.8 and a raider is about 4.5 studs wide, so nine
		-- fit shoulder to shoulder. Eight leaves a slot of slack, and the ones over
		-- the cap keep milling and step in as slots free — which reads as
		-- reinforcements rather than as a queue.
		MaxChasers = 8,
	}

	-- ─────────────────────────────────────────────────────────────────────────────
	-- BELT PATHS AND FLOORS
	--
	-- These lived under the PROTOTYPES banner, which was already a lie:
	-- Tycoon.new consumes BeltPaths[1] unconditionally to build the ground floor's
	-- conveyor. They are shipped data and they sit with the shipped data.
	--
	-- A path is just a list of corners, and every piece of belt geometry derives
	-- from leg(i), so the runtime does not care how many legs there are.
	-- ─────────────────────────────────────────────────────────────────────────────
	--
	-- Ground floor path is derived from the shipped Layout keys rather than
	-- duplicated, so the two cannot drift.
	--- `outboard` carries which SIDE of each leg the machines stand on, +1 or -1.
	--- It used to be inferred, by taking the perpendicular that points away from
	--- the plot origin — which works only while every leg hugs an outer edge. An
	--- upper floor's return leg runs back across the middle of its own deck, where
	--- the inferred side flips and puts the machines over the walkway and the buy
	--- buttons out in space. One entry per leg, so one fewer than `points`.
	Config.BeltPaths = {
		{
			id = "ground",
			y = 0,
			points = { Config.Layout.BeltStart, Config.Layout.BeltCorner, Config.Layout.BeltEnd },
			outboard = { 1, 1 },
			collectorAt = Config.Layout.CollectorAt,
		},
	}

	--- The upper floor. NOT stacked on the ground floor: a ceiling is the one thing
	--- Roblox's camera has no good answer for (opaque snaps the camera to head
	--- height, transparent lets it pop through, and LocalTransparencyModifier is
	--- overwritten by the default camera scripts every frame). An open mezzanine
	--- over the BACK half of the plot leaves the aisle you walk open to the sky.
	Config.Floors = {
		{
			id = "mezzanine",
			-- The button that BUILDS this floor. It used to be `requires =
			-- "dropper10"` — own the last dropper and the whole deck appeared for
			-- free, at the very end of the build. It is a purchase now, and it
			-- lands at the halfway mark.
			button = "floor2",
			height = 22,             -- floor top, plot-local
			-- deck covers the back half only, so it does not roof the walkway
			deckSize = Vector3.new(112, 1.6, 60),
			deckAt = Vector3.new(0, 0, -38),
			-- belt and machines float this far over the deck: a belt base whose
			-- underside is coplanar with the deck's top face is two surfaces at one
			-- Y, which z-fights
			deckLift = 0.1,
			railHeight = 5,          -- falling off is the obvious new failure mode

			-- BELT MARGINS, in from each deck edge.
			--
			-- Each has to clear MachineOffset + MachineFootprint/2 + rail thickness
			-- or a machine standing on that leg hangs over the railing. `side` was
			-- 10 and needed 11.5, so leg 2's machine strip overshot the deck by a
			-- stud and a half; `back` was 12 against 11.5, half a stud of margin.
			-- Nothing stood there only because the floor carried one dropper on leg
			-- 1 — which is the whole reason this geometry had to become data before
			-- anything could be bought on it.
			belt = {
				back = 13,
				side = 12,
				front = 14,
				collectorRun = 16,   -- run-off between the belt's end and the hopper
				padClearance = 12,   -- keep the hopper this clear of the teleport pad
				outboard = { 1, 1, 1 },
			},

			rail = { thickness = 1, bar = 1.4 },

			-- Support posts down to the plot floor. Their footprints miss what is
			-- already down there: 4 in from the deck's sides puts them at x = +-52,
			-- outboard of leg 2 (which reaches x = -48.6) and clear of the upgrader
			-- beams; 8 in from the front edge drops them at z = -16, between
			-- upgrader slots 2 and 3 at z = -26 and z = -10.
			pillar = { size = 2.4, insetSide = 4, insetBack = 4, insetFront = 8 },

			-- TELEPORT PADS. Shipped elevators in this genre are pad pairs, not
			-- moving platforms: TweenService lifts jitter and slide players off.
			--
			-- `down` and `up` used to share coordinates, which reads as a lift
			-- shaft and is the nicer arrangement — but the ground end at (40, -14)
			-- interpenetrated the armour cabinet's slot-2 pedestal by three studs
			-- by one, and there is no clean 9x9 anywhere on that side: the weapons
			-- and armour columns at x = 30 and 44 on a 14-stud pitch cap the best
			-- achievable clearance at exactly zero. So the ground end moves to the
			-- aisle side, where it has 3.5 studs of room. They do not have to line
			-- up, and FloorService never assumed they did.
			pads = {
				size = Vector3.new(9, 1, 9),
				groundTop = 1.1,     -- its own Y: claim pad tops out at 1.2, rebirth at 1.5
				stand = 3.5,         -- pivot height above the pad you land on
				cooldown = 1.5,
				down = Vector3.new(10, 0, -20),
				up   = Vector3.new(40, 0, -14),
			},
		},
	}

	--- The mezzanine's belt, as a Config.BeltPaths entry.
	---
	--- Three legs around the back and left of the deck, then a return leg back
	--- across it to the hopper. Derived from the deck rectangle and the pad
	--- position rather than written out as a second set of magic coordinates, so it
	--- follows the deck if that is ever resized.
	---
	--- The return leg is what the old inferred-outboard heuristic could not do: its
	--- midpoint sits near the middle of the plot, so "point away from the origin"
	--- picks the wrong side and hangs the machines over the walkway. Every leg's
	--- side is stated.
	---
	--- COMPONENT ARITHMETIC ONLY. tools/verify_config.lua stubs Vector3 as a plain
	--- table with no operators, so `deckSize * 0.5` here would take the entire
	--- 1200-check suite down at require time. This function is the reason the
	--- mezzanine's belt is visible to the belt assertions at all, so it would be a
	--- particularly silly place to break them.
	function Config.floorBeltPath(floor)
		local b = floor.belt
		local halfX, halfZ = floor.deckSize.X / 2, floor.deckSize.Z / 2

		local backZ = floor.deckAt.Z - halfZ + b.back
		local frontZ = floor.deckAt.Z + halfZ - b.front
		local rightX = floor.deckAt.X + halfX - b.side
		local leftX = floor.deckAt.X - halfX + b.side
		local collectorX = floor.pads.up.X - b.padClearance

		return {
			id = floor.id,
			y = floor.height + floor.deckLift,
			points = {
				Vector3.new(rightX, 0, backZ),
				Vector3.new(leftX, 0, backZ),
				Vector3.new(leftX, 0, frontZ),
				Vector3.new(collectorX - b.collectorRun, 0, frontZ),
			},
			outboard = b.outboard,
			collectorAt = Vector3.new(collectorX, 0, frontZ),
		}
	end

	for _, floor in ipairs(Config.Floors) do
		table.insert(Config.BeltPaths, Config.floorBeltPath(floor))
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- PROTOTYPES
	--
	-- Everything below this line is unshipped. Each block is gated by a flag in
	-- Config.Prototypes and every one of them defaults to OFF, so a build with all
	-- the flags false is byte-for-byte the game that ships today. That is the whole
	-- contract: a prototype you cannot turn off is not a prototype, it is a
	-- half-finished feature you have to finish before you can ship anything else.
	--
	-- The rationale for each of these — what shipped where, and what players said
	-- about it — is in IDEAS.md. Numbers here are first drafts, not balance.
	-- ─────────────────────────────────────────────────────────────────────────────

	-- `Floors` is gone from this table rather than set true: the check below asserts
	-- every prototype flag ships off, so graduating one means it stops being a
	-- prototype, not that it becomes the exception. The second floor is a purchase
	-- on the factory track now, gated by owning its button like everything else.
	Config.Prototypes = {
		PlayerUpgrades = false,-- walkspeed / magnet / cash multiplier shop
		Utilities = false,     -- a second weapon slot holding a verb, not a stat
		RebirthPerks = false,  -- rebirth grants four things instead of one number
		Offline = false,       -- offline earnings and the welcome-back panel
		Sessions = false,      -- daily streak, playtime ladder, boost cooldown
		Sound = false,         -- the engine-asset sound layer
	}

	-- ── player upgrades ──────────────────────────────────────────────────────────
	--
	-- Deliberately small. Pet Sim 99's whole walkspeed track is +25% over two
	-- tiers, and its biggest stat track is +54% over eight. The large multipliers
	-- belong to rebirth; this shop is for shaving friction off the loop.
	Config.PlayerUpgrades = {
		{
			id = "speed", name = "Sahur Sprint",
			stat = "WalkSpeed", levels = 8,
			base = 22, perLevel = 1.1,        -- caps at 30.8, under the ~32 wall-clip ceiling
			cost = 250, costGrowth = 4,
			blurb = "Move %s studs/sec.",
		},
		{
			id = "magnet", name = "Tung Magnet",
			stat = "CollectRadius", levels = 7,
			base = 0, perLevel = 4,
			cost = 400, costGrowth = 3.4,
			blurb = "Pull drops in from %s studs.",
		},
		{
			id = "payout", name = "Vault Skimmer",
			stat = "CashMultiplier", levels = 7,
			base = 1, perLevel = 0.08,
			cost = 800, costGrowth = 5,
			blurb = "All income x%s.",
		},
		{
			id = "autocollect", name = "Auto Collector",
			stat = "AutoCollect", levels = 1,
			base = 0, perLevel = 1,
			cost = 60000, costGrowth = 1,
			blurb = "The vault collects itself.",
		},
	}

	-- ── the utility slot ─────────────────────────────────────────────────────────
	--
	-- Steal a Brainrot's weapon ladder is one archetype reskinned eleven times,
	-- scaling exactly one stat. All of its VARIETY lives in a second slot where
	-- every item is a new verb with one duration number. That split is the thing
	-- worth copying: progression in the weapon, variety in the utility.
	--- `radius` and `force` are per-verb, not global: how far a shove reaches is a
	--- property of the shove, and the moment they are shared constants the next
	--- utility has to fight them.
	Config.Utilities = {
		{ id = "freeze", name = "Sahur Freeze", verb = "freeze", duration = 4, cooldown = 18,
		  price = 40000, requires = "batforge", radius = 34 },
		{ id = "shove", name = "Tung Shove", verb = "shove", duration = 0, cooldown = 12,
		  price = 300000, requires = "upgrader3", radius = 26, force = 130 },
		{ id = "decoy", name = "Sahur Decoy", verb = "decoy", duration = 10, cooldown = 30,
		  price = 4000000, requires = "batforge2", radius = 6 },
	}

	-- ── rebirth perks ────────────────────────────────────────────────────────────
	--
	-- Four rewards per rebirth instead of one. The multiplier is the headline but
	-- the other three are what stop the re-grind feeling like a punishment, and
	-- what give MaxRebirths = 25 something on every rung.
	Config.RebirthPerks = {
		StartingCashPerRebirth = 2500,     -- compounding is handled by the multiplier
		StartingCashGrowth = 3.2,
		-- every Nth rebirth grants a permanent extra machine slot
		SlotEveryRebirths = 3,
		-- milestone unlocks: rebirth -> what opens up
		Milestones = {
			[2] = { unlock = "mezzanine", label = "Second floor" },
			[4] = { unlock = "utility2", label = "Utility slot II" },
			[8] = { unlock = "goldplot", label = "Golden plot theme" },
		},
	}

	-- ── offline earnings ─────────────────────────────────────────────────────────
	Config.Offline = {
		Rate = 0.25,             -- fraction of your live income per second
		CapHours = 8,
		-- extending the cap is a purchase, which turns the cap into a goal rather
		-- than a wall you resent
		CapUpgradeHours = { 12, 16, 24 },
		CapUpgradeCost = { 250000, 5000000, 120000000 },
		MinimumSeconds = 120,    -- below this, don't bother with the panel
	}

	-- ── session loops ────────────────────────────────────────────────────────────
	Config.Sessions = {
		-- 7-day loop with milestones. 48h of grace, because losing a 20-day streak
		-- to one missed evening is how you lose the player instead of the streak.
		DailyRewards = { 500, 1500, 4000, 10000, 25000, 60000, 150000 },
		DailyGraceHours = 48,
		DailyMilestones = { [7] = 250000, [14] = 750000, [30] = 3000000 },

		-- Pet Sim 99's ladder, and note the deliberately decaying cadence: close
		-- together early so the first one arrives while you are still deciding
		-- whether to stay.
		PlaytimeMinutes = { 5, 10, 15, 20, 30, 40, 50, 60, 75, 90, 120, 180 },
		PlaytimeRewardBase = 1200,
		PlaytimeRewardGrowth = 1.9,

		-- The rewarded-video-ad shape with the ad removed: a big multiplier over a
		-- short window, which forces an active session rather than being banked.
		BoostMultiplier = 2,
		BoostSeconds = 600,
		BoostCooldown = 2400,

		-- near-zero code, real concurrency effect
		WeekendMultiplier = 2,
		WeekendDays = { [1] = true, [7] = true },   -- os.date("!*t").wday, Sun and Sat
	}

	-- ── sound ────────────────────────────────────────────────────────────────────
	--
	-- Every one of these ships INSIDE the Roblox client. No upload, no moderation,
	-- and they cannot be taken down. The old handoff assumed audio was blocked
	-- until someone uploads samples; it is not, and this is the cheapest quality
	-- win on the list.
	Config.Sound = {
		Library = {
			collect  = "rbxasset://sounds/electronicpingshort.wav",
			purchase = "rbxasset://sounds/switch3.wav",
			ui       = "rbxasset://sounds/button.wav",
			impact   = "rbxasset://sounds/impact_water.mp3",
			swing    = "rbxasset://sounds/swoosh.wav",
			rebirth  = "rbxasset://sounds/victory.wav",
			siren    = "rbxasset://sounds/action.wav",
		},
		-- Pool and round-robin; never Instance.new per drop. ~400 live Sound
		-- instances is where audio/video desync starts.
		PoolSize = 8,
		MinRepeatSeconds = 0.04,
		RollOffMaxDistance = 60,   -- so a neighbour's factory doesn't blare at you
		PitchPerCombo = 0.06,
		MaxPitch = 2,
	}

	-- ─────────────────────────────────────────────────────────────────────────────
	-- Derived lookups (built once at require time)
	-- ─────────────────────────────────────────────────────────────────────────────

	-- Resolved once, at require time, so every module sees the same numbers.
	Config.World.PlotCount = Config.plotCountFor()
	Config.World.PlotPlacements = Config.plotPlacements(Config.World.PlotCount)
	Config.World.PlotRadius = Config.World.PlotPlacements[1].radius   -- inner ring

	-- THE MERGE. Three track tables become one Config.Buttons, in track order, so
	-- every consumer downstream still iterates a single array exactly as before.
	--
	-- FACTORY FIRST IS LOAD-BEARING. It leaves every factory button with the same
	-- `order` it had when there was only one table, which is what lets
	-- Tycoon:assign keep replaying installs by sorting on `order` — weapons and
	-- armour land after the whole factory, and because no requirement crosses a
	-- track that ordering is trivially valid. It also keeps the verifier's
	-- "requires must point at an earlier index" check true without modification.
	--
	--   order       position in the merged array. The install-order key. Global.
	--   trackOrder  position within the button's own track. The gating and
	--               display key: it is what the buy-button billboard counts, what
	--               the three-state reveal measures its frontier against, and
	--               what the HUD calls a step.
	Config.TrackOrder = { "factory", "weapons", "armor" }
	Config.Tracks = {
		factory = Config.FactoryButtons,
		weapons = Config.WeaponButtons,
		armor   = Config.ArmorButtons,
	}
	Config.TrackLabel = { factory = "FACTORY", weapons = "WEAPONS", armor = "ARMORY" }

	-- WHAT A WHOLE LADDER WAITS ON.
	--
	-- Deliberately NOT a `requires` on each track's first rung. The loader derives
	-- requirements within a track and the verifier asserts none ever crosses one —
	-- that guarantee is worth more than the convenience, and a precondition on an
	-- entire ladder is a different kind of thing from a link inside one.
	--
	-- The two cabinets stood on the plot from the moment you claimed it: two
	-- display cases and nine pedestals, for upgrades you could not use and had no
	-- reason to care about yet. That is most of the visual noise in the first few
	-- minutes, and it is why they now arrive with the second floor.
	Config.TrackUnlock = { weapons = "floor2", armor = "floor2" }

	--- Whether `track` is open on a plot that owns `owned`.
	---
	--- STICKY, and derived rather than stored. Owning any rung of a track counts as
	--- having it open, which matters because rebirth wipes the factory (and so the
	--- gate button) while deliberately keeping weapons and armour. Without that
	--- clause a rebirth would make the cabinets vanish while the shelf displays and
	--- the granted bat survived — a cabinet-shaped hole with a bat floating in it.
	--- Derived this way it costs no new persisted field and no migration.
	function Config.trackUnlocked(track: string, owned): boolean
		local gate = Config.TrackUnlock[track]
		if not gate or owned[gate] then
			return true
		end
		for _, def in ipairs(Config.Tracks[track] or {}) do
			if owned[def.id] then
				return true
			end
		end
		return false
	end

	Config.Buttons = {}
	Config.ButtonById = {}
	for _, track in ipairs(Config.TrackOrder) do
		local defs = Config.Tracks[track]
		for trackOrder, def in ipairs(defs) do
			def.track = track
			def.trackOrder = trackOrder
			-- A track IS a chain, so derive the link rather than restating it.
			-- This is what makes "no requirement crosses a track" a property of
			-- the loader instead of a promise the verifier has to police, and it
			-- deletes the single most error-prone field in this file for every
			-- row that doesn't genuinely need something unusual.
			if def.requires == nil and trackOrder > 1 then
				def.requires = defs[trackOrder - 1].id
			end
			table.insert(Config.Buttons, def)
			def.order = #Config.Buttons
			Config.ButtonById[def.id] = def
		end
	end

	Config.BatById = {}
	for tier, def in ipairs(Config.Bats) do
		def.tier = tier
		Config.BatById[def.id] = def
	end

	Config.ArmorById = {}
	for tier, def in ipairs(Config.Armor.Tiers) do
		def.tier = tier
		Config.ArmorById[def.id] = def
	end

	--- Where a side track's buy button `slot` stands, in plot-local coordinates.
	---
	--- Component arithmetic on purpose: tools/verify_config.lua stubs Vector3 as a
	--- plain table with no operators, so anything that adds or scales a Vector3 at
	--- require time takes the whole verifier down.
	function Config.trackButtonPosition(track: string, slot: number): Vector3
		local t = Config.Layout.Tracks[track]
		return Vector3.new(t.buttonX, 0, t.firstZ + (slot - 1) * t.spacing)
	end

	--- The cabinet body behind that column: centre, then size. Its long axis is Z,
	--- running the length of its own button column with four studs of overhang at
	--- each end so the case reads as containing the buttons rather than starting
	--- level with them.
	function Config.trackCabinet(track: string): (Vector3, Vector3)
		local t = Config.Layout.Tracks[track]
		local length = (t.slots - 1) * t.spacing + 8
		return Vector3.new(t.cabinetX, 0, t.firstZ + (t.slots - 1) * t.spacing / 2),
			Vector3.new(t.depth, t.height, length)
	end

	--- Shelf slot `slot` on the cabinet — where the display for a bought tier
	--- stands, so the case visibly fills up as you climb the track.
	function Config.trackShelfPosition(track: string, slot: number): Vector3
		local t = Config.Layout.Tracks[track]
		return Vector3.new(t.cabinetX, 5, t.firstZ + (slot - 1) * t.spacing)
	end

	function Config.requirementsOf(def)
		local req = def.requires
		if req == nil then
			return {}
		elseif type(req) == "string" then
			return { req }
		end
		return req
	end

	return Config
end


__MODULES["Fx"] = function()
	--[[
		Fx.lua — every particle / light / sound effect in the game, built from code.

		No asset uploads required: all textures use Roblox's built-in default
		particle sprites (rbxasset://textures/particles/*) which ship with the
		engine and are always available, so nothing here can be moderated away.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Style = Req("Style")
	local Sound = Req("Sound")

	local TweenService = game:GetService("TweenService")
	local Debris = game:GetService("Debris")

	local Fx = {}

	-- Built-in engine textures. These are shipped in the Roblox client itself.
	local SPARKLE = "rbxasset://textures/particles/sparkles_main.dds"
	local SMOKE   = "rbxasset://textures/particles/smoke_main.dds"
	local FIRE    = "rbxasset://textures/particles/fire_main.dds"

	local function emitter(part: BasePart, props: { [string]: any }): ParticleEmitter
		local p = Instance.new("ParticleEmitter")
		p.Name = "TungFx"
		p.Texture = SPARKLE
		p.Lifetime = NumberRange.new(0.4, 0.9)
		p.Rate = 12
		p.Speed = NumberRange.new(1, 3)
		p.SpreadAngle = Vector2.new(180, 180)
		p.LightEmission = 0.6
		p.LockedToPart = false
		for key, value in pairs(props) do
			(p :: any)[key] = value
		end
		p.Parent = part
		return p
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- Per-variant recipes
	-- ─────────────────────────────────────────────────────────────────────────────

	local RECIPES: { [string]: (BasePart, any) -> () } = {}

	RECIPES.none = function() end

	RECIPES.sparkle = function(part, variant)
		emitter(part, {
			Color = ColorSequence.new(variant.accent, variant.wood),
			Size = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 0.5),
				NumberSequenceKeypoint.new(1, 0),
			}),
			Rate = 14,
			Lifetime = NumberRange.new(0.4, 0.8),
		})
	end

	RECIPES.dust = function(part, variant)
		emitter(part, {
			Texture = SMOKE,
			Color = ColorSequence.new(variant.wood),
			Transparency = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 0.5),
				NumberSequenceKeypoint.new(1, 1),
			}),
			Size = NumberSequence.new(1.2),
			Rate = 8,
			Speed = NumberRange.new(0.5, 1.5),
			LightEmission = 0,
		})
	end

	RECIPES.embers = function(part, variant)
		emitter(part, {
			Texture = FIRE,
			Color = ColorSequence.new(Color3.fromRGB(255, 160, 60), variant.wood),
			Size = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 0.8),
				NumberSequenceKeypoint.new(1, 0),
			}),
			Rate = 22,
			Speed = NumberRange.new(2, 5),
			Acceleration = Vector3.new(0, 6, 0),
			Lifetime = NumberRange.new(0.5, 1.1),
			LightEmission = 1,
		})
	end

	RECIPES.pulse = function(part, variant)
		emitter(part, {
			Color = ColorSequence.new(variant.wood),
			Size = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 0),
				NumberSequenceKeypoint.new(0.4, 1.1),
				NumberSequenceKeypoint.new(1, 0),
			}),
			Rate = 26,
			Speed = NumberRange.new(0.5, 2),
			LightEmission = 1,
			LightInfluence = 0,
		})
	end

	RECIPES.void = function(part, variant)
		emitter(part, {
			Color = ColorSequence.new(Color3.fromRGB(160, 80, 255), Color3.fromRGB(30, 0, 60)),
			Size = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 1.4),
				NumberSequenceKeypoint.new(1, 0),
			}),
			Rate = 24,
			Speed = NumberRange.new(-3, -1),  -- negative = sucked inward
			Lifetime = NumberRange.new(0.6, 1.2),
			LightEmission = 1,
			LightInfluence = 0,
		})
	end

	RECIPES.eclipse = function(part, variant)
		RECIPES.embers(part, variant)
		emitter(part, {
			Color = ColorSequence.new(Color3.fromRGB(255, 150, 40)),
			Size = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 0),
				NumberSequenceKeypoint.new(0.5, 2.4),
				NumberSequenceKeypoint.new(1, 0),
			}),
			Transparency = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 0.4),
				NumberSequenceKeypoint.new(1, 1),
			}),
			Rate = 6,
			Speed = NumberRange.new(0, 0.5),
			LightEmission = 1,
			LightInfluence = 0,
		})
	end

	RECIPES.galaxy = function(part, _variant)
		emitter(part, {
			Color = ColorSequence.new({
				ColorSequenceKeypoint.new(0, Color3.fromRGB(120, 160, 255)),
				ColorSequenceKeypoint.new(0.5, Color3.fromRGB(200, 120, 255)),
				ColorSequenceKeypoint.new(1, Color3.fromRGB(255, 255, 255)),
			}),
			Size = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 0.7),
				NumberSequenceKeypoint.new(1, 0),
			}),
			Rate = 40,
			Speed = NumberRange.new(1, 4),
			Rotation = NumberRange.new(0, 360),
			RotSpeed = NumberRange.new(-180, 180),
			Lifetime = NumberRange.new(0.7, 1.4),
			LightEmission = 1,
			LightInfluence = 0,
		})
	end

	RECIPES.infinity = function(part, variant)
		RECIPES.galaxy(part, variant)
		emitter(part, {
			Texture = FIRE,
			Color = ColorSequence.new(Color3.fromRGB(255, 255, 255), Color3.fromRGB(255, 210, 90)),
			Size = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 2.2),
				NumberSequenceKeypoint.new(1, 0),
			}),
			Rate = 30,
			Speed = NumberRange.new(3, 8),
			SpreadAngle = Vector2.new(180, 180),
			Lifetime = NumberRange.new(0.4, 0.9),
			LightEmission = 1,
			LightInfluence = 0,
		})
	end

	--- Applies a variant's signature effect + light to a part.
	--- `opts.light = false` skips the PointLight — important for conveyor drops,
	--- since Roblox only renders a limited number of lights and hundreds of
	--- glowing drops would starve the lights that actually matter.
	--- `opts.rateScale` thins out the particles for the same reason.
	function Fx.applyVariant(part: BasePart, variant, opts)
		opts = opts or {}
		local recipe = RECIPES[variant.fx or "none"] or RECIPES.none
		recipe(part, variant)

		if opts.rateScale then
			for _, child in ipairs(part:GetChildren()) do
				if child:IsA("ParticleEmitter") then
					child.Rate = math.max(1, child.Rate * opts.rateScale)
				end
			end
		end

		if variant.light and opts.light ~= false then
			local light = Instance.new("PointLight")
			light.Color = variant.light.color
			light.Range = variant.light.range
			light.Brightness = variant.light.brightness
			light.Shadows = false
			light.Parent = part
		end
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- One-shot effects
	-- ─────────────────────────────────────────────────────────────────────────────

	--- A quick expanding ring. Used for purchases, upgrades and heavy hits.
	function Fx.burst(position: Vector3, color: Color3, size: number?, parent: Instance?)
		local ring = Instance.new("Part")
		ring.Name = "TungBurst"
		ring.Shape = Enum.PartType.Ball
		ring.Anchored = true
		ring.CanCollide = false
		ring.CanQuery = false
		ring.CanTouch = false
		ring.CastShadow = false
		ring.Material = Enum.Material.Neon
		ring.Color = color
		ring.Transparency = 0.25
		ring.Size = Vector3.one * 0.5
		ring.CFrame = CFrame.new(position)
		ring.Parent = parent or workspace

		local goalSize = Vector3.one * (size or 10)
		TweenService:Create(ring, TweenInfo.new(0.45, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
			Size = goalSize,
			Transparency = 1,
		}):Play()
		Debris:AddItem(ring, 0.6)
	end

	--- Floating "+1.2K" text.
	function Fx.floatingText(position: Vector3, text: string, color: Color3, parent: Instance?)
		local anchor = Instance.new("Part")
		anchor.Name = "TungFloatText"
		anchor.Anchored = true
		anchor.CanCollide = false
		anchor.CanQuery = false
		anchor.CanTouch = false
		anchor.Transparency = 1
		anchor.Size = Vector3.one * 0.2
		anchor.CFrame = CFrame.new(position)
		anchor.Parent = parent or workspace

		-- ONE OF THE TWO THINGS IN THIS GAME THAT DRAWS THROUGH WALLS. A damage
		-- number you can't see is a hit you didn't feel land, and the thing most
		-- likely to be standing between you and it is the enemy you just hit. (The
		-- other is enemy nameplates, and those are Roblox's own — it draws them on
		-- top whatever we ask for.)
		local billboard = Style.billboard(anchor, {
			name = "FloatText", width = 6, height = 2,
			distance = "prop", alwaysOnTop = true,
		})

		local label = Style.text(billboard, { text = text, color = color })

		TweenService:Create(anchor, TweenInfo.new(1.1, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
			CFrame = CFrame.new(position + Vector3.new(0, 6, 0)),
		}):Play()
		TweenService:Create(label, TweenInfo.new(1.1), { TextTransparency = 1, TextStrokeTransparency = 1 }):Play()
		Debris:AddItem(anchor, 1.3)
	end

	--- Procedural "tung" percussion. Generated from engine default sound ids that
	--- ship with Studio, pitched by index so each variant sounds different.
	---
	--- With Config.Prototypes.Sound on, both of these hand off to Sound.lua, which
	--- plays them out of a fixed pool instead of allocating one Sound per drop.
	--- With it off they keep the shipped behaviour exactly, down to the volumes
	--- and roll-off distances — the prototype has to be switchable, not merged.
	local TUNG_SOUND = "rbxasset://sounds/electronicpingshort.wav"
	local IMPACT_SOUND = "rbxasset://sounds/impact_water.mp3"

	function Fx.tung(part: BasePart, pitch: number?, volume: number?)
		if Config.Prototypes.Sound then
			Sound.playAt("collect", part, { pitch = pitch, volume = volume or 0.35 })
			return
		end
		local sound = Instance.new("Sound")
		sound.SoundId = TUNG_SOUND
		sound.PlaybackSpeed = pitch or 1
		sound.Volume = volume or 0.35
		sound.RollOffMaxDistance = 90
		sound.Parent = part
		sound:Play()
		Debris:AddItem(sound, 3)
	end

	function Fx.impact(part: BasePart, pitch: number?)
		if Config.Prototypes.Sound then
			-- combo is passed by callers that track one (bat swings); without it
			-- this is just the pitch they asked for
			Sound.playAt("impact", part, { pitch = pitch, volume = 0.6, rollOff = 120 })
			return
		end
		local sound = Instance.new("Sound")
		sound.SoundId = IMPACT_SOUND
		sound.PlaybackSpeed = pitch or 1
		sound.Volume = 0.6
		sound.RollOffMaxDistance = 120
		sound.Parent = part
		sound:Play()
		Debris:AddItem(sound, 3)
	end

	--- Named passthroughs for the rest of the library, so callers outside Fx do
	--- not have to know the asset keys. All no-ops with the flag off.
	function Fx.sfx(name: string, position: Vector3?, opts)
		if not Config.Prototypes.Sound then
			return
		end
		if position then
			Sound.playAt(name, position, opts)
		else
			Sound.play(name, opts)
		end
	end

	--- Trail between two attachments, used on bats mid-swing.
	function Fx.trail(a0: Attachment, a1: Attachment, color: Color3): Trail
		local trail = Instance.new("Trail")
		trail.Attachment0 = a0
		trail.Attachment1 = a1
		trail.Color = ColorSequence.new(color)
		trail.Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 0.1),
			NumberSequenceKeypoint.new(1, 1),
		})
		trail.Lifetime = 0.22
		trail.LightEmission = 0.8
		trail.MinLength = 0.1
		trail.Enabled = false
		trail.Parent = a0.Parent
		return trail
	end

	return Fx
end


__MODULES["Net"] = function()
	--[[
		Net.lua — lazily creates and hands out the project's RemoteEvents.

		Server calls Net.event("Name") and it is created on demand.
		Client calls Net.event("Name") and it waits for it.
	]]

	local ReplicatedStorage = game:GetService("ReplicatedStorage")
	local RunService = game:GetService("RunService")

	local Net = {}

	local FOLDER_NAME = "TungNet"

	local folder: Folder
	if RunService:IsServer() then
		folder = ReplicatedStorage:FindFirstChild(FOLDER_NAME) :: Folder
		if not folder then
			folder = Instance.new("Folder")
			folder.Name = FOLDER_NAME
			folder.Parent = ReplicatedStorage
		end
	else
		folder = ReplicatedStorage:WaitForChild(FOLDER_NAME, 30) :: Folder
	end

	-- Every remote the game uses. Declared up front so the client never races.
	Net.NAMES = {
		"Notify",        -- S->C  { kind, title, body, color }
		"Stats",         -- S->C  { cash, rebirths, kills, batTier, armorTier, multiplier, owned, rebirthCost }
		"PlotAssigned",  -- S->C  plotIndex
		"Purchased",     -- S->C  { id, name, price }
		-- phase: idle | resting | warning | spawning | active | clear.
		-- `seconds` is sent ONCE per phase and counted down client-side.
		"WaveState",     -- S->C  { phase, wave, remaining, total, seconds, boss, forced }
		"SwingFx",       -- S->C  { character, combo, duration } — play a swing on that rig
		"HitFeedback",   -- S->C  { damage, crit, killed, position }
		"Knockback",     -- S->C  impulse Vector3, applied by the owning client
		"RequestRebirth",-- C->S
		"RequestReset",  -- C->S  (leave plot)
		"Sfx",           -- S->C  { name, position }

		-- PROTOTYPES (see Config.Prototypes). Declared here rather than created on
		-- demand so a client that connects with a flag off still resolves them and
		-- never sits in WaitForChild for 30 seconds.
		"UpgradeState",   -- S->C  { levels = {id = level}, costs = {id = price} }
		"RequestUpgrade", -- C->S  upgrade id
		"UseUtility",     -- C->S  (fire the equipped utility)
		"SessionState",   -- S->C  { daily, playtime, boost, offline }
		"RequestClaim",   -- C->S  { kind = "daily" | "playtime" | "offline", index }
		"RequestBoost",   -- C->S
		"FloorState",     -- S->C  { unlocked = boolean }
	}

	if RunService:IsServer() then
		for _, name in ipairs(Net.NAMES) do
			if not folder:FindFirstChild(name) then
				local remote = Instance.new("RemoteEvent")
				remote.Name = name
				remote.Parent = folder
			end
		end
	end

	local cache: { [string]: RemoteEvent } = {}

	function Net.event(name: string): RemoteEvent
		local hit = cache[name]
		if hit then
			return hit
		end
		local remote
		if RunService:IsServer() then
			remote = folder:FindFirstChild(name)
			if not remote then
				remote = Instance.new("RemoteEvent")
				remote.Name = name
				remote.Parent = folder
			end
		else
			remote = folder:WaitForChild(name, 30)
			if not remote then
				error(("[Tung] remote %q never replicated"):format(name))
			end
		end
		cache[name] = remote
		return remote
	end

	return Net
end


__MODULES["Sound"] = function()
	--[[
		Sound.lua — the whole audio layer, built on sounds that ship INSIDE the
		Roblox client (`rbxasset://sounds/*`). No upload, no moderation queue, and
		nothing here can 404 or be taken down, which is the same contract every
		other asset in this project honours.

		Three rules drive the shape of this file, and all three are failure modes
		rather than preferences:

		  * **Never `Instance.new` a Sound per event.** Around 400 live Sound
		    instances is where audio/video desync starts, and ten plots dropping a
		    Tung every 0.4s reach that inside a minute. Every sound name owns a
		    fixed pool of `Config.Sound.PoolSize` instances handed out round-robin;
		    the 9th overlapping play steals the oldest slot instead of allocating.
		  * **Server-side sound spam can take a 20-player server down.** Anything
		    the client can play for itself, it plays for itself — the server never
		    broadcasts audio it does not have to.
		  * **Everything goes through one SoundGroup.** "There is no way to turn
		    the sound off" is a recurring playtest complaint, and with a group the
		    fix is one property write.

		Gated on `Config.Prototypes.Sound`: with the flag off every entry point
		returns nil before touching a single instance, so a shipping build is
		byte-for-byte the audio it has today.
	]]

	local Req = __Req
	local Config = Req("Config")

	local RunService = game:GetService("RunService")
	local SoundService = game:GetService("SoundService")

	local Sound = {}

	local CFG = Config.Sound
	local GROUP_NAME = "TungSfx"
	local ANCHOR_FOLDER = "TungSfxAnchors"

	local IS_SERVER = RunService:IsServer()

	export type PlayOptions = {
		pitch: number?,       -- multiplies the resolved playback speed
		volume: number?,
		combo: number?,       -- pitch-stacks: 1 + combo * PitchPerCombo, clamped
		rollOff: number?,     -- override RollOffMaxDistance for one play
		looped: boolean?,
	}

	-- ─────────────────────────────────────────────────────────────────────────────
	-- lazily-built plumbing
	-- ─────────────────────────────────────────────────────────────────────────────

	local group: SoundGroup? = nil
	local groupVolume = 1

	--- One group for every sound in the game. Found-or-created rather than always
	--- created: the server's group replicates, so a client that arrives late must
	--- adopt the existing one instead of stacking a second.
	local function soundGroup(): SoundGroup
		if group and group.Parent then
			return group :: SoundGroup
		end
		local existing = SoundService:FindFirstChild(GROUP_NAME)
		if existing and existing:IsA("SoundGroup") then
			group = existing :: SoundGroup
		else
			local made = Instance.new("SoundGroup")
			made.Name = GROUP_NAME
			made.Volume = groupVolume
			made.Parent = SoundService
			group = made
		end
		return group :: SoundGroup
	end

	local anchorFolder: Folder? = nil

	local function anchors(): Folder
		if anchorFolder and anchorFolder.Parent then
			return anchorFolder :: Folder
		end
		local existing = workspace:FindFirstChild(ANCHOR_FOLDER)
		if existing then
			anchorFolder = existing :: Folder
		else
			local made = Instance.new("Folder")
			made.Name = ANCHOR_FOLDER
			made.Parent = workspace
			anchorFolder = made
		end
		return anchorFolder :: Folder
	end

	--- A pooled positional sound needs somewhere permanent to live. Parenting it
	--- to the thing that made the noise looks obvious and is wrong: a drop being
	--- collected destroys its children, so the pool would quietly decay back into
	--- allocate-per-drop. Each slot owns a 0.2-stud invisible anchor we teleport
	--- to the emitter instead.
	local function newAnchor(): BasePart
		local part = Instance.new("Part")
		part.Name = "SfxAnchor"
		part.Anchored = true
		part.CanCollide = false
		part.CanQuery = false
		part.CanTouch = false
		part.CastShadow = false
		part.Locked = true
		part.Transparency = 1
		part.Size = Vector3.one * 0.2
		part.Parent = anchors()
		return part
	end

	type Slot = { sound: Sound, anchor: BasePart? }
	type Pool = { slots: { Slot }, cursor: number, lastPlay: number }

	local pools: { [string]: Pool } = {}
	local warned: { [string]: boolean } = {}

	local function buildPool(name: string, assetId: string, positional: boolean): Pool
		local pool: Pool = { slots = {}, cursor = 0, lastPlay = -math.huge }
		for i = 1, math.max(1, CFG.PoolSize) do
			local sound = Instance.new("Sound")
			sound.Name = ("%s_%d"):format(name, i)
			sound.SoundId = assetId
			sound.SoundGroup = soundGroup()
			sound.Volume = 0.5
			if positional then
				local anchor = newAnchor()
				-- RollOffMaxDistance is the whole reason a neighbour's factory
				-- does not blare across the ring: a plot is ~120 studs wide and
				-- the gap between plots is 44, so 60 studs dies out at the fence.
				sound.RollOffMode = Enum.RollOffMode.InverseTapered
				sound.RollOffMinDistance = 8
				sound.RollOffMaxDistance = CFG.RollOffMaxDistance
				sound.Parent = anchor
				table.insert(pool.slots, { sound = sound, anchor = anchor })
			else
				-- parented to a non-BasePart, a Sound is 2D and plays at full
				-- volume wherever the listener is — which is what UI wants
				sound.Parent = SoundService
				table.insert(pool.slots, { sound = sound })
			end
		end
		return pool
	end

	--- Round-robin, with the repeat-rate guard applied per sound NAME. Two drops
	--- landing in the same frame is one audible "tung", not two stacked into a
	--- clipped mush — and the guard is what stops a ten-plot server machine-gunning
	--- the same 40ms sample.
	---
	--- os.clock() here, not os.time(): this is a sub-second monotonic timer, and
	--- os.time() has 1-second resolution which would silence everything.
	local function acquire(name: string, positional: boolean): Slot?
		local assetId = CFG.Library[name]
		if not assetId then
			if not warned[name] then
				warned[name] = true
				warn(("[Tung] no sound named %q in Config.Sound.Library"):format(name))
			end
			return nil
		end

		local key = name .. (positional and "@3d" or "@2d")
		local pool = pools[key]
		if not pool then
			pool = buildPool(name, assetId, positional)
			pools[key] = pool
		end

		local now = os.clock()
		if now - pool.lastPlay < CFG.MinRepeatSeconds then
			return nil
		end
		pool.lastPlay = now

		pool.cursor = (pool.cursor % #pool.slots) + 1
		return pool.slots[pool.cursor]
	end

	--- `PlaybackSpeed = min(1 + combo * PitchPerCombo, MaxPitch)` — the combo
	--- pitch-stack. Rising pitch on a repeated hit is the single cheapest way to
	--- make one stock sample read as a streak instead of a stutter.
	function Sound.comboPitch(combo: number?): number
		return math.min(1 + (combo or 0) * CFG.PitchPerCombo, CFG.MaxPitch)
	end

	local function resolvePitch(opts: PlayOptions?): number
		local speed = (opts and opts.pitch) or 1
		if opts and opts.combo then
			speed *= Sound.comboPitch(opts.combo)
		end
		return math.clamp(speed, 0.2, CFG.MaxPitch)
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- public
	-- ─────────────────────────────────────────────────────────────────────────────

	--- 2D one-shot: UI clicks, stings, anything that is not happening at a place.
	--- On the client this goes through `PlayLocalSound`, which never replicates and
	--- never asks the server for anything.
	function Sound.play(name: string, opts: PlayOptions?): Sound?
		if not Config.Prototypes.Sound then
			return nil
		end
		local slot = acquire(name, false)
		if not slot then
			return nil
		end

		local sound = slot.sound
		sound.PlaybackSpeed = resolvePitch(opts)
		sound.Volume = (opts and opts.volume) or 0.5
		sound.Looped = (opts and opts.looped) or false

		if IS_SERVER then
			sound:Play()
		else
			SoundService:PlayLocalSound(sound)
		end
		return sound
	end

	--- Positional one-shot at a part or a raw position.
	---
	--- Called from the server this replicates a *bounded* number of instances
	--- (PoolSize per name for the whole server), which is the point: the shipped
	--- code allocates one Sound per drop and lets Debris clean up after it.
	function Sound.playAt(name: string, where: any, opts: PlayOptions?): Sound?
		if not Config.Prototypes.Sound then
			return nil
		end

		local position: Vector3?
		if typeof(where) == "Vector3" then
			position = where
		elseif typeof(where) == "Instance" and where:IsA("BasePart") then
			position = where.Position
		elseif typeof(where) == "CFrame" then
			position = where.Position
		end
		if not position then
			return nil
		end

		local slot = acquire(name, true)
		if not slot or not slot.anchor then
			return nil
		end

		local anchor = slot.anchor :: BasePart
		anchor.CFrame = CFrame.new(position)

		local sound = slot.sound
		sound.PlaybackSpeed = resolvePitch(opts)
		sound.Volume = (opts and opts.volume) or 0.5
		sound.Looped = (opts and opts.looped) or false
		sound.RollOffMaxDistance = (opts and opts.rollOff) or CFG.RollOffMaxDistance
		sound:Play()
		return sound
	end

	--- The mute toggle a HUD checkbox would drive. Volume rather than
	--- SoundGroup.Parent = nil so a muted group still tracks playback position.
	function Sound.setVolume(volume: number)
		groupVolume = math.clamp(volume, 0, 1)
		if Config.Prototypes.Sound then
			soundGroup().Volume = groupVolume
		end
	end

	function Sound.setMuted(muted: boolean)
		Sound.setVolume(muted and 0 or 1)
	end

	function Sound.group(): SoundGroup?
		if not Config.Prototypes.Sound then
			return nil
		end
		return soundGroup()
	end

	--- Warms every pool up front so the first drop of the session is not the one
	--- that pays for eight instantiations. Safe to call more than once.
	function Sound.preload(positional: boolean?)
		if not Config.Prototypes.Sound then
			return
		end
		for name, assetId in pairs(CFG.Library) do
			local wants3d = positional ~= false
			local key = name .. (wants3d and "@3d" or "@2d")
			if not pools[key] then
				pools[key] = buildPool(name, assetId, wants3d)
			end
		end
	end

	return Sound
end


__MODULES["Style"] = function()
	--[[
		Style.lua — the one place that turns Config.Style into instances.

		Every label this game draws, in the world and on the screen, comes through
		here. Before it existed each site picked its own font, its own outline and
		its own view distance as it was written, which is how the plot ended up
		using three fonts, six outline settings and eleven view distances from 90
		studs to 1200 — none of them chosen against each other.

		WHY A MODULE AND NOT JUST CONSTANTS. Constants would have fixed the values
		and left the *shape* free: one site setting LightInfluence and the next
		forgetting, one billboard with StudsOffsetWorldSpace and the next without.
		The point of a builder is that the site cannot leave a field out. What a
		caller still gets to choose is what a label IS — its size, its colour, and
		how far away it stops mattering — and nothing else.

		tools/verify.py fails the build if `Enum.Font`, `TextStrokeTransparency` or
		`MaxDistance` appears anywhere in src/ outside this file. That lint is the
		only reason this stays true; the state it replaced is what happens without
		one.
	]]

	local Req = __Req
	local Config = Req("Config")

	local S = Config.Style

	local Style = {}

	--- The two faces. `title` is the display face — names, headlines, anything you
	--- read at a glance from across the plot. `body` is everything else: prices,
	--- step counters, blurbs, the small print on a panel.
	Style.Font = {
		title = (Enum.Font :: any)[S.TitleFont],
		body  = (Enum.Font :: any)[S.BodyFont],
	}

	--- Named view distances, resolved. Anything that wants a number reads
	--- `Style.distance("prop")` rather than writing 220.
	function Style.distance(tier: string): number
		local value = S.Distance[tier]
		if not value then
			-- Loud rather than silent: a typo'd tier that fell back to a default
			-- would be a label that quietly renders at the wrong range forever,
			-- which is exactly the class of bug this module exists to end.
			error(("[Tung] unknown view-distance tier %q; expected one of machine/prop/plot/world"):format(tostring(tier)), 2)
		end
		return value
	end

	--- A world-space label anchor.
	---
	---   width, height   studs (BillboardGui scale maps 1:1 to studs)
	---   distance        a Config.Style.Distance key
	---   offset          studs straight up from the adornee, world-space
	---   alwaysOnTop     draws through geometry. Two things in this game are
	---                   allowed it — damage numbers and enemy nameplates — and
	---                   the nameplates are Roblox's own. Everything else obeys
	---                   walls, which is the whole point of hiding behind one.
	function Style.billboard(parent: Instance, opts): BillboardGui
		local gui = Instance.new("BillboardGui")
		gui.Name = opts.name or "Label"
		gui.Size = UDim2.fromScale(opts.width, opts.height)
		gui.MaxDistance = Style.distance(opts.distance)
		gui.AlwaysOnTop = opts.alwaysOnTop == true
		gui.LightInfluence = S.LightInfluence
		if opts.offset then
			gui.StudsOffsetWorldSpace = Vector3.new(0, opts.offset, 0)
		end
		gui.Parent = parent
		return gui
	end

	--- A line of world text. Defaults to filling its billboard, because most of
	--- them hold exactly one line; the buy button is the only label with enough to
	--- say that it needs its own layout.
	function Style.text(parent: Instance, opts): TextLabel
		local label = Instance.new("TextLabel")
		label.Name = opts.name or "Text"
		label.BackgroundTransparency = 1
		label.Size = opts.size or UDim2.fromScale(1, 1)
		if opts.position then
			label.Position = opts.position
		end
		label.Font = (opts.weight == "body") and Style.Font.body or Style.Font.title
		label.Text = opts.text or ""
		label.TextColor3 = opts.color or Color3.new(1, 1, 1)
		label.TextStrokeTransparency = S.StrokeTransparency
		label.TextStrokeColor3 = S.StrokeColor
		label.TextScaled = opts.scaled ~= false
		label.Parent = parent
		return label
	end

	--- Retunes a live billboard's view distance. Some labels have more than one
	--- voice — a locked buy button drops out of sight sooner than a buyable one —
	--- and the tier still has to come from here rather than from a number written
	--- at the call site.
	function Style.setDistance(gui: BillboardGui, tier: string)
		gui.MaxDistance = Style.distance(tier)
	end

	--- Fades a label, outline included.
	---
	--- The outline has to fade WITH the text or a dimmed label keeps its hard dark
	--- edge and ends up reading as MORE contrasty than the bright one it was
	--- supposed to recede behind — which is the exact opposite of the point.
	function Style.fade(label: TextLabel, alpha: number)
		label.TextTransparency = alpha
		label.TextStrokeTransparency = alpha + (1 - alpha) * S.StrokeTransparency
	end

	return Style
end


__MODULES["SwingAnim"] = function()
	--[[
		SwingAnim.lua — procedural melee swings that move the CHARACTER, not just
		the bat.

		The old swing tweened Tool.Grip, which is the offset of the engine's
		RightGrip weld. That rotates the bat inside a motionless hand: the arm, the
		shoulders and the torso never moved, so a "swing" read as the bat pivoting
		in mid-air. This drives the rig itself.

		WHY NOT AN AnimationTrack? Roblox animations are uploaded assets. This game
		has zero uploads by design (see README), and an animation asset would also
		have to be authored twice, once per rig type. Writing the joints directly
		costs one PreSimulation connection and works on R6 and R15 from the same
		pose data.

		THE FOUR THINGS THAT MAKE THIS WORK
		  1. We write Motor6D.Transform, not C0. Transform is the channel the
		     Animator itself writes into every frame, so it composes with the
		     playing animation and leaves the rig's rest pose (C0/C1) untouched.
		     Stop writing and Roblox's own Animate script takes the limb straight
		     back over, with no restore step. (C0 is also becoming read-only on
		     character joints under the Avatar Joint Upgrade, so it is a dead end.)
		  2. We write on RunService.PreSimulation, and ONLY there. This is the part
		     that was wrong for the whole first version of this file, which used
		     BindToRenderStep at Enum.RenderPriority.Character + 1 and was
		     consequently a no-op: nothing moved, ever.

		     BindToRenderStep binds to PreRender, and the frame goes

		         PreRender -> render -> PreAnimation -> [Animator writes joint
		         transforms] -> PreSimulation -> [transforms applied to parts]

		     so a PreRender write is overwritten by the Animator later in the same
		     frame and is discarded before it ever reaches a part. PreSimulation is
		     the last Luau event before the batch apply. Enum.RenderPriority is a
		     bare ordering constant with no engine meaning; `Character = 300` does
		     not mark where characters are animated, and reading it that way is
		     what produced the bug. The reasoning was imported from the camera
		     shake in CombatClient, where binding at `RenderPriority.Camera + 1`
		     genuinely does work — because the default camera module really IS a
		     BindToRenderStep binding, so priority ordering applies to it. The
		     Animator is not, so no priority value could ever have won.
		  3. We MULTIPLY into Transform rather than assigning it. Assigning throws
		     away the Animator's pose for that joint, so the arm snaps out of the
		     tool-hold with no blending.
		  4. Poses are expressed in TORSO space, not joint space, and converted per
		     joint by conjugating with that joint's own C0 rotation:

		         Transform = C0.Rotation:Inverse() * Q * C0.Rotation

		     R6 and R15 bake completely different rotations into their shoulder C0s,
		     so a raw joint-space angle that raises an R15 arm forwards swings an R6
		     arm out sideways. Conjugating makes "rotate the arm 90 degrees about
		     the torso's X axis" mean the same thing on both rigs, and means this
		     file never has to know a single rig convention.

		This module runs on the CLIENT ONLY. Motor6D.Transform is not replicated, so
		every client plays every swing locally: the attacker predicts their own on
		Tool.Activated and everyone else plays it from the SwingFx broadcast.
	]]

	local Req = __Req
	local Config = Req("Config")

	local RunService = game:GetService("RunService")

	local SwingAnim = {}

	local ZERO = Vector3.new(0, 0, 0)

	--- Poses are ABSOLUTE torso-space Euler angles in DEGREES: (pitch, yaw, roll),
	--- measured from the rig's bind pose — arms hanging straight down. They are not
	--- offsets from whatever the character is currently doing; see applyJoint.
	---
	--- THE FRAME. A Roblox character faces -Z, up is +Y, and +X is its own right.
	--- Both arms hang along -Y from their shoulder. So for an ARM joint:
	---
	---   pitch    0 = straight down      90 = straight forward (horizontal)
	---          180 = straight up       270 = straight back
	---   roll   +90 = out to the character's RIGHT      -90 = out to its LEFT
	---   yaw        = twist about the limb's own length; unused here
	---
	--- Note "right" and "left" are the CHARACTER's, in torso space, for BOTH arms.
	--- The rotation is applied to each arm identically, so a symmetric two-handed
	--- pose needs the off-arm's roll to reach ACROSS: positive roll swings the left
	--- arm toward the body's centre, negative swings it away. Mirroring the sign,
	--- which is the intuitive thing to write, splays the arms apart instead.
	---
	--- ORDER MATTERS. CFrame.Angles(x, y, z) composes as Rx * Ry * Rz, so roll is
	--- applied first, in the hanging frame, and pitch then swings the result up and
	--- over. Reading a pair as "point the arm here, then rotate to there" is why
	--- these are easier to reason about as a cone than as a direction vector.
	---
	--- For a TORSO joint (R15 Waist, R6 RootJoint) the same frame applies to the
	--- upper body: pitch +  leans BACK, pitch - leans forward, yaw + turns left.
	---
	--- Choreography lives here rather than in Config because these are drawings,
	--- not balance. The timings that damage depends on ARE in Config.
	local function P(arm: Vector3, offArm: Vector3?, torso: Vector3?)
		return { arm = arm, offArm = offArm or ZERO, torso = torso or ZERO }
	end

	--- One entry per step of the combo. `Config.Combat.SwingSteps` (which is
	--- ComboMaxStacks + 1, because stack 0 is the first swing of a chain) selects
	--- among these. Alternating the direction is what makes a chain read as a combo
	--- instead of as the same swing played four times.
	SwingAnim.SWINGS = {
		{   -- 1. overhead diagonal: cocked over the right shoulder, chopped down
		    -- across to the left hip. Wind-up pitch is past 180 so the arm goes up
		    -- and BEHIND; at 158 it was raised up and in FRONT, which reads as
		    -- presenting the bat rather than loading a swing.
			name = "diagonal",
			windUp = P(Vector3.new(200, 0, 35), Vector3.new(30, 0, -20), Vector3.new(-6, -30, 0)),
			strike = P(Vector3.new(60, 0, -45), Vector3.new(20, 0, 25), Vector3.new(-10, 28, 0)),
		},
		{   -- 2. backhand: low across the body on the left, swept up to the right
			name = "backhand",
			windUp = P(Vector3.new(55, 0, -70), Vector3.new(25, 0, 20), Vector3.new(-4, 32, 0)),
			strike = P(Vector3.new(120, 0, 60), Vector3.new(30, 0, -18), Vector3.new(-8, -30, 0)),
		},
		{   -- 3. flat horizontal sweep, right to left. Pitch stays near 90 through
		    -- both poses so the arm stays level and only the roll travels — that
		    -- level arc is what distinguishes it from the two diagonals.
			name = "sweep",
			windUp = P(Vector3.new(95, 0, 75), Vector3.new(28, 0, -22), Vector3.new(0, -38, 0)),
			strike = P(Vector3.new(95, 0, -68), Vector3.new(35, 0, 28), Vector3.new(0, 36, 0)),
		},
		{   -- 4. two-handed overhead slam; the combo finisher. Both rolls are
		    -- POSITIVE so the off-arm reaches across to meet the bat instead of
		    -- splaying away from it, and the torso leans back to load and forward
		    -- to land — which is the way round it was NOT written the first time.
			name = "slam",
			windUp = P(Vector3.new(196, 0, 6), Vector3.new(190, 0, 20), Vector3.new(16, 0, 0)),
			strike = P(Vector3.new(58, 0, -4), Vector3.new(62, 0, 12), Vector3.new(-24, 0, 0)),
		},
	}

	-- The server times its hitbox off the same two numbers, so they live in Config
	-- rather than here. If they drift apart, damage stops landing when the bat
	-- looks like it connects.
	assert(#SwingAnim.SWINGS == Config.Combat.SwingSteps,
		"SwingAnim.SWINGS and Config.Combat.SwingSteps disagree; the combo would repeat a swing")

	local active: { [Model]: any } = {}
	local bound = false

	local function angles(v: Vector3): CFrame
		return CFrame.Angles(math.rad(v.X), math.rad(v.Y), math.rad(v.Z))
	end

	--- A rig joint by name, accepting either class.
	---
	--- R15 characters are migrating from Motor6D to AnimationConstraint under the
	--- Avatar Joint Upgrade, and an upgraded character has no Motor6Ds at all.
	--- Both classes carry C0 and Transform with the same meaning, so everything
	--- here works on either — but only if we never filter on Motor6D. The name
	--- check alone is not enough: a rig part can hold other children.
	local function jointNamed(parent: Instance?, name: string): Instance?
		local joint = parent and parent:FindFirstChild(name)
		if joint and (joint:IsA("Motor6D") or joint:IsA("AnimationConstraint")) then
			return joint
		end
		return nil
	end

	--- The rig's joints, found once per swing. Named by ROLE, not by rig: `arm` is
	--- whichever joint swings the weapon, `torso` is whichever one twists the upper
	--- body relative to the root.
	local function jointsFor(character: Model)
		local humanoid = character:FindFirstChildOfClass("Humanoid")
		if not humanoid then
			return nil
		end

		if humanoid.RigType == Enum.HumanoidRigType.R6 then
			local torso = character:FindFirstChild("Torso")
			local rootPart = character:FindFirstChild("HumanoidRootPart")
			if not torso or not rootPart then
				return nil
			end
			return {
				arm = jointNamed(torso, "Right Shoulder"),
				offArm = jointNamed(torso, "Left Shoulder"),
				-- R6 has no waist. RootJoint is the closest thing, but it is NOT
				-- equivalent to R15's Waist: every R6 limb joint hangs off the
				-- Torso, so a rotation here carries the arms, legs and head with
				-- it and the character bodily leans rather than twisting at the
				-- middle. Yaw only, and damped — that reads as a shoulder turn,
				-- where the raw pose would swing the feet.
				torso = jointNamed(rootPart, "RootJoint"),
				torsoGain = Vector3.new(0, 0.45, 0),
			}
		end

		local rightUpperArm = character:FindFirstChild("RightUpperArm")
		local leftUpperArm = character:FindFirstChild("LeftUpperArm")
		local upperTorso = character:FindFirstChild("UpperTorso")
		return {
			arm = jointNamed(rightUpperArm, "RightShoulder"),
			offArm = jointNamed(leftUpperArm, "LeftShoulder"),
			-- R15's Waist joins LowerTorso to UpperTorso, so the legs stay put
			torso = jointNamed(upperTorso, "Waist"),
			torsoGain = Vector3.new(1, 1, 1),
		}
	end

	--- Blend a joint from whatever the Animator put there this frame toward an
	--- absolute torso-space pose. See the header: conjugating by the joint's own
	--- C0 rotation is what makes one set of angles work on both rigs.
	---
	--- `state` carries, per joint, the Transform we wrote last frame and the pose
	--- we blended from. That pair is what stops the pose drifting. Normally the
	--- Animator resets Transform before every PreSimulation, so `current` is a
	--- fresh pose and there is nothing to undo — but it does NOT reset when the
	--- Animator is throttled (it reuses the previous frame's pose for distant
	--- characters, see Animator.EvaluationThrottled) or when no track is playing at
	--- all. In those frames Transform is still exactly what we wrote, so without
	--- this check a partial-weight blend would creep toward the target a little
	--- more every frame and the pose would slowly overshoot into a pose we never
	--- authored.
	local function applyJoint(state, joint: Instance?, rotation: Vector3, weight: number)
		if not joint or not joint.Parent then
			return
		end

		local current = (joint :: any).Transform
		if state.written[joint] == current then
			current = state.baseline[joint]
		end
		state.baseline[joint] = current

		-- BLEND toward the pose, do not stack onto it. Multiplying our rotation
		-- into the Animator's looks right until you remember the tool-hold has
		-- already raised the right arm about 90 degrees forward: a 200-degree
		-- wind-up then becomes 290 and the bat starts somewhere behind the
		-- character's back. Poses are absolute, so the Animator's contribution is
		-- what we blend FROM, not something we add to.
		--
		-- Lerping also makes the weight envelope do the whole job of easing in and
		-- out: at weight 0 this is exactly the Animator's pose, so a swing can
		-- start and end without a pop and without ever needing to restore anything.
		local basis = (joint :: any).C0.Rotation
		local target = basis:Inverse() * angles(rotation) * basis
		local result = current:Lerp(target, weight)
		;(joint :: any).Transform = result
		state.written[joint] = result
	end

	local function lerpPose(a, b, alpha: number)
		return {
			arm = a.arm:Lerp(b.arm, alpha),
			offArm = a.offArm:Lerp(b.offArm, alpha),
			torso = a.torso:Lerp(b.torso, alpha),
		}
	end

	local REST = P(ZERO, ZERO, ZERO)

	--- Where the rig should be, `t` seconds into a swing of length `duration`.
	--- Returns the pose plus a blend weight that fades the whole thing in over the
	--- first few frames and out over the tail, so nothing pops when Roblox's own
	--- animation takes the limbs back.
	local function evaluate(swing, t: number, duration: number)
		local f = math.clamp(t / duration, 0, 1)
		local windUpEnd = Config.Combat.SwingWindUp
		local strikeEnd = Config.Combat.SwingStrikeAt

		local pose
		if f < windUpEnd then
			-- decelerating into the top of the wind-up
			local a = f / windUpEnd
			pose = lerpPose(REST, swing.windUp, 1 - (1 - a) * (1 - a))
		elseif f < strikeEnd then
			-- accelerating through the strike: this is the fast part
			local a = (f - windUpEnd) / (strikeEnd - windUpEnd)
			pose = lerpPose(swing.windUp, swing.strike, a * a)
		else
			-- HOLD the strike and let the weight envelope carry the arm back into
			-- whatever the Animator is doing. This used to lerp the pose toward
			-- REST, which is the bind pose — arms hanging at the sides — so at full
			-- weight the arm was driven down to the hip and then snapped back up to
			-- the tool-hold as the weight finally released. That was the odd ending.
			pose = swing.strike
		end

		-- The weight envelope does all the easing in and out of the Animator's
		-- pose, so it has to reach 1 before the strike and be back at 0 by the end.
		local weight
		local riseEnd = windUpEnd * 0.6
		if f < riseEnd then
			local a = f / riseEnd
			weight = a * a
		elseif f < strikeEnd then
			weight = 1
		else
			local a = (f - strikeEnd) / (1 - strikeEnd)
			weight = (1 - a) * (1 - a)
		end
		return pose, weight
	end

	--- Start (or restart) a swing on `character`.
	function SwingAnim.play(character: Model?, comboIndex: number, duration: number)
		if not character or not character.Parent then
			return
		end
		local swing = SwingAnim.SWINGS[((comboIndex - 1) % #SwingAnim.SWINGS) + 1]
		if not swing then
			return
		end
		active[character] = {
			swing = swing,
			joints = jointsFor(character),
			elapsed = 0,
			duration = math.max(0.15, duration),
			freeze = 0,
			-- per-joint memory of what we wrote and what we layered onto; see
			-- applyJoint for why both are needed
			written = {},
			baseline = {},
		}
	end

	--- Freeze the pose for a moment. Called on a landed hit: stopping the arc dead
	--- for two or three frames is most of what makes a hit feel like it connected
	--- with something solid rather than passing through it.
	function SwingAnim.hitStop(character: Model?, seconds: number?)
		local entry = character and active[character]
		if entry then
			entry.freeze = math.max(entry.freeze, seconds or 0.07)
		end
	end

	function SwingAnim.stop(character: Model?)
		if character then
			active[character] = nil
		end
	end

	local function step(dt: number)
		for character, entry in pairs(active) do
			if not character.Parent then
				active[character] = nil
			else
				if entry.freeze > 0 then
					entry.freeze -= dt
				else
					entry.elapsed += dt
				end

				if entry.elapsed >= entry.duration then
					active[character] = nil
				else
					local joints = entry.joints
					if not joints or not joints.arm or not joints.arm.Parent then
						-- the character can respawn mid-swing
						joints = jointsFor(character)
						entry.joints = joints
					end
					if joints then
						local pose, weight = evaluate(entry.swing, entry.elapsed, entry.duration)
						applyJoint(entry, joints.arm, pose.arm, weight)
						applyJoint(entry, joints.offArm, pose.offArm, weight)
						applyJoint(entry, joints.torso, pose.torso * (joints.torsoGain or ZERO), weight * 0.8)
					end
				end
			end
		end
	end

	function SwingAnim.start()
		if bound then
			return
		end
		bound = true
		-- PreSimulation, and nothing else. See the header: this is the last Luau
		-- event before Motor6D transforms are applied to part CFrames, and the
		-- first one after the Animator has written its own. A render-step binding
		-- here does nothing at all — that was the original bug.
		--
		-- Do NOT "modernise" this to its deprecated alias Stepped. PreSimulation
		-- passes (deltaTime); Stepped passes (timeSinceStart, deltaTime). With
		-- Stepped, `step` would take the elapsed run time as its dt and every swing
		-- would blow past its duration on the first frame — invisible again, for a
		-- completely different reason.
		RunService.PreSimulation:Connect(step)
	end

	return SwingAnim
end


__MODULES["TungModels"] = function()
	--[[
		TungModels.lua — procedural Tung Tung Tung Sahur models.

		Everything here is built from primitives at runtime. That means:
		  * zero dependency on toolbox / free models that can vanish or be moderated
		  * every variant is a parameter change, not a new upload
		  * the whole game is one Rojo sync away from running

		The silhouette: a wooden baseball bat standing on two skinny legs, with
		stick arms, an angry face, and (usually) a smaller bat in one hand.

		Facing convention: the face points along -Z, which matches Roblox's
		CFrame.LookVector and Enum.NormalId.Front.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Style = Req("Style")
	local Util = Req("Util")
	local Fx = Req("Fx")

	local TungModels = {}

	local HALF_PI = math.pi / 2

	local function variantOf(name: string)
		return Config.Variants[name] or Config.Variants.classic
	end

	local function part(parent: Instance, name: string, size: Vector3, cf: CFrame, color: Color3, material: Enum.Material): Part
		local p = Instance.new("Part")
		p.Name = name
		p.Size = size
		p.CFrame = cf
		p.Color = color
		p.Material = material
		p.Anchored = true
		p.CanCollide = false
		p.CanQuery = false
		p.CanTouch = false
		p.CastShadow = false
		p.TopSurface = Enum.SurfaceType.Smooth
		p.BottomSurface = Enum.SurfaceType.Smooth
		p.Parent = parent
		return p
	end

	--- Vertical cylinder helper (Roblox cylinders run along X, so we spin them).
	local function cylinder(parent, name, height, diameter, cf, color, material): Part
		local p = part(parent, name, Vector3.new(height, diameter, diameter), cf * CFrame.Angles(0, 0, HALF_PI), color, material)
		p.Shape = Enum.PartType.Cylinder
		return p
	end

	local function ball(parent, name, diameter, cf, color, material): Part
		local p = part(parent, name, Vector3.one * diameter, cf, color, material)
		p.Shape = Enum.PartType.Ball
		return p
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- The face — drawn with a SurfaceGui so it costs no extra physics parts.
	-- ─────────────────────────────────────────────────────────────────────────────

	local function circle(parent: Instance, size: UDim2, pos: UDim2, color: Color3, z: number): Frame
		local f = Instance.new("Frame")
		f.Size = size
		f.Position = pos
		f.AnchorPoint = Vector2.new(0.5, 0.5)
		f.BackgroundColor3 = color
		f.BorderSizePixel = 0
		f.ZIndex = z
		f.Parent = parent
		local corner = Instance.new("UICorner")
		corner.CornerRadius = UDim.new(1, 0)
		corner.Parent = f
		return f
	end

	--- Angry sahur face: wide eyes, hard brows, gritted mouth.
	function TungModels.paintFace(facePlate: BasePart, variant, mood: string?, maxDistance: number?)
		mood = mood or "angry"

		local gui = Instance.new("SurfaceGui")
		gui.Name = "Face"
		gui.Face = Enum.NormalId.Front
		gui.CanvasSize = Vector2.new(200, 200)
		gui.SizingMode = Enum.SurfaceGuiSizingMode.FixedSize
		gui.LightInfluence = Config.Style.LightInfluence
		gui.AlwaysOnTop = false
		-- A face is the most expensive label on screen — sixteen frames apiece, one
		-- per Tung on the belt — and the default used to be 0, which in
		-- SurfaceGui.MaxDistance means "never stop drawing". The arena statue and
		-- every raider inherited that. Callers that know better still pass their
		-- own (drops use `machine`); everything else gets the range at which a face
		-- has stopped being a face.
		gui.MaxDistance = maxDistance or Style.distance("plot")
		gui.Parent = facePlate

		local root = Instance.new("Frame")
		root.Size = UDim2.fromScale(1, 1)
		root.BackgroundTransparency = 1
		root.Parent = gui

		local dark = Color3.fromRGB(12, 10, 14)

		-- eye whites
		circle(root, UDim2.fromScale(0.30, 0.30), UDim2.fromScale(0.31, 0.40), variant.eye, 2)
		circle(root, UDim2.fromScale(0.30, 0.30), UDim2.fromScale(0.69, 0.40), variant.eye, 2)
		-- pupils
		circle(root, UDim2.fromScale(0.13, 0.15), UDim2.fromScale(0.33, 0.42), dark, 3)
		circle(root, UDim2.fromScale(0.13, 0.15), UDim2.fromScale(0.67, 0.42), dark, 3)
		-- glint
		circle(root, UDim2.fromScale(0.05, 0.05), UDim2.fromScale(0.30, 0.38), Color3.new(1, 1, 1), 4)
		circle(root, UDim2.fromScale(0.05, 0.05), UDim2.fromScale(0.64, 0.38), Color3.new(1, 1, 1), 4)

		if mood == "angry" then
			for i, x in ipairs({ 0.31, 0.69 }) do
				local brow = Instance.new("Frame")
				brow.Size = UDim2.fromScale(0.30, 0.075)
				brow.Position = UDim2.fromScale(x, 0.245)
				brow.AnchorPoint = Vector2.new(0.5, 0.5)
				brow.BackgroundColor3 = variant.accent
				brow.BorderSizePixel = 0
				brow.Rotation = (i == 1) and 16 or -16
				brow.ZIndex = 5
				brow.Parent = root
				Util.roundedFrame(brow, 6)
			end
		end

		-- mouth
		local mouth = Instance.new("Frame")
		mouth.Size = UDim2.fromScale(0.42, 0.16)
		mouth.Position = UDim2.fromScale(0.5, 0.70)
		mouth.AnchorPoint = Vector2.new(0.5, 0.5)
		mouth.BackgroundColor3 = dark
		mouth.BorderSizePixel = 0
		mouth.ZIndex = 2
		mouth.Parent = root
		Util.roundedFrame(mouth, 10)

		-- teeth
		for i = 0, 3 do
			local tooth = Instance.new("Frame")
			tooth.Size = UDim2.fromScale(0.075, 0.075)
			tooth.Position = UDim2.fromScale(0.325 + i * 0.117, 0.665)
			tooth.AnchorPoint = Vector2.new(0.5, 0.5)
			tooth.BackgroundColor3 = Color3.fromRGB(245, 245, 240)
			tooth.BorderSizePixel = 0
			tooth.ZIndex = 3
			tooth.Parent = root
		end

		return gui
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- Bat body (no face) — reused by the character, the weapon, and props.
	-- ─────────────────────────────────────────────────────────────────────────────

	--- Builds a bat aligned along +Y, centred at `origin`. Returns the barrel part.
	---
	--- The shape is deliberately five explicit parts rather than a sampled profile.
	--- A continuously tapered version was built and reverted: it satisfied every
	--- assertion written for it and still did not look right, which is the whole
	--- reason the shape lives in code you can see rather than in data you can only
	--- check.
	function TungModels.buildBatBody(parent: Instance, variantName: string, s: number, origin: CFrame): (Part, Part)
		local v = variantOf(variantName)
		s = s * (v.scale or 1)

		cylinder(parent, "Knob", 0.22 * s, 0.62 * s, origin * CFrame.new(0, -1.55 * s, 0), v.accent, v.material)
		local handle = cylinder(parent, "Handle", 1.50 * s, 0.44 * s, origin * CFrame.new(0, -0.75 * s, 0), v.accent, v.material)
		cylinder(parent, "Taper", 0.55 * s, 0.80 * s, origin * CFrame.new(0, 0.20 * s, 0), v.wood, v.material)
		local barrel = cylinder(parent, "Barrel", 2.05 * s, 1.34 * s, origin * CFrame.new(0, 1.45 * s, 0), v.wood, v.material)
		ball(parent, "Cap", 1.34 * s, origin * CFrame.new(0, 2.45 * s, 0), v.wood, v.material)

		-- wood grain rings
		for i = 1, 3 do
			local ring = cylinder(parent, "Grain" .. i, 0.06 * s, 1.37 * s,
				origin * CFrame.new(0, (0.85 + i * 0.42) * s, 0), v.accent, v.material)
			ring.Transparency = 0.35
		end

		return barrel, handle
	end

	--- A bat's extents at scale 1, measured off the parts buildBatBody actually
	--- emits: the knob's underside at -1.55 - 0.22/2, the cap's crown at
	--- 2.45 + 1.34/2. Anything that has to span or sit against a bat derives from
	--- these rather than restating a number that will not be updated with them.
	TungModels.BAT_BASE = -1.66
	TungModels.BAT_TOP = 3.12
	TungModels.BAT_LENGTH = TungModels.BAT_TOP - TungModels.BAT_BASE

	--- The barrel's radius at the local +Y offset `y`, in studs at the same scale.
	--- The barrel is a constant 1.34 across the whole face-plate region, so `y` is
	--- unused today — it is in the signature because the caller's question is "how
	--- wide is the body HERE", and the day the barrel stops being constant that is
	--- the question that still needs answering.
	function TungModels.batRadiusAt(y: number, s: number): number
		return 1.34 * s / 2
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- Full character
	-- ─────────────────────────────────────────────────────────────────────────────

	export type BuildOptions = {
		scale: number?,
		anchored: boolean?,
		withEffects: boolean?,
		holdBat: boolean?,
		mood: string?,
		collide: boolean?,
	}

	--- The full Tung Tung Tung Sahur guy. PrimaryPart is `Core` at the model centre.
	function TungModels.build(variantName: string, opts: BuildOptions?): Model
		local o = opts or {}
		local v = variantOf(variantName)
		local s = (o.scale or 1) * (v.scale or 1)

		local model = Instance.new("Model")
		model.Name = "Tung_" .. variantName

		-- invisible physics core, sized to the whole silhouette
		local core = Instance.new("Part")
		core.Name = "Core"
		core.Size = Vector3.new(1.6 * s, 3.4 * s, 1.6 * s)
		core.CFrame = CFrame.new(0, 0, 0)
		core.Transparency = 1
		core.Anchored = true
		core.CanCollide = o.collide ~= false
		core.CanQuery = true
		core.CanTouch = true
		core.CustomPhysicalProperties = PhysicalProperties.new(0.7, 0.35, 0.2, 1, 1)
		core.Parent = model
		model.PrimaryPart = core

		local origin = CFrame.new(0, 0, 0)

		-- legs
		for i, sign in ipairs({ -1, 1 }) do
			local hip = origin * CFrame.new(sign * 0.34 * s, -2.15 * s, 0)
			local leg = cylinder(model, "Leg" .. i, 1.25 * s, 0.26 * s, hip, v.accent, Enum.Material.SmoothPlastic)
			leg.Color = Color3.fromRGB(232, 214, 186)
			local foot = part(model, "Foot" .. i, Vector3.new(0.52 * s, 0.24 * s, 0.92 * s),
				origin * CFrame.new(sign * 0.34 * s, -2.85 * s, -0.18 * s), Color3.fromRGB(60, 48, 40), Enum.Material.SmoothPlastic)
			local c = Instance.new("SpecialMesh")
			c.MeshType = Enum.MeshType.Sphere
			c.Scale = Vector3.new(1, 0.9, 1)
			c.Parent = foot
		end

		-- body
		local barrel = TungModels.buildBatBody(model, variantName, o.scale or 1, origin)

		-- Face plate, set 0.01 studs into the barrel so its 0.08 of depth leaves the
		-- front surface standing proud. Derived from the barrel's radius rather
		-- than written as the literal -0.66 it evaluates to: the two agree today
		-- only because the barrel is 1.34, and the literal would not notice if it
		-- stopped being.
		local faceY = 1.62 * s
		local faceRadius = TungModels.batRadiusAt(faceY, s)
		local face = part(model, "FacePlate", Vector3.new(1.16 * s, 1.16 * s, 0.08 * s),
			origin * CFrame.new(0, faceY, -(faceRadius - 0.01 * s)), v.wood, v.material)
		face.Transparency = 1
		TungModels.paintFace(face, v, o.mood)

		-- Arms. The RIGHT one — the one holding the bat — is built into its own
		-- sub-model so it can hang off a Motor6D instead of being welded rigidly to
		-- the body. Without that joint there is no way to raise a raider's bat:
		-- the R6 rig underneath is entirely invisible, so animating its shoulder
		-- rotates a stick nobody can see.
		local rightArm = Instance.new("Model")
		rightArm.Name = "RightArm"
		rightArm.Parent = model

		local shoulderCF, armRoot
		for _, sign in ipairs({ -1, 1 }) do
			local parent = (sign > 0) and rightArm or model
			local shoulder = origin * CFrame.new(sign * 0.72 * s, 1.15 * s, 0) * CFrame.Angles(0, 0, math.rad(sign * -34))
			local arm = cylinder(parent, "Arm", 1.30 * s, 0.22 * s, shoulder * CFrame.new(0, -0.55 * s, 0),
				Color3.fromRGB(232, 214, 186), Enum.Material.SmoothPlastic)
			arm.Name = (sign < 0) and "ArmLeft" or "ArmRight"
			local hand = ball(parent, "Hand", 0.34 * s,
				shoulder * CFrame.new(0, -1.25 * s, 0), Color3.fromRGB(240, 226, 200), Enum.Material.SmoothPlastic)
			hand.Name = (sign < 0) and "HandLeft" or "HandRight"

			if sign > 0 then
				shoulderCF = shoulder
				armRoot = arm
				-- the held bat rides with the arm, so it goes in the same sub-model
				if o.holdBat ~= false then
					local grip = CFrame.new(hand.Position) * CFrame.Angles(math.rad(-58), 0, math.rad(-18))
					TungModels.buildBatBody(rightArm, variantName, 0.34 * (o.scale or 1), grip * CFrame.new(0, 0.55 * s, 0))
				end
			end
		end

		-- signature effects
		if o.withEffects ~= false then
			Fx.applyVariant(barrel, v)
		end

		-- Assemble. Everything is welded rigidly to the core except the right arm,
		-- whose parts weld to each other and then join the body on one Motor6D —
		-- the only articulated joint on the visible model.
		for _, p in ipairs(model:GetDescendants()) do
			if p:IsA("BasePart") and p ~= core and p ~= armRoot then
				p.Anchored = true
				Util.weld(p:IsDescendantOf(rightArm) and armRoot or core, p)
			end
		end

		if armRoot then
			armRoot.Anchored = true
			local joint = Instance.new("Motor6D")
			joint.Name = "TungArm"
			joint.Part0 = core
			joint.Part1 = armRoot
			-- Pivot at the shoulder. Both C-frames are expressed relative to the
			-- same world point, so an identity Transform reproduces the pose the
			-- parts were built in.
			joint.C0 = core.CFrame:Inverse() * shoulderCF
			joint.C1 = armRoot.CFrame:Inverse() * shoulderCF
			joint.Parent = core
		end

		if not o.anchored then
			for _, p in ipairs(model:GetDescendants()) do
				if p:IsA("BasePart") then
					p.Anchored = false
				end
			end
		end

		model:SetAttribute("Variant", variantName)
		return model
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- Conveyor drop — deliberately cheap (2 physics parts) because there can be
	-- hundreds of these alive at once.
	-- ─────────────────────────────────────────────────────────────────────────────

	function TungModels.buildDrop(variantName: string, scale: number?): Model
		local v = variantOf(variantName)
		local s = (scale or 0.5) * (v.scale or 1)

		local model = Instance.new("Model")
		model.Name = "Drop"

		local body = Instance.new("Part")
		body.Name = "Body"
		body.Shape = Enum.PartType.Cylinder
		body.Size = Vector3.new(2.4 * s, 1.15 * s, 1.15 * s)
		body.Color = v.wood
		body.Material = v.material
		body.Anchored = false
		body.CanCollide = true
		body.CastShadow = false
		body.TopSurface = Enum.SurfaceType.Smooth
		body.BottomSurface = Enum.SurfaceType.Smooth
		body.CustomPhysicalProperties = PhysicalProperties.new(0.6, 0.4, 0.1, 1, 1)
		body.CFrame = CFrame.Angles(0, 0, HALF_PI)
		body.Parent = model
		model.PrimaryPart = body

		local face = Instance.new("Part")
		face.Name = "FacePlate"
		face.Size = Vector3.new(0.95 * s, 0.95 * s, 0.06)
		face.Transparency = 1
		face.CanCollide = false
		face.CanQuery = false
		face.CanTouch = false
		face.CastShadow = false
		face.Massless = true
		face.CFrame = body.CFrame * CFrame.Angles(0, 0, -HALF_PI) * CFrame.new(0, 0.55 * s, -0.58 * s)
		face.Parent = model
		TungModels.paintFace(face, v, "angry", Style.distance("machine"))
		Util.weld(body, face)

		if v.fx and v.fx ~= "none" then
			-- no PointLight and fewer particles: there can be hundreds of these
			Fx.applyVariant(body, v, { light = false, rateScale = 0.35 })
		end

		model:SetAttribute("Variant", variantName)
		return model
	end

	--- The world CFrame a drop should be locked to so it rides the belt upright
	--- and looking back at whoever is walking alongside it.
	function TungModels.dropOrientation(beltDirection: Vector3): CFrame
		local look = CFrame.lookAt(Vector3.zero, -beltDirection.Unit)
		return look * CFrame.Angles(0, 0, HALF_PI)
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- NPC rig — a real R6 Humanoid so pathfinding, MoveTo and damage all work,
	-- with the Tung visual welded on top of invisible limbs.
	-- ─────────────────────────────────────────────────────────────────────────────

	local function rigPart(model: Model, name: string, size: Vector3, cf: CFrame): Part
		local p = Instance.new("Part")
		p.Name = name
		p.Size = size
		p.CFrame = cf
		p.Transparency = 1
		p.Anchored = false
		p.CanCollide = false
		p.CastShadow = false
		p.TopSurface = Enum.SurfaceType.Smooth
		p.BottomSurface = Enum.SurfaceType.Smooth
		p.Parent = model
		return p
	end

	local function motor(parent: BasePart, part0: BasePart, part1: BasePart, name: string, c0: CFrame, c1: CFrame): Motor6D
		local m = Instance.new("Motor6D")
		m.Name = name
		m.Part0 = part0
		m.Part1 = part1
		m.C0 = c0
		m.C1 = c1
		m.Parent = parent
		return m
	end

	export type NPCOptions = {
		scale: number?,
		health: number?,
		walkSpeed: number?,
		displayName: string?,
		boss: boolean?,
	}

	function TungModels.buildNPC(variantName: string, opts: NPCOptions?): Model
		local o = opts or {}
		local scale = o.scale or 1

		local model = Instance.new("Model")
		model.Name = o.displayName or ("Sahur Raider (" .. variantName .. ")")

		local base = CFrame.new(0, 0, 0)

		local hrp = rigPart(model, "HumanoidRootPart", Vector3.new(2, 2, 1) * scale, base)
		hrp.CanCollide = false

		local torso = rigPart(model, "Torso", Vector3.new(2, 2, 1) * scale, base)
		local head = rigPart(model, "Head", Vector3.new(1.2, 1.2, 1.2) * scale, base * CFrame.new(0, 1.5 * scale, 0))
		local la = rigPart(model, "Left Arm", Vector3.new(1, 2, 1) * scale, base * CFrame.new(-1.5 * scale, 0, 0))
		local ra = rigPart(model, "Right Arm", Vector3.new(1, 2, 1) * scale, base * CFrame.new(1.5 * scale, 0, 0))
		local ll = rigPart(model, "Left Leg", Vector3.new(1, 2, 1) * scale, base * CFrame.new(-0.5 * scale, -2 * scale, 0))
		local rl = rigPart(model, "Right Leg", Vector3.new(1, 2, 1) * scale, base * CFrame.new(0.5 * scale, -2 * scale, 0))

		-- an R6 Humanoid stands on its Torso + Legs; without collision here the
		-- raider sinks through the floor on spawn.
		torso.CanCollide = true
		ll.CanCollide = true
		rl.CanCollide = true

		motor(hrp, hrp, torso, "RootJoint", CFrame.new(0, 0, 0) * CFrame.Angles(-HALF_PI, 0, math.pi), CFrame.new(0, 0, 0) * CFrame.Angles(-HALF_PI, 0, math.pi))
		motor(torso, torso, head, "Neck", CFrame.new(0, 1 * scale, 0) * CFrame.Angles(-HALF_PI, 0, math.pi), CFrame.new(0, -0.5 * scale, 0) * CFrame.Angles(-HALF_PI, 0, math.pi))
		motor(torso, torso, la, "Left Shoulder", CFrame.new(-1 * scale, 0.5 * scale, 0) * CFrame.Angles(0, -HALF_PI, 0), CFrame.new(0.5 * scale, 0.5 * scale, 0) * CFrame.Angles(0, -HALF_PI, 0))
		motor(torso, torso, ra, "Right Shoulder", CFrame.new(1 * scale, 0.5 * scale, 0) * CFrame.Angles(0, HALF_PI, 0), CFrame.new(-0.5 * scale, 0.5 * scale, 0) * CFrame.Angles(0, HALF_PI, 0))
		motor(torso, torso, ll, "Left Hip", CFrame.new(-1 * scale, -1 * scale, 0) * CFrame.Angles(0, -HALF_PI, 0), CFrame.new(-0.5 * scale, 1 * scale, 0) * CFrame.Angles(0, -HALF_PI, 0))
		motor(torso, torso, rl, "Right Hip", CFrame.new(1 * scale, -1 * scale, 0) * CFrame.Angles(0, HALF_PI, 0), CFrame.new(0.5 * scale, 1 * scale, 0) * CFrame.Angles(0, HALF_PI, 0))

		-- the visible guy
		local visual = TungModels.build(variantName, {
			scale = scale * 0.95,
			anchored = false,
			withEffects = true,
			holdBat = true,
			collide = false,
		})
		visual.Name = "Visual"
		local core = visual.PrimaryPart :: BasePart
		core.CanCollide = false
		core.CanQuery = false
		core.CanTouch = false
		for _, p in ipairs(visual:GetDescendants()) do
			if p:IsA("BasePart") then
				p.Massless = true
				p.CanCollide = false
			end
		end
		visual:PivotTo(torso.CFrame * CFrame.new(0, 0.7 * scale, 0))
		visual.Parent = model

		-- Motor6D (not a weld) so we can waddle it from code
		local sway = motor(torso, torso, core, "TungSway",
			CFrame.new(0, 0.7 * scale, 0), CFrame.new(0, 0, 0))
		sway.Name = "TungSway"

		local humanoid = Instance.new("Humanoid")
		humanoid.RigType = Enum.HumanoidRigType.R6
		humanoid.MaxHealth = o.health or 100
		humanoid.Health = o.health or 100
		humanoid.WalkSpeed = o.walkSpeed or 13
		humanoid.HipHeight = 0
		humanoid.AutoRotate = true
		humanoid.BreakJointsOnDeath = false
		humanoid.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.Viewer
		humanoid.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOn
		humanoid.NameDisplayDistance = 120
		humanoid.HealthDisplayDistance = 120
		humanoid.Parent = model

		model.PrimaryPart = hrp
		model:SetAttribute("Variant", variantName)
		model:SetAttribute("IsSahurNPC", true)
		if o.boss then
			model:SetAttribute("IsBoss", true)
		end

		return model
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- Weapon
	-- ─────────────────────────────────────────────────────────────────────────────

	--- How the Tool's visible bat sits relative to its Handle box. Named because
	--- the trail attachments have to span exactly this.
	local DECO_SCALE = 0.72
	local DECO_ORIGIN_Y = 1.9

	--- Builds the Handle part + decoration for a bat Tool.
	function TungModels.buildBatTool(batDef): Tool
		local v = variantOf(batDef.variant)

		local tool = Instance.new("Tool")
		tool.Name = batDef.name
		tool.RequiresHandle = true
		tool.CanBeDropped = false
		tool.ToolTip = ("%d dmg  •  click to swing"):format(batDef.damage)
		-- Held like a sword rather than straight up out of the fist: the grip drops
		-- the bat into the palm and cants it forward so the barrel reads as a blade
		-- you're about to swing. Grip is the offset of the engine's RightGrip weld,
		-- so this is a pose, not an animation, and it costs nothing.
		tool.Grip = CFrame.new(0, -0.15, 0.1) * CFrame.Angles(math.rad(-18), 0, math.rad(-8))

		local handle = Instance.new("Part")
		handle.Name = "Handle"
		handle.Size = Vector3.new(0.5, 1.6, 0.5)
		handle.Color = v.accent
		handle.Material = v.material
		handle.CanCollide = false
		handle.Massless = true
		handle.TopSurface = Enum.SurfaceType.Smooth
		handle.BottomSurface = Enum.SurfaceType.Smooth
		handle.Parent = tool

		local deco = Instance.new("Model")
		deco.Name = "Deco"
		deco.Parent = tool

		-- barrel above the grip
		local origin = CFrame.new(0, DECO_ORIGIN_Y, 0)
		TungModels.buildBatBody(deco, batDef.variant, DECO_SCALE, origin)

		for _, p in ipairs(deco:GetDescendants()) do
			if p:IsA("BasePart") then
				p.Massless = true
				p.CanCollide = false
				p.Anchored = false
				Util.weld(handle, p)
			end
		end

		-- Swing trail, spanning the deco the Tool actually built.
		--
		-- These were hardcoded at 0.8 and 3.4, which was wrong twice: the span did
		-- not scale with the variant, and a bat is not centred on its origin
		-- anyway — it runs from -1.66 to +3.12, so the fixed pair clipped the last
		-- three quarters of a stud off a `classic` and covered barely half of a
		-- `void`, which carries its own 1.3x on top.
		local decoScale = DECO_SCALE * (v.scale or 1)
		local a0 = Instance.new("Attachment")
		a0.Name = "TrailTop"
		a0.Position = Vector3.new(0, DECO_ORIGIN_Y + TungModels.BAT_BASE * decoScale, 0)
		a0.Parent = handle
		local a1 = Instance.new("Attachment")
		a1.Name = "TrailBottom"
		a1.Position = Vector3.new(0, DECO_ORIGIN_Y + TungModels.BAT_TOP * decoScale, 0)
		a1.Parent = handle
		local trail = Fx.trail(a0, a1, v.light and v.light.color or v.wood)
		trail.Name = "SwingTrail"

		tool:SetAttribute("BatId", batDef.id)
		tool:SetAttribute("Damage", batDef.damage)
		tool:SetAttribute("Cooldown", batDef.cooldown)
		tool:SetAttribute("Knockback", batDef.knockback)
		tool:SetAttribute("Reach", batDef.reach)
		tool:SetAttribute("Crit", batDef.crit)

		return tool
	end

	--- Big anchored decorative statue for the lobby / plot signage.
	function TungModels.buildStatue(variantName: string, scale: number): Model
		local model = TungModels.build(variantName, {
			scale = scale,
			anchored = true,
			withEffects = true,
			holdBat = true,
			collide = true,
		})
		model.Name = "TungStatue"
		for _, p in ipairs(model:GetDescendants()) do
			if p:IsA("BasePart") then
				p.Anchored = true
			end
		end
		return model
	end

	return TungModels
end


__MODULES["Util"] = function()
	--[[ Util.lua — small helpers shared by client and server. ]]

	local Util = {}

	local SUFFIXES = {
		"", "K", "M", "B", "T", "Qa", "Qi", "Sx", "Sp", "Oc", "No",
		"Dc", "UDc", "DDc", "TDc", "QaDc", "QiDc", "SxDc", "SpDc", "OcDc", "NoDc", "Vg",
	}

	--- 1234567 -> "1.23M"
	function Util.abbreviate(n: number): string
		if n ~= n then return "0" end            -- NaN guard
		local sign = n < 0 and "-" or ""
		n = math.abs(n)
		if n < 1000 then
			return sign .. tostring(math.floor(n + 0.5))
		end
		local index = math.floor(math.log(n, 1000))
		index = math.clamp(index, 1, #SUFFIXES - 1)
		local scaled = n / (1000 ^ index)
		local text
		if scaled >= 100 then
			text = string.format("%.0f", scaled)
		elseif scaled >= 10 then
			text = string.format("%.1f", scaled)
		else
			text = string.format("%.2f", scaled)
		end
		-- Trim trailing zeros, but ONLY past a decimal point. Trimming
		-- unconditionally turns "320" into "32", i.e. 320K displays as 32K.
		if text:find("%.") then
			text = text:gsub("0+$", "")
			text = text:gsub("%.$", "")
		end
		return sign .. text .. SUFFIXES[index + 1]
	end

	--- 1234567 -> "1,234,567"
	function Util.comma(n: number): string
		local whole = string.format("%.0f", math.abs(n))
		local out = whole:reverse():gsub("(%d%d%d)", "%1,"):reverse()
		out = out:gsub("^,", "")
		return (n < 0 and "-" or "") .. out
	end

	function Util.weld(a: BasePart, b: BasePart, name: string?): WeldConstraint
		local weld = Instance.new("WeldConstraint")
		weld.Name = name or "TungWeld"
		weld.Part0 = a
		weld.Part1 = b
		weld.Parent = a
		return weld
	end

	--- Welds every descendant BasePart of `model` to `root` and anchors nothing.
	function Util.weldModel(model: Model, root: BasePart)
		for _, part in ipairs(model:GetDescendants()) do
			if part:IsA("BasePart") and part ~= root then
				part.Anchored = false
				Util.weld(root, part)
			end
		end
	end

	function Util.setCollision(model: Instance, group: string)
		for _, part in ipairs(model:GetDescendants()) do
			if part:IsA("BasePart") then
				part.CollisionGroup = group
			end
		end
		if model:IsA("BasePart") then
			model.CollisionGroup = group
		end
	end

	function Util.newPart(props: { [string]: any }): Part
		local part = Instance.new("Part")
		part.Anchored = true
		part.CanCollide = false
		part.CastShadow = false
		part.TopSurface = Enum.SurfaceType.Smooth
		part.BottomSurface = Enum.SurfaceType.Smooth
		for key, value in pairs(props) do
			if key ~= "Parent" then
				(part :: any)[key] = value
			end
		end
		if props.Parent then
			part.Parent = props.Parent
		end
		return part
	end

	function Util.roundedFrame(parent: Instance, radius: number): UICorner
		local corner = Instance.new("UICorner")
		corner.CornerRadius = UDim.new(0, radius)
		corner.Parent = parent
		return corner
	end

	function Util.shallowCopy(t)
		local out = {}
		for k, v in pairs(t) do
			out[k] = v
		end
		return out
	end

	function Util.count(t): number
		local n = 0
		for _ in pairs(t) do
			n += 1
		end
		return n
	end

	--- Deterministic-ish pseudo random from a string seed (used for plot flavour).
	function Util.hash(s: string): number
		local h = 5381
		for i = 1, #s do
			h = (h * 33 + s:byte(i)) % 2147483647
		end
		return h
	end

	function Util.lerpColor(a: Color3, b: Color3, t: number): Color3
		return a:Lerp(b, math.clamp(t, 0, 1))
	end

	--- Safely reads a character's humanoid + root, or nil.
	function Util.getRig(model: Instance?): (Humanoid?, BasePart?)
		if not model or not model:IsA("Model") then
			return nil, nil
		end
		local humanoid = model:FindFirstChildOfClass("Humanoid")
		local root = model:FindFirstChild("HumanoidRootPart")
		if humanoid and root and root:IsA("BasePart") then
			return humanoid, root
		end
		return nil, nil
	end

	return Util
end


__MODULES["Utilities"] = function()
	--[[
		Utilities.lua — shared maths and lookups for the two player-progression
		prototypes: the upgrade shop (Config.PlayerUpgrades) and the utility slot
		(Config.Utilities).

		Why one module for both: the server prices a purchase and the client draws
		the price, and if those two ever disagree the shop shows a number you can't
		actually buy at. Every formula the UI needs lives here so there is exactly
		one copy of it, and the server treats its own result as the authority.

		Pure data + maths only — no Instances, no remotes, so it is safe on both
		sides of the wire.
	]]

	local Req = __Req
	local Config = Req("Config")

	local Utilities = {}

	export type UpgradeDef = {
		id: string, name: string, stat: string, levels: number,
		base: number, perLevel: number, cost: number, costGrowth: number,
		blurb: string,
	}

	export type UtilityDef = {
		id: string, name: string, verb: string,
		duration: number, cooldown: number, price: number, requires: string,
	}

	-- Config ships the two tables as arrays; index them once here rather than
	-- looping over four entries on every remote call.
	Utilities.UpgradeById = {} :: { [string]: UpgradeDef }
	for _, def in ipairs(Config.PlayerUpgrades) do
		Utilities.UpgradeById[def.id] = def
	end

	Utilities.UtilityById = {} :: { [string]: UtilityDef }
	for _, def in ipairs(Config.Utilities) do
		Utilities.UtilityById[def.id] = def
	end

	--- The value of an upgrade's stat at `level` (level 0 = unpurchased).
	function Utilities.valueAt(def, level: number): number
		return def.base + def.perLevel * math.clamp(level, 0, def.levels)
	end

	--- What the NEXT level costs, or nil at max. Geometric, per IDEAS.md §7:
	--- x4–6 per tier for a ~7-level premium stat.
	function Utilities.costAt(def, level: number): number?
		if level >= def.levels then
			return nil
		end
		return math.floor(def.cost * (def.costGrowth ^ level))
	end

	--- Trims trailing zeros so "23.10 studs/sec" reads as "23.1 studs/sec" without
	--- turning the payout multiplier into a bare "x1".
	function Utilities.formatValue(value: number): string
		if value == math.floor(value) then
			return tostring(math.floor(value))
		end
		local s = ("%.2f"):format(value)
		s = s:gsub("0$", "")
		return s
	end

	--- The blurb with the current stat value substituted in. Some blurbs (the
	--- autocollect toggle) have no placeholder, hence the find().
	function Utilities.describe(def, level: number): string
		if not def.blurb:find("%%s") then
			return def.blurb
		end
		return def.blurb:format(Utilities.formatValue(Utilities.valueAt(def, level)))
	end

	--- What each verb actually does, for the shop row. Config.Utilities carries a
	--- verb and a duration but no player-facing description, and the wording has
	--- to match what UpgradeService's implementation really does — so it lives
	--- next to the maths rather than in the UI, where it would be one more thing
	--- that can quietly stop being true.
	local VERB_BLURB = {
		freeze = "Roots nearby raiders for %ds. They can still swing.",
		shove = "Heavy knockback on everything nearby. No damage.",
		decoy = "Drops a decoy for %ds. PROTOTYPE: raiders ignore it.",
	}

	function Utilities.verbBlurb(def): string
		local blurb = VERB_BLURB[def.verb] or ("%s nearby."):format(def.verb)
		if blurb:find("%%d") then
			return blurb:format(def.duration)
		end
		return blurb
	end

	--- Utilities are one-shot purchases, so their "level" is 0 or 1 and their cost
	--- is flat. Expressed through the same two functions as the upgrades so the
	--- shop UI can draw both kinds of row with one code path.
	function Utilities.utilityCostAt(def, level: number): number?
		if level >= 1 then
			return nil
		end
		return def.price
	end

	return Utilities
end


__MODULES["CombatService"] = function()
	--[[
		CombatService.lua — bats, swinging, damage, knockback and PvP rules.

		Design notes
		  * The server is authoritative. Tool.Activated replicates, so the client
		    never gets to say "I hit them"; it only asks for a swing.
		  * PvP is opt-in by geography: you can only hurt another player while
		    BOTH of you are inside the arena ring. Your plot is a safe zone.
		  * Sahur raiders can be hit anywhere.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Util = Req("Util")
	local Fx = Req("Fx")
	local Net = Req("Net")
	local TungModels = Req("TungModels")
	local DataService = Req("DataService")
	local Economy = Req("Economy")

	local Players = game:GetService("Players")
	local Debris = game:GetService("Debris")

	local CombatService = {}

	local hitFeedback = Net.event("HitFeedback")
	local knockbackRemote = Net.event("Knockback")
	local swingFx = Net.event("SwingFx")

	local state: { [Player]: { lastSwing: number, combo: number, comboAt: number } } = {}

	local function stateFor(player: Player)
		local s = state[player]
		if not s then
			s = { lastSwing = 0, combo = 0, comboAt = 0 }
			state[player] = s
		end
		return s
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- zones
	-- ─────────────────────────────────────────────────────────────────────────────

	function CombatService.inArena(position: Vector3): boolean
		local flat = Vector3.new(position.X, 0, position.Z)
		return flat.Magnitude <= Config.World.ArenaRadius
	end

	--- Can `attacker` (a Player) hurt `victimModel`?
	function CombatService.canDamage(attacker: Player, victimModel: Model): boolean
		if victimModel:GetAttribute("IsSahurNPC") then
			return true
		end
		local victimPlayer = Players:GetPlayerFromCharacter(victimModel)
		if not victimPlayer then
			return false
		end
		if victimPlayer == attacker then
			return false
		end
		if not Config.Combat.ArenaPvP then
			return true
		end
		local attackerChar = attacker.Character
		if not attackerChar then
			return false
		end
		return CombatService.inArena(attackerChar:GetPivot().Position)
			and CombatService.inArena(victimModel:GetPivot().Position)
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- bats
	-- ─────────────────────────────────────────────────────────────────────────────

	local function removeBats(container: Instance?)
		if not container then
			return
		end
		for _, child in ipairs(container:GetChildren()) do
			if child:IsA("Tool") and child:GetAttribute("BatId") then
				child:Destroy()
			end
		end
	end

	--- Blocks until the player's profile has loaded, or gives up. A character can
	--- spawn before the DataStore read finishes on first join, and everything that
	--- dresses that character needs the profile.
	local function waitForProfile(player: Player)
		local profile = DataService.get(player)
		local deadline = os.clock() + 12
		while not profile and player.Parent and os.clock() < deadline do
			task.wait(0.25)
			profile = DataService.get(player)
		end
		return player.Parent and profile or nil
	end

	function CombatService.equipCurrentBat(player: Player)
		local profile = waitForProfile(player)
		if not profile then
			return
		end
		local tier = math.clamp(profile.batTier or 1, 1, #Config.Bats)
		local def = Config.Bats[tier]

		removeBats(player:FindFirstChildOfClass("Backpack"))
		removeBats(player.Character)

		local tool = TungModels.buildBatTool(def)
		-- straight into the Backpack: Roblox's own inventory + hotbar handles
		-- equipping, dropping and slot assignment, so we don't reimplement any of it
		tool.Parent = player:FindFirstChildOfClass("Backpack")

		CombatService.bind(player, tool)
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- armour
	--
	-- Lives here rather than in a service of its own because CombatService already
	-- owns the two places armour has to touch: onCharacter, which is the only
	-- writer of a player's humanoid stats, and CombatService.damage, which is the
	-- only TakeDamage call in the repo. A separate service would have to race the
	-- first and reach across the second.
	-- ─────────────────────────────────────────────────────────────────────────────

	function CombatService.armorTierOf(player: Player)
		local profile = DataService.get(player)
		local tier = math.clamp(profile and profile.armorTier or 1, 1, #Config.Armor.Tiers)
		return Config.Armor.Tiers[tier]
	end

	function CombatService.applyArmor(player: Player, character: Model?)
		character = character or player.Character
		local humanoid = character and character:FindFirstChildOfClass("Humanoid")
		if not humanoid then
			return
		end
		local health = CombatService.armorTierOf(player).health
		local delta = health - humanoid.MaxHealth
		humanoid.MaxHealth = health
		-- Setting MaxHealth alone leaves Health where it was, so a fully-armoured
		-- player spawns showing 100/320 and looking like they are bleeding out. The
		-- bar IS the reward for this track, so it has to read right.
		--
		-- Raised by the DELTA rather than to full, so buying armour in the middle
		-- of a raid is not also a free heal.
		humanoid.Health = math.clamp(humanoid.Health + math.max(0, delta), 1, health)
	end

	function CombatService.grantArmor(player: Player, armorId: string)
		local def = Config.ArmorById[armorId]
		local profile = DataService.get(player)
		if not def or not profile then
			return
		end
		-- monotonic, like grantBat: re-installing a tier you already have on a
		-- claim or a replay must not be a downgrade
		if def.tier <= (profile.armorTier or 1) then
			return
		end
		profile.armorTier = def.tier
		CombatService.applyArmor(player)
		Economy.push(player)
		Economy.notify(player, {
			kind = "gear",
			title = "NEW ARMOR: " .. def.name,
			body = ("%d max health"):format(def.health),
		})
	end

	function CombatService.grantBat(player: Player, batId: string)
		local def = Config.BatById[batId]
		local profile = DataService.get(player)
		if not def or not profile then
			return
		end
		if def.tier <= (profile.batTier or 1) then
			return
		end
		profile.batTier = def.tier
		CombatService.equipCurrentBat(player)
		Economy.push(player)
		Economy.notify(player, {
			kind = "gear",
			title = "NEW BAT: " .. def.name,
			body = ("%d damage  •  %.0f%% crit"):format(def.damage, def.crit * 100),
		})
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- swinging
	-- ─────────────────────────────────────────────────────────────────────────────

	--- Tells every client to play swing `comboIndex` on this character.
	---
	--- The animation itself is client-side (see SwingAnim): Motor6D.Transform does
	--- not replicate, so the server can only broadcast the fact of the swing and
	--- let each client draw it. The attacker's own client has already started the
	--- same swing from Tool.Activated — waiting for this round trip to begin the
	--- wind-up is exactly what makes networked melee feel like mud.
	local function broadcastSwing(character: Model, comboIndex: number, duration: number)
		swingFx:FireAllClients({
			character = character,
			combo = comboIndex,
			duration = duration,
		})
	end

	--- Applies damage to any humanoid, from a player or from an NPC.
	function CombatService.damage(victimModel: Model, amount: number, sourcePosition: Vector3?, knockback: number?, attacker: Player?, crit: boolean?)
		local humanoid, root = Util.getRig(victimModel)
		if not humanoid or not root or humanoid.Health <= 0 then
			return false
		end

		-- classic "creator" tag so whoever landed the last hit gets the credit
		if attacker then
			local old = humanoid:FindFirstChild("creator")
			if old then
				old:Destroy()
			end
			local tag = Instance.new("ObjectValue")
			tag.Name = "creator"
			tag.Value = attacker
			tag.Parent = humanoid
			Debris:AddItem(tag, 8)
		end

		humanoid:TakeDamage(amount)

		if knockback and knockback > 0 and sourcePosition then
			local direction = (root.Position - sourcePosition)
			direction = Vector3.new(direction.X, 0, direction.Z)
			if direction.Magnitude < 0.1 then
				direction = Vector3.new(0, 0, 1)
			end
			direction = direction.Unit
			local impulse = (direction * knockback + Vector3.new(0, knockback * 0.45, 0)) * root.AssemblyMass * 0.6

			local victimPlayer = Players:GetPlayerFromCharacter(victimModel)
			if victimPlayer then
				-- The victim's own client owns their character's physics, so a
				-- server-side ApplyImpulse is overwritten on the next replication
				-- tick. Ask the owning client to apply it instead.
				knockbackRemote:FireClient(victimPlayer, impulse)
			else
				root:ApplyImpulse(impulse)
			end
		end

		if attacker then
			hitFeedback:FireClient(attacker, {
				damage = amount,
				position = root.Position,
				killed = humanoid.Health <= 0,
				crit = crit == true,
			})
		end
		return true
	end

	local function hitscan(character: Model, reach: number, width: number): { Model }
		local root = character:FindFirstChild("HumanoidRootPart") :: BasePart
		if not root then
			return {}
		end
		local size = Config.Combat.HitboxSize
		local box = root.CFrame * CFrame.new(0, 0, -(reach / 2))
		local boxSize = Vector3.new(size.X * width, size.Y, reach)

		local params = OverlapParams.new()
		params.FilterType = Enum.RaycastFilterType.Exclude
		params.FilterDescendantsInstances = { character }
		params.MaxParts = 60

		local parts = workspace:GetPartBoundsInBox(box, boxSize, params)

		local seen = {}
		local victims = {}
		for _, part in ipairs(parts) do
			-- Walk UP until we find the model that owns a Humanoid, rather than
			-- stopping at the first Model ancestor. A raider's visible body is a
			-- sub-model of the rig, and the arm is a sub-model of that, so the first
			-- Model above a hit part is often not the character at all.
			local model = part:FindFirstAncestorOfClass("Model")
			while model and not model:FindFirstChildOfClass("Humanoid") do
				model = model:FindFirstAncestorOfClass("Model")
			end
			if model and not seen[model] then
				local humanoid = model:FindFirstChildOfClass("Humanoid")
				if humanoid and humanoid.Health > 0 then
					seen[model] = true
					table.insert(victims, model)
				end
			end
		end
		return victims
	end

	--- Resolves one strike: box the area in front of the swinger and damage
	--- whatever is in it that we're allowed to hurt.
	local function resolveStrike(player: Player, character: Model, hit: { [Model]: boolean },
		reach: number, width: number, damage: number, knockback: number, crit: boolean)

		local origin = character:GetPivot().Position

		for _, victim in ipairs(hitscan(character, reach, width)) do
			-- one swing damages a given victim once, however many samples see them
			if not hit[victim] and CombatService.canDamage(player, victim) then
				hit[victim] = true
				CombatService.damage(victim, damage, origin, knockback, player, crit)
				local _, victimRoot = Util.getRig(victim)
				if victimRoot then
					Fx.burst(victimRoot.Position, crit and Color3.fromRGB(255, 120, 80) or Color3.fromRGB(255, 230, 160),
						crit and 12 or 7, workspace)
					Fx.floatingText(victimRoot.Position + Vector3.new(0, 3, 0),
						(crit and "CRIT " or "") .. tostring(math.floor(damage)),
						crit and Color3.fromRGB(255, 140, 90) or Color3.fromRGB(255, 250, 220), workspace)
					Fx.impact(victimRoot, crit and 0.75 or 1)
				end
			end
		end
	end

	function CombatService.swing(player: Player, tool: Tool)
		local character = player.Character
		if not character then
			return
		end
		local humanoid = character:FindFirstChildOfClass("Humanoid")
		if not humanoid or humanoid.Health <= 0 then
			return
		end

		local s = stateFor(player)
		local now = os.clock()
		local cooldown = tool:GetAttribute("Cooldown") or 0.55
		if now - s.lastSwing < cooldown then
			return
		end
		s.lastSwing = now

		-- combo. Stack 0 is the first swing of a chain, so the animation index is
		-- one higher; the last step of the chain is the overhead finisher.
		if now - s.comboAt <= Config.Combat.ComboWindow then
			s.combo = (s.combo + 1) % (Config.Combat.ComboMaxStacks + 1)
		else
			s.combo = 0
		end
		s.comboAt = now

		local comboIndex = s.combo + 1
		local finisher = comboIndex == Config.Combat.SwingSteps

		broadcastSwing(character, comboIndex, cooldown)

		local handle = tool:FindFirstChild("Handle") :: BasePart
		local trail = handle and handle:FindFirstChild("SwingTrail") :: Trail
		if trail then
			-- the trail belongs to the strike, not to the wind-up: leaving it on
			-- for the whole swing draws a streak of the bat sitting still
			task.delay(cooldown * Config.Combat.SwingWindUp, function()
				if trail.Parent then
					trail.Enabled = true
				end
			end)
			task.delay(cooldown * (Config.Combat.SwingStrikeAt + 0.18), function()
				if trail.Parent then
					trail.Enabled = false
				end
			end)
		end
		if handle then
			Fx.impact(handle, 1.4 + math.random() * 0.2)
		end

		local reach = (tool:GetAttribute("Reach") or 9) * (finisher and Config.Combat.FinisherReach or 1)
		local baseDamage = tool:GetAttribute("Damage") or 18
		local knockback = (tool:GetAttribute("Knockback") or 55) * (finisher and Config.Combat.FinisherKnockback or 1)
		local critChance = tool:GetAttribute("Crit") or 0.08

		local comboMult = 1 + s.combo * Config.Combat.ComboDamagePerStack
		local crit = math.random() < critChance
		local damage = baseDamage * comboMult
			* (crit and Config.Combat.CritMultiplier or 1)
			* (finisher and Config.Combat.FinisherDamage or 1)
		if crit then
			knockback *= Config.Combat.CritKnockback
		end
		-- the slam lands flat in front of you rather than in a narrow line
		local width = finisher and 1.3 or 1

		-- The swing is resolved on its STRIKE FRAME, not on the frame the player
		-- clicked. That is the whole point of the rewrite: damage used to land a
		-- full animation before the bat visibly reached anything, which is why
		-- combat read as clicking rather than as hitting. The cost is that a target
		-- can now step out of a telegraphed swing, which is the point.
		local generation = s.lastSwing
		local hit: { [Model]: boolean } = {}

		local function strike()
			-- A second swing, a death, a respawn or a disconnect since we were
			-- scheduled all cancel this one. The player check matters: canDamage
			-- lets anyone hit an NPC without looking at the attacker, so without it
			-- a departing player's last swing still lands, tags a raider with a
			-- creator who is gone, and fires hit feedback at nobody.
			if s.lastSwing ~= generation
				or player.Parent == nil
				or player.Character ~= character
				or humanoid.Health <= 0
				or character.Parent == nil
			then
				return
			end
			resolveStrike(player, character, hit, reach, width, damage, knockback, crit)
		end

		task.delay(cooldown * Config.Combat.SwingStrikeAt, function()
			strike()
			-- The arc is still moving, so one instantaneous box misses anyone a few
			-- frames early or late. Sample again just after.
			task.delay(Config.Combat.SwingSampleGap, strike)
		end)
	end

	function CombatService.bind(player: Player, tool: Tool)
		tool.Activated:Connect(function()
			CombatService.swing(player, tool)
		end)
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- lifecycle
	-- ─────────────────────────────────────────────────────────────────────────────

	function CombatService.onCharacter(player: Player, character: Model)
		local humanoid = character:WaitForChild("Humanoid", 10) :: Humanoid
		if not humanoid then
			return
		end
		humanoid.WalkSpeed = Config.Combat.WalkSpeed
		humanoid.JumpPower = Config.Combat.JumpPower
		humanoid.UseJumpPower = true

		task.wait(0.35)
		if not waitForProfile(player) then
			return
		end
		CombatService.applyArmor(player, character)
		CombatService.equipCurrentBat(player)

		-- Re-apply once a beat later. Roblox's own Health script and the respawn
		-- pipeline both write Humanoid.Health after CharacterAdded returns, and
		-- nothing orders those against this write. Guarded on the character still
		-- being current so a fast death-respawn cannot apply to the wrong body.
		task.delay(0.75, function()
			if player.Character == character and humanoid.Health > 0 then
				CombatService.applyArmor(player, character)
			end
		end)

		humanoid.Died:Connect(function()
			local killerTag = humanoid:FindFirstChild("creator") :: ObjectValue?
			if killerTag and killerTag.Value and killerTag.Value:IsA("Player") then
				CombatService.creditKill(killerTag.Value, player.Name)
			end
		end)
	end

	function CombatService.creditKill(player: Player, victimName: string)
		local profile = DataService.get(player)
		if not profile then
			return
		end
		profile.kills += 1
		Economy.push(player)
		Economy.notify(player, { kind = "ko", title = "KO!", body = victimName })
	end

	--- Used by NPCService so raider damage flows through the same path.
	function CombatService.npcAttack(npc: Model, victimModel: Model, damage: number)
		local _, npcRoot = Util.getRig(npc)
		if not npcRoot then
			return
		end
		CombatService.damage(victimModel, damage, npcRoot.Position, Config.Waves.AttackKnockback, nil)
	end

	function CombatService.start()
		Players.PlayerRemoving:Connect(function(player)
			state[player] = nil
		end)
	end

	return CombatService
end


__MODULES["DataService"] = function()
	--[[
		DataService.lua — DataStore persistence with retries, autosave and a
		safe shutdown flush. Falls back to in-memory only if DataStores are
		unavailable (Studio without API access), so the game still runs.
	]]

	local Req = __Req
	local Config = Req("Config")

	local DataStoreService = game:GetService("DataStoreService")
	local Players = game:GetService("Players")
	local RunService = game:GetService("RunService")

	local DataService = {}

	local STORE_NAME = "TungTungTycoon_v1"
	local AUTOSAVE_SECONDS = 90

	--- Bumped whenever a saved value's MEANING changes rather than its shape.
	--- reconcile() runs the migrations between the saved version and this one.
	---
	--- 1 -> 2: Config.Bats grew from three tiers to six, with ash and crimson
	---         inserted between oak and void. profile.batTier stores an INDEX, so
	---         a v1 save reading "3" meant void and now means ash — a silent
	---         downgrade of a purchase, and one nothing else in the game could
	---         detect.
	local PROFILE_VERSION = 2

	--- v1 bat tier -> v2 bat tier. { starter, oak, void } -> their new indices.
	local LEGACY_BAT_TIERS = { 1, 2, 5 }

	local store: DataStore? = nil
	local dataStoresUsable = true

	do
		local ok, result = pcall(function()
			return DataStoreService:GetDataStore(STORE_NAME)
		end)
		if ok then
			store = result
		else
			dataStoresUsable = false
			warn("[Tung] DataStores unavailable, running in memory-only mode: " .. tostring(result))
		end
	end

	local function defaultProfile()
		return {
			cash = Config.Economy.StartingCash,
			owned = {},        -- { [buttonId] = true }
			rebirths = 0,
			batTier = 1,
			armorTier = 1,
			kills = 0,
			playtime = 0,
			-- PROTOTYPE fields (Offline / Sessions / RebirthPerks). reconcile()
			-- merges a saved value onto this default only when the TYPES match, so
			-- adding a field here is what makes every existing save keep loading:
			-- an old profile simply arrives with the default.
			--
			-- lastSeen is 0 rather than os.time() deliberately. A profile that has
			-- never stored one has no knowable logout time, and seeding it with
			-- "now" would look like a zero-second session; seeding it with 0 means
			-- SessionService skips the offline payout for that first session and
			-- starts counting from the logout after it.
			lastSeen = 0,
			sessions = {},     -- streak / boost / cap state, shaped by SessionService
			unlocks = {},      -- { [unlockId] = label } granted by rebirth milestones
			upgrades = {},     -- { [upgradeId] = level }, shaped by UpgradeService
			utilityEquipped = "",  -- a Config.Utilities id; "" rather than nil so the
			                       -- type-matched reconcile can merge a saved value
			version = PROFILE_VERSION,
		}
	end

	local profiles: { [number]: any } = {}
	local loading: { [number]: boolean } = {}

	local function key(userId: number): string
		return "player_" .. userId
	end

	local function retry(fn, attempts: number)
		local lastErr
		for i = 1, attempts do
			local ok, result = pcall(fn)
			if ok then
				return true, result
			end
			lastErr = result
			task.wait(0.6 * i)
		end
		return false, lastErr
	end

	--- Merges saved fields onto a fresh default so schema additions are safe.
	local function reconcile(saved)
		local profile = defaultProfile()
		if type(saved) ~= "table" then
			return profile
		end
		for k, v in pairs(profile) do
			if saved[k] ~= nil and type(saved[k]) == type(v) then
				profile[k] = saved[k]
			end
		end
		-- prune ids that no longer exist in Config
		local cleanOwned = {}
		if type(profile.owned) == "table" then
			for id, value in pairs(profile.owned) do
				if value and Config.ButtonById[id] then
					cleanOwned[id] = true
				end
			end
		end
		profile.owned = cleanOwned
		profile.cash = math.max(0, tonumber(profile.cash) or 0)
		profile.rebirths = math.clamp(math.floor(tonumber(profile.rebirths) or 0), 0, Config.Rebirth.MaxRebirths)
		profile.batTier = math.floor(tonumber(profile.batTier) or 1)

		-- MIGRATIONS. Run before the clamps, because a stale index is not out of
		-- range — it is in range and means the wrong thing, which is worse.
		local version = math.floor(tonumber(profile.version) or 1)
		if version < 2 then
			profile.batTier = LEGACY_BAT_TIERS[profile.batTier] or profile.batTier
		end
		profile.version = PROFILE_VERSION

		profile.batTier = math.clamp(profile.batTier, 1, #Config.Bats)
		profile.armorTier = math.clamp(math.floor(tonumber(profile.armorTier) or 1), 1, #Config.Armor.Tiers)

		-- A weapon or armour button is the RECORD of a granted tier, so it must
		-- never disagree with the tier itself. A save from before the weapons
		-- track existed owns batforge and batforge2 but none of the rungs now
		-- sitting between them — and because grantBat is monotonic, those rungs
		-- would light up as available and then take the player's money and do
		-- nothing. Backfill anything the tier already covers.
		--
		-- Idempotent, and it fixes the CLASS: the same divergence would reappear
		-- from any future reordering of Config.Bats.
		for _, def in ipairs(Config.Buttons) do
			if def.kind == "Gear" then
				local bat = Config.BatById[def.grants]
				if bat and bat.tier <= profile.batTier then
					profile.owned[def.id] = true
				end
			elseif def.kind == "Armor" then
				local tier = Config.ArmorById[def.grants]
				if tier and tier.tier <= profile.armorTier then
					profile.owned[def.id] = true
				end
			end
		end

		return profile
	end

	function DataService.load(player: Player)
		local userId = player.UserId
		if profiles[userId] then
			return profiles[userId]
		end
		loading[userId] = true

		local profile
		if store and dataStoresUsable then
			local ok, saved = retry(function()
				return (store :: DataStore):GetAsync(key(userId))
			end, 4)
			if ok then
				profile = reconcile(saved)
			else
				warn(("[Tung] load failed for %s: %s"):format(player.Name, tostring(saved)))
				profile = reconcile(nil)
				profile.__loadFailed = true   -- never overwrite good data with a failed read
			end
		else
			profile = reconcile(nil)
			profile.__loadFailed = not dataStoresUsable
		end

		profiles[userId] = profile
		loading[userId] = nil
		return profile
	end

	function DataService.get(player: Player)
		return profiles[player.UserId]
	end

	function DataService.save(player: Player, release: boolean?)
		local userId = player.UserId
		local profile = profiles[userId]
		if not profile then
			return false
		end
		if profile.__loadFailed then
			-- data never loaded cleanly; refuse to clobber the real save
			if release then
				profiles[userId] = nil
			end
			return false
		end

		local payload = {
			cash = profile.cash,
			owned = profile.owned,
			rebirths = profile.rebirths,
			batTier = profile.batTier,
			armorTier = profile.armorTier,
			kills = profile.kills,
			playtime = profile.playtime,
			lastSeen = profile.lastSeen,
			sessions = profile.sessions,
			unlocks = profile.unlocks,
			upgrades = profile.upgrades,
			utilityEquipped = profile.utilityEquipped,
			version = profile.version,
		}

		local saved = false
		if store and dataStoresUsable then
			local ok, err = retry(function()
				return (store :: DataStore):UpdateAsync(key(userId), function()
					return payload
				end)
			end, 4)
			saved = ok
			if not ok then
				warn(("[Tung] save failed for %s: %s"):format(player.Name, tostring(err)))
			end
		end

		if release then
			profiles[userId] = nil
		end
		return saved
	end

	function DataService.start()
		Players.PlayerRemoving:Connect(function(player)
			DataService.save(player, true)
		end)

		task.spawn(function()
			while true do
				task.wait(AUTOSAVE_SECONDS)
				for _, player in ipairs(Players:GetPlayers()) do
					local profile = profiles[player.UserId]
					if profile then
						profile.playtime += AUTOSAVE_SECONDS
						task.spawn(DataService.save, player, false)
					end
				end
			end
		end)

		game:BindToClose(function()
			if RunService:IsStudio() then
				return
			end
			local remaining = 0
			for _, player in ipairs(Players:GetPlayers()) do
				remaining += 1
				task.spawn(function()
					DataService.save(player, true)
					remaining -= 1
				end)
			end
			local deadline = os.clock() + 25
			while remaining > 0 and os.clock() < deadline do
				task.wait(0.1)
			end
		end)
	end

	return DataService
end


__MODULES["Economy"] = function()
	--[[
		Economy.lua — the single place cash is created, spent and replicated.
		Everything else asks this module; nothing else touches profile.cash.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Util = Req("Util")
	local Net = Req("Net")

	local Players = game:GetService("Players")

	local DataService = Req("DataService")

	local Economy = {}

	local statsRemote = Net.event("Stats")
	local notifyRemote = Net.event("Notify")

	local dirty: { [Player]: boolean } = {}

	--- PROTOTYPE HOOKS. Timed boosts, the weekend bonus and (eventually) the
	--- player-upgrade cash multiplier all stack on top of rebirth, but Economy
	--- must not depend on any of them — they depend on Economy, and Req refuses a
	--- circular require. Each registers a named function here at boot and Economy
	--- stays ignorant of what they do.
	---
	--- Keyed rather than a single slot so two prototypes can both stack without
	--- silently overwriting each other.
	local multiplierHooks: { [string]: (Player) -> number } = {}

	function Economy.setMultiplierHook(name: string, fn: ((Player) -> number)?)
		multiplierHooks[name] = fn
	end

	function Economy.multiplier(player: Player): number
		local profile = DataService.get(player)
		if not profile then
			return 1
		end
		-- compounding, not linear: rebirth cost grows geometrically (CostGrowth^n)
		-- so a linear payout bonus would make each rebirth strictly worse than the
		-- last and the prestige loop would dead-end after two or three.
		local base = Config.Rebirth.MultiplierPerRebirth ^ profile.rebirths
		for _, hook in pairs(multiplierHooks) do
			base *= hook(player)
		end
		return base
	end

	function Economy.get(player: Player): number
		local profile = DataService.get(player)
		return profile and profile.cash or 0
	end

	function Economy.setupLeaderstats(player: Player)
		local profile = DataService.get(player)
		if not profile then
			return
		end

		local existing = player:FindFirstChild("leaderstats")
		if existing then
			existing:Destroy()
		end

		local folder = Instance.new("Folder")
		folder.Name = "leaderstats"
		folder.Parent = player

		local cash = Instance.new("NumberValue")
		cash.Name = Config.Economy.CurrencyName
		cash.Value = profile.cash
		cash.Parent = folder

		local rebirths = Instance.new("IntValue")
		rebirths.Name = "Rebirths"
		rebirths.Value = profile.rebirths
		rebirths.Parent = folder

		local kos = Instance.new("IntValue")
		kos.Name = "KOs"
		kos.Value = profile.kills
		kos.Parent = folder
	end

	local function syncLeaderstats(player: Player)
		local profile = DataService.get(player)
		local folder = player:FindFirstChild("leaderstats")
		if not profile or not folder then
			return
		end
		local cash = folder:FindFirstChild(Config.Economy.CurrencyName)
		if cash then
			(cash :: NumberValue).Value = profile.cash
		end
		local rebirths = folder:FindFirstChild("Rebirths")
		if rebirths then
			(rebirths :: IntValue).Value = profile.rebirths
		end
		local kos = folder:FindFirstChild("KOs")
		if kos then
			(kos :: IntValue).Value = profile.kills
		end
	end

	function Economy.push(player: Player)
		local profile = DataService.get(player)
		if not profile then
			return
		end
		syncLeaderstats(player)
		statsRemote:FireClient(player, {
			cash = profile.cash,
			rebirths = profile.rebirths,
			kills = profile.kills,
			batTier = profile.batTier,
			armorTier = profile.armorTier,
			multiplier = Economy.multiplier(player),
			owned = profile.owned,
			rebirthCost = Economy.rebirthCost(player),
		})
	end

	--- Coalesces rapid-fire updates (droppers) into ~10 replications/sec.
	function Economy.markDirty(player: Player)
		dirty[player] = true
	end

	function Economy.add(player: Player, amount: number, applyMultiplier: boolean?)
		local profile = DataService.get(player)
		if not profile or amount <= 0 then
			return 0
		end
		local final = amount
		if applyMultiplier then
			final = amount * Economy.multiplier(player)
		end
		profile.cash += final
		Economy.markDirty(player)
		return final
	end

	function Economy.spend(player: Player, amount: number): boolean
		local profile = DataService.get(player)
		if not profile then
			return false
		end
		if profile.cash < amount then
			return false
		end
		profile.cash -= amount
		Economy.push(player)
		return true
	end

	--- Raiders nibble a slice of your bank when they land a hit.
	function Economy.steal(player: Player, fraction: number): number
		local profile = DataService.get(player)
		if not profile then
			return 0
		end
		local taken = math.floor(profile.cash * fraction)
		if taken <= 0 then
			return 0
		end
		profile.cash -= taken
		Economy.markDirty(player)
		return taken
	end

	function Economy.rebirthCost(player: Player): number
		local profile = DataService.get(player)
		local n = profile and profile.rebirths or 0
		return math.floor(Config.Rebirth.BaseCost * (Config.Rebirth.CostGrowth ^ n))
	end

	--- PROTOTYPE (Config.Prototypes.RebirthPerks). A rebirth pays four things, not
	--- one number. `Tycoon:rebirth()` owns two of them — it bumps profile.rebirths
	--- (the multiplier) and resets cash to Config.Economy.StartingCash — and it is
	--- owned by another track, so the other two are applied here, from the one
	--- module allowed to create cash.
	---
	--- `perks` comes from SessionService.rebirthPerksFor(profile). Passing it in
	--- rather than computing it keeps the dependency arrow pointing one way.
	---
	--- Idempotent on purpose: it tops cash UP to the grant instead of adding to
	--- it, so a double call (a retry, a re-detect) cannot be farmed.
	function Economy.applyRebirthGrants(player: Player, perks): number
		local profile = DataService.get(player)
		if not profile or not perks then
			return 0
		end

		local granted = 0
		local target = math.floor(tonumber(perks.startingCash) or 0)
		if target > profile.cash then
			granted = target - profile.cash
			profile.cash = target
		end

		if type(perks.unlocks) == "table" then
			if type(profile.unlocks) ~= "table" then
				profile.unlocks = {}
			end
			for id, label in pairs(perks.unlocks) do
				profile.unlocks[id] = label
			end
		end

		Economy.push(player)
		return granted
	end

	function Economy.notify(player: Player, payload)
		notifyRemote:FireClient(player, payload)
	end

	function Economy.start()
		task.spawn(function()
			while true do
				task.wait(0.1)
				for player in pairs(dirty) do
					dirty[player] = nil
					if player.Parent then
						Economy.push(player)
					end
				end
			end
		end)

		Players.PlayerRemoving:Connect(function(player)
			dirty[player] = nil
		end)
	end

	Economy.format = Util.abbreviate

	return Economy
end


__MODULES["FloorService"] = function()
	--[[
		FloorService.lua — the second storey.

		A mezzanine deck over the BACK half of the plot, with its own belt and
		collector and a pair of teleport pads. It appears when the plot buys
		Config.Floors[1].button, which sits at roughly the halfway point of the
		factory track.

		NO LONGER A PROTOTYPE. It was gated on Config.Prototypes.Floors, and the
		verifier asserts every prototype flag ships false — so graduating it meant
		deleting the flag rather than flipping it. It also used to appear for FREE
		the moment you owned dropper10, the last button of the ground floor, about
		eighty minutes in. "You buy floor 2 before you get anywhere near finishing
		floor 1" is the most complained-about thing in multi-floor tycoons, but the
		answer to it is not "put it where nobody will ever see it".

		Three decisions that look arbitrary and are not:

		  OFFSET, NOT STACKED. The deck covers the back half only, so the aisle you
		  walk down and the buy-button spine stay open to the sky. Roblox has no
		  good answer for a ceiling: opaque snaps the camera to head height,
		  transparent lets it pop through, and LocalTransparencyModifier is
		  overwritten by the default camera scripts every frame.

		  PADS, NOT A LIFT. Every shipped "elevator" in this genre is a teleport
		  pair. TweenService platforms jitter and slide players off, and they buy
		  nothing: the pads do not even have to be vertically aligned.

		  ITS OWN LOOP. Each floor runs an independent dropper -> belt -> collector.
		  Cross-floor transport is the trap — upward conveyors need velocity >= 25
		  and still stick.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Style = Req("Style")
	local Tycoon = Req("Tycoon")

	local FloorService = {}

	local FLOOR = Config.Floors and Config.Floors[1]

	-- All of this used to be file-local constants under two SHOULD MOVE TO CONFIG
	-- comments. It is in Config now, and the reason is not tidiness: deckPath()
	-- built the mezzanine's belt in CODE, so none of the belt-path assertions ever
	-- saw it — not that its legs stay on the deck, not that its collector clears
	-- the teleport pad, not its outboard count. Two of those were wrong.

	local COLORS = {
		deck   = Color3.fromRGB(138, 88, 58),
		frame  = Color3.fromRGB(118, 122, 130),
		rail   = Color3.fromRGB(255, 176, 60),
		padUp  = Color3.fromRGB(120, 200, 255),
		padDown = Color3.fromRGB(255, 190, 120),
	}

	-- one entry per plot: { folder, built }
	local state: { [any]: any } = {}

	-- Characters currently standing on a pad they were just delivered to. Weak
	-- keys so a player who leaves mid-ride doesn't pin their character forever.
	local arrivals: { [Model]: BasePart } = setmetatable({}, { __mode = "k" }) :: any
	local lastRide: { [Model]: number } = setmetatable({}, { __mode = "k" }) :: any

	-- ─────────────────────────────────────────────────────────────────────────────
	-- geometry
	-- ─────────────────────────────────────────────────────────────────────────────

	local function deckTopY(): number
		return FLOOR.height
	end

	--- The mezzanine's belt. Config.floorBeltPath derives it from the deck
	--- rectangle and the pad position, and Config.BeltPaths carries the result — so
	--- the belt assertions cover it exactly as they cover the ground floor's, with
	--- no new code on their side.
	local function deckPath()
		return Config.floorBeltPath(FLOOR), FLOOR.belt.outboard
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- the deck
	-- ─────────────────────────────────────────────────────────────────────────────

	function FloorService.buildDeck(tycoon, folder: Instance)
		local size = FLOOR.deckSize
		local centre = FLOOR.deckAt
		local top = deckTopY()

		Tycoon.part(folder, "Deck", size,
			tycoon:at(centre.X, top - size.Y / 2, centre.Z), COLORS.deck, Enum.Material.WoodPlanks)

		-- Posts down to the plot floor. They overlap INTO the deck rather than
		-- meeting its underside, because a post whose top face is coplanar with the
		-- deck's bottom face z-fights from below.
		local postTop = top - size.Y / 2 + 0.6
		local postX = size.X / 2 - FLOOR.pillar.insetSide
		local postZ = { centre.Z - size.Z / 2 + FLOOR.pillar.insetBack, centre.Z + size.Z / 2 - FLOOR.pillar.insetFront }
		for _, x in ipairs({ -1, 1 }) do
			for _, z in ipairs(postZ) do
				Tycoon.part(folder, "Post", Vector3.new(FLOOR.pillar.size, postTop, FLOOR.pillar.size),
					tycoon:at(centre.X + x * postX, postTop / 2, z),
					COLORS.frame, Enum.Material.Metal)
			end
		end

		-- Perimeter guard: an invisible collide-wall, because a solid 5-stud rail
		-- around the deck is a wall the camera has to fight. The visible part is a
		-- thin bar along the top of it, which reads as a railing and occludes
		-- nothing. Falling off is the obvious new failure mode of a floor.
		local height = FLOOR.railHeight
		local sides = {
			{ Vector3.new(size.X, height, FLOOR.rail.thickness), Vector3.new(0, 0, -size.Z / 2 + FLOOR.rail.thickness / 2) },
			{ Vector3.new(size.X, height, FLOOR.rail.thickness), Vector3.new(0, 0, size.Z / 2 - FLOOR.rail.thickness / 2) },
			{ Vector3.new(FLOOR.rail.thickness, height, size.Z), Vector3.new(-size.X / 2 + FLOOR.rail.thickness / 2, 0, 0) },
			{ Vector3.new(FLOOR.rail.thickness, height, size.Z), Vector3.new(size.X / 2 - FLOOR.rail.thickness / 2, 0, 0) },
		}
		for index, side in ipairs(sides) do
			local extent, offset = side[1], side[2]
			-- sunk 0.4 into the deck so its underside is inside solid geometry
			local guard = Tycoon.part(folder, "Guard" .. index, extent,
				tycoon:at(centre.X + offset.X, top + height / 2 - 0.4, centre.Z + offset.Z),
				Color3.new(1, 1, 1), Enum.Material.SmoothPlastic)
			guard.Transparency = 1
			guard.CanQuery = false
			guard.CastShadow = false

			-- The bars are shortened on the long sides so the four of them abut at
			-- the corners instead of overlapping: two coplanar top faces sharing a
			-- corner square is a z-fight you only notice from the deck itself.
			local barSize = Vector3.new(
				(index <= 2) and extent.X or FLOOR.rail.bar,
				0.4,
				(index <= 2) and FLOOR.rail.bar or (extent.Z - 2 * FLOOR.rail.bar))
			-- and it sits just INSIDE the top of the guard, not flush with it
			local bar = Tycoon.part(folder, "Rail" .. index, barSize,
				tycoon:at(centre.X + offset.X, top + height - 0.7, centre.Z + offset.Z),
				COLORS.rail, Enum.Material.Neon, false)
			bar.CanQuery = false
		end
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- teleport pads
	-- ─────────────────────────────────────────────────────────────────────────────

	local function humanoidsOn(pad: BasePart): { Model }
		-- Sweep the pad's volume instead of trusting the part that touched it.
		-- Teleporting only the toucher is the classic pad bug: it strands whoever
		-- walked in with them on the wrong floor.
		local volume = pad.Size + Vector3.new(0, 8, 0)
		local parts = workspace:GetPartBoundsInBox(pad.CFrame * CFrame.new(0, 4, 0), volume)

		local seen: { [Model]: boolean } = {}
		local found: { Model } = {}
		for _, part in ipairs(parts) do
			local model = part:FindFirstAncestorOfClass("Model")
			local humanoid = model and model:FindFirstChildOfClass("Humanoid")
			if humanoid and humanoid.Health > 0 and model.PrimaryPart and not seen[model] then
				seen[model] = true
				table.insert(found, model)
			end
		end
		return found
	end

	local function ride(pad: BasePart, destination: BasePart)
		local now = os.clock()
		for _, model in ipairs(humanoidsOn(pad)) do
			-- Don't bounce someone we just delivered here. The time window alone is
			-- not enough: a character resting on a part re-fires Touched off its own
			-- physics jitter, so the lock is only released when a sweep of the pad
			-- no longer finds them (see the TouchEnded handler).
			if arrivals[model] ~= pad and now - (lastRide[model] or 0) > FLOOR.pads.cooldown then
				lastRide[model] = now
				arrivals[model] = destination

				local pivot = model:GetPivot()
				local offset = pivot.Position - pad.Position
				local landing = destination.Position
					+ Vector3.new(offset.X, 0, offset.Z)
					+ Vector3.new(0, destination.Size.Y / 2 + FLOOR.pads.stand, 0)

				-- PivotTo overwrites the model's rotation outright, so the facing
				-- has to be baked into the target or everyone lands staring at
				-- world -Z regardless of which way they walked in.
				model:PivotTo(CFrame.new(landing) * (pivot - pivot.Position))
			end
		end
	end

	--- Both pads of a pair, wired to each other.
	local function linkPads(a: BasePart, b: BasePart)
		for _, pair in ipairs({ { a, b }, { b, a } }) do
			local pad, destination = pair[1], pair[2]
			pad.Touched:Connect(function()
				ride(pad, destination)
			end)
			pad.TouchEnded:Connect(function()
				-- release the arrival lock once they have actually stepped off
				local standing: { [Model]: boolean } = {}
				for _, model in ipairs(humanoidsOn(pad)) do
					standing[model] = true
				end
				for model, held in pairs(arrivals) do
					if held == pad and not standing[model] then
						arrivals[model] = nil
					end
				end
			end)
		end
	end

	local function buildPad(tycoon, folder: Instance, name: string, at: Vector3, topY: number, color: Color3, text: string): BasePart
		local pad = Tycoon.part(folder, name, FLOOR.pads.size,
			tycoon:at(at.X, topY - FLOOR.pads.size.Y / 2, at.Z), color, Enum.Material.Neon)
		-- walk-over, not step-onto, exactly like the claim and rebirth pads
		pad.CanCollide = false

		local light = Instance.new("PointLight")
		light.Color = color
		light.Range = 14
		light.Brightness = 1.6
		light.Shadows = false
		light.Parent = pad

		local billboard = Style.billboard(pad, {
			name = "Sign", width = 12, height = 4, distance = "prop", offset = 6,
		})
		Style.text(billboard, { text = text, color = color })

		return pad
	end

	function FloorService.buildPads(tycoon, folder: Instance)
		-- Config.Floors gives padDown and padUp the same X/Z, so which name means
		-- which cannot bite: the ground pad takes you up, the deck pad takes you
		-- down. They do not have to line up at all — the shipped elevators in this
		-- genre explicitly don't — but a pair that does reads as a lift shaft.
		local toDeck = buildPad(tycoon, folder, "PadToMezzanine", FLOOR.pads.down, FLOOR.pads.groundTop,
			COLORS.padUp, "▲ MEZZANINE")
		local toGround = buildPad(tycoon, folder, "PadToGround", FLOOR.pads.up,
			deckTopY() + FLOOR.deckLift + FLOOR.pads.size.Y, COLORS.padDown, "▼ GROUND FLOOR")
		linkPads(toDeck, toGround)
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- lifecycle
	-- ─────────────────────────────────────────────────────────────────────────────

	local function stateFor(tycoon)
		local entry = state[tycoon]
		if entry then
			return entry
		end

		local folder = Instance.new("Folder")
		folder.Name = "Floors"
		folder.Parent = tycoon.model
		-- so a released plot doesn't leave a deck hanging over a bare claim pad
		tycoon:registerFactoryFolder(folder)

		entry = { folder = folder, built = false }
		state[tycoon] = entry
		return entry
	end

	function FloorService.build(tycoon)
		local entry = stateFor(tycoon)
		entry.folder:ClearAllChildren()

		FloorService.buildDeck(tycoon, entry.folder)

		-- addBeltPath is idempotent by id and Tycoon.new already registered every
		-- path in Config.BeltPaths, so this resolves rather than adds. It has to:
		-- the mezzanine's buy buttons were built on first claim, and they took
		-- their height from this path existing.
		local def, outboard = deckPath()
		local pathIndex = tycoon:addBeltPath(def, outboard)
		tycoon:buildBelt(pathIndex, entry.folder)
		tycoon:buildCollector(pathIndex, entry.folder, false)

		-- NO DROPPER HERE ANY MORE. It used to be synthesised in this file and
		-- installed straight through buildDropperMachine/startDropLoop, bypassing
		-- Tycoon:install — which is why it appeared in neither Config.ButtonById
		-- nor `owned`, and why every income readout in the game under-reported a
		-- plot that had one. It is Config.FactoryButtons.mezz_dropper1 now, an
		-- ordinary Dropper row pinned to this path, installed like everything else.

		FloorService.buildPads(tycoon, entry.folder)
		entry.built = true
	end

	function FloorService.teardown(tycoon)
		local entry = state[tycoon]
		if not entry then
			return
		end
		-- Clearing the folder ends the floor's drop loop on its own: the loop polls
		-- its own model's Parent. The belt PATH stays registered — it is pure maths
		-- and addBeltPath is idempotent by id, so a rebuild rebuilds parts rather
		-- than stacking a second path onto the plot.
		entry.folder:ClearAllChildren()
		entry.built = false
	end

	--- Builds or tears down a plot's floors to match what it owns right now.
	---
	--- Driven off ownedChanged rather than from the Floor button's installer,
	--- because the deck outlives the button: a release, a rebirth and a re-claim
	--- all have to rebuild or drop it and none of them go through install().
	function FloorService.sync(tycoon)
		local unlocked = tycoon.owner ~= nil and tycoon.owned[FLOOR.button] == true
		local entry = state[tycoon]
		local built = entry ~= nil and entry.built

		if unlocked and not built then
			FloorService.build(tycoon)
			-- The roof was shaped for a plot with no floor in it. Reshape it now,
			-- or the deck grows through it.
			tycoon:refreshRoof()
		elseif built and not unlocked then
			FloorService.teardown(tycoon)
			tycoon:refreshRoof()
		end
	end

	function FloorService.start()
		if not FLOOR then
			return
		end
		local button = Config.ButtonById[FLOOR.button]
		if not button then
			warn("[Tung] floor " .. tostring(FLOOR.id) .. " is built by an unknown button: " .. tostring(FLOOR.button))
			return
		end

		for _, tycoon in ipairs(Tycoon.all()) do
			tycoon:onOwnedChanged(FloorService.sync)
			FloorService.sync(tycoon)
		end
	end

	return FloorService
end


__MODULES["MapBuilder"] = function()
	--[[
		MapBuilder.lua — generates the whole world at runtime.

		Layout: a central open-air arena (PvP + raid target) ringed by
		Config.World.PlotCount tycoon plots, each rotated to face inward.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Style = Req("Style")
	local Util = Req("Util")
	local TungModels = Req("TungModels")

	local Lighting = game:GetService("Lighting")

	local MapBuilder = {}

	local W = Config.World

	local PALETTE = {
		ground   = Color3.fromRGB(106, 168, 79),   -- grass
		pad      = Color3.fromRGB(199, 195, 185),  -- light concrete
		padEdge  = Color3.fromRGB(255, 176, 60),   -- warm marker stripe
		arena    = Color3.fromRGB(178, 172, 160),
		arenaLip = Color3.fromRGB(255, 140, 40),
		wood     = Color3.fromRGB(150, 103, 60),
	}

	local function newPart(parent, name, size, cf, color, material)
		local p = Instance.new("Part")
		p.Name = name
		p.Size = size
		p.CFrame = cf
		p.Color = color
		p.Material = material or Enum.Material.SmoothPlastic
		p.Anchored = true
		p.CanCollide = true
		p.TopSurface = Enum.SurfaceType.Smooth
		p.BottomSurface = Enum.SurfaceType.Smooth
		p.Parent = parent
		return p
	end

	--- Stock Roblox daylight. Deliberately plain: bright, neutral and readable.
	function MapBuilder.applyLighting()
		-- Lighting.Technology is not script-writable at runtime; it is set in
		-- default.project.json instead. Guarded so a manual/paste-in install
		-- doesn't take the whole boot sequence down with it.
		pcall(function()
			Lighting.Technology = Enum.Technology.ShadowMap
		end)
		Lighting.Ambient = Color3.fromRGB(0, 0, 0)
		Lighting.OutdoorAmbient = Color3.fromRGB(128, 128, 128)
		Lighting.Brightness = 3
		Lighting.ClockTime = 14.5
		Lighting.GeographicLatitude = 41.733
		Lighting.ExposureCompensation = 0
		Lighting.EnvironmentDiffuseScale = 1
		Lighting.EnvironmentSpecularScale = 1
		Lighting.FogColor = Color3.fromRGB(192, 192, 192)
		Lighting.FogStart = 0
		Lighting.FogEnd = 100000
		Lighting.GlobalShadows = true

		-- strip anything a previous (darker) build left behind, so re-running
		-- doesn't stack post-effects
		for _, existing in ipairs(Lighting:GetChildren()) do
			if existing:IsA("Atmosphere") or existing:IsA("PostEffect") then
				existing:Destroy()
			end
		end
	end

	--- Returns the CFrame for plot `index` (1-based). +Z of the CFrame points
	--- at the arena, matching the plot-local layout in Config.
	function MapBuilder.plotCFrame(index: number): CFrame
		local placement = W.PlotPlacements[index] or W.PlotPlacements[1]
		local angle, radius = placement.angle, placement.radius
		-- y = PlotSurfaceY, so plot-local y=0 is the top of the pad and sits
		-- clear of the ground plane instead of z-fighting with it
		local position = Vector3.new(math.sin(angle) * radius, W.PlotSurfaceY, math.cos(angle) * radius)
		-- look at the origin, then flip so plot-local +Z faces the arena
		local look = CFrame.lookAt(position, Vector3.new(0, 0, 0))
		return look * CFrame.Angles(0, math.pi, 0)
	end

	-- MVP arena: a floor, a low plinth, the statue and a sign. The torches, the
	-- 32-segment glowing rim and the 72-tile ring path were all decoration with
	-- no gameplay attached, so they are gone.
	local function buildArena(parent: Instance)
		local arena = Instance.new("Model")
		arena.Name = "Arena"
		arena.Parent = parent

		local floorThickness = 3
		local floor = newPart(arena, "ArenaFloor", Vector3.new(floorThickness, W.ArenaRadius * 2, W.ArenaRadius * 2),
			CFrame.new(0, W.ArenaFloorTopY - floorThickness / 2, 0) * CFrame.Angles(0, 0, math.pi / 2),
			PALETTE.arena, Enum.Material.Pebble)
		floor.Shape = Enum.PartType.Cylinder

		-- single ring border instead of 32 separate segments
		local rim = newPart(arena, "Rim", Vector3.new(1.2, W.ArenaRadius * 2 + 6, W.ArenaRadius * 2 + 6),
			CFrame.new(0, W.ArenaFloorTopY - 0.4, 0) * CFrame.Angles(0, 0, math.pi / 2),
			PALETTE.arenaLip, Enum.Material.Neon)
		rim.Shape = Enum.PartType.Cylinder
		rim.CanCollide = false

		local daisHeight = 4
		local daisTopY = W.ArenaFloorTopY + daisHeight
		local dais = newPart(arena, "Dais", Vector3.new(daisHeight, 26, 26),
			CFrame.new(0, daisTopY - daisHeight / 2, 0) * CFrame.Angles(0, 0, math.pi / 2),
			PALETTE.pad, Enum.Material.Slate)
		dais.Shape = Enum.PartType.Cylinder

		-- The statue's feet are 2.85 * scale below its pivot (see TungModels), and
		-- the infinity variant carries its own 1.5x scale. Stand it ON the dais
		-- instead of guessing a height and burying its legs in the platform.
		local statueScale = 3.5
		local footDrop = 2.85 * statueScale * Config.Variants.infinity.scale
		local statue = TungModels.buildStatue("infinity", statueScale)
		statue.Name = "ArenaStatue"
		statue:PivotTo(CFrame.new(0, daisTopY + footDrop, 0))
		statue.Parent = arena

		-- WHERE THE RAID IS ANNOUNCED. The client hangs its own billboard here and
		-- writes the wave state into it; the server only stands the anchor up, so
		-- the countdown can keep ticking locally instead of costing a remote a
		-- second. Empty and unowned until a client claims it.
		local raidAnchor = newPart(arena, "RaidAnchor", Vector3.new(1, 1, 1),
			CFrame.new(0, Config.Style.RaidSignY, 0), PALETTE.pad)
		raidAnchor.Transparency = 1
		raidAnchor.CanCollide = false
		raidAnchor.CanQuery = false

		-- ...and the game's own name above it. This used to sit at 34, which is
		-- across the statue's face — it tops out around 35.6.
		local sign = newPart(arena, "TitleAnchor", Vector3.new(1, 1, 1),
			CFrame.new(0, Config.Style.ArenaTitleY, 0), PALETTE.pad)
		sign.Transparency = 1
		sign.CanCollide = false

		local billboard = Style.billboard(sign, {
			name = "Title", width = 56, height = Config.Style.ArenaTitleHeight, distance = "world",
		})
		Style.text(billboard, {
			name = "Title", size = UDim2.fromScale(1, 0.62),
			text = "TUNG TUNG TYCOON", color = Color3.fromRGB(255, 214, 90),
		})
		Style.text(billboard, {
			name = "Subtitle", weight = "body",
			size = UDim2.fromScale(1, 0.34), position = UDim2.fromScale(0, 0.62),
			text = "pvp enabled inside the ring", color = Color3.fromRGB(255, 255, 255),
		})

		return arena
	end

	local function buildSpawn(parent: Instance)
		local spawnPad = Instance.new("SpawnLocation")
		spawnPad.Name = "TungSpawn"
		spawnPad.Size = Vector3.new(36, 1.5, 24)
		-- in FRONT of the dais, not on top of it: spawning at the origin puts
		-- players inside the statue's legs
		spawnPad.CFrame = CFrame.new(0, W.ArenaFloorTopY + 0.75, 52)
		spawnPad.Anchored = true
		spawnPad.CanCollide = true
		spawnPad.Color = Color3.fromRGB(150, 103, 60)
		spawnPad.Material = Enum.Material.WoodPlanks
		spawnPad.TopSurface = Enum.SurfaceType.Smooth
		spawnPad.Duration = 0
		spawnPad.Neutral = true
		spawnPad.Parent = parent
		return spawnPad
	end

	function MapBuilder.build(): Folder
		local existing = workspace:FindFirstChild("TungWorld")
		if existing then
			existing:Destroy()
		end

		-- clear the default baseplate if the place still has one
		local defaultBase = workspace:FindFirstChild("Baseplate")
		if defaultBase then
			defaultBase:Destroy()
		end

		local world = Instance.new("Folder")
		world.Name = "TungWorld"
		world.Parent = workspace

		local groundThickness = 12
		local ground = newPart(world, "Ground", Vector3.new(W.BaseplateSize, groundThickness, W.BaseplateSize),
			CFrame.new(0, W.GroundTopY - groundThickness / 2, 0), PALETTE.ground, Enum.Material.Grass)
		ground.Anchored = true

		buildArena(world)
		buildSpawn(world)

		local plots = Instance.new("Folder")
		plots.Name = "Plots"
		plots.Parent = world

		MapBuilder.applyLighting()

		return world
	end

	--- Builds the flat pad + signage for one plot. The tycoon machinery is added
	--- later by Tycoon.lua; this is just the real estate.
	function MapBuilder.buildPlotPad(parent: Instance, index: number): (Model, CFrame)
		local cf = MapBuilder.plotCFrame(index)

		local model = Instance.new("Model")
		model.Name = "Plot" .. index
		model.Parent = parent

		local pad = newPart(model, "Pad", W.PlotSize, cf * CFrame.new(0, -W.PlotSize.Y / 2, 0), PALETTE.pad, Enum.Material.Concrete)
		pad:SetAttribute("PlotIndex", index)

		-- glowing border. The pad is no longer square, so the front/back strips key
		-- off half the DEPTH and the side strips off half the width; using one
		-- `half` for both left the front and back edges floating inside the pad.
		local half = W.PlotSize.X / 2
		local halfZ = W.PlotSize.Z / 2
		local edges = {
			{ Vector3.new(W.PlotSize.X, 1, 2), CFrame.new(0, 0.2, halfZ) },
			{ Vector3.new(W.PlotSize.X, 1, 2), CFrame.new(0, 0.2, -halfZ) },
			{ Vector3.new(2, 1, W.PlotSize.Z), CFrame.new(half, 0.2, 0) },
			{ Vector3.new(2, 1, W.PlotSize.Z), CFrame.new(-half, 0.2, 0) },
		}
		for i, edge in ipairs(edges) do
			local e = newPart(model, "Edge" .. i, edge[1], cf * edge[2], PALETTE.padEdge, Enum.Material.Neon)
			e.CanCollide = false
		end

		-- Claim totem, parked in the front-RIGHT corner. It used to stand at x = 0,
		-- directly on top of the pad you are meant to step on, and then in the
		-- front-left corner, which is where Tycoon builds the vault — the two
		-- models were interpenetrating on every plot.
		local totemCF = cf * CFrame.new(half - 12, 6, halfZ - 8)
		local totem = newPart(model, "Totem", Vector3.new(4, 12, 4), totemCF, Color3.fromRGB(70, 52, 40), Enum.Material.Wood)
		totem:SetAttribute("PlotIndex", index)

		local billboard = Style.billboard(totem, {
			name = "Sign", width = 26, height = 9, distance = "plot", offset = 9,
		})

		local frame = Instance.new("Frame")
		frame.Size = UDim2.fromScale(1, 1)
		frame.BackgroundColor3 = Color3.fromRGB(24, 18, 34)
		frame.BackgroundTransparency = 0.25
		frame.BorderSizePixel = 0
		frame.Parent = billboard
		Util.roundedFrame(frame, 12)

		local stroke = Instance.new("UIStroke")
		stroke.Color = PALETTE.padEdge
		stroke.Thickness = 3
		stroke.Parent = frame

		Style.text(frame, {
			name = "Owner",
			size = UDim2.fromScale(0.92, 0.9), position = UDim2.fromScale(0.04, 0.05),
			text = "UNCLAIMED PLOT " .. index .. "\nstep on the pad to claim",
			color = Color3.fromRGB(255, 236, 180),
		})

		return model, cf
	end

	return MapBuilder
end


__MODULES["NPCService"] = function()
	--[[
		NPCService.lua — the Sahur Raid.

		Every few minutes a wave of Tung Tung Tung Sahur raiders spawns at the
		arena rim and goes looking for players. They hit hard, they nibble your
		bank, and they pay out well when you knock them down.

		All NPCs are ticked from one loop rather than a thread each.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Util = Req("Util")
	local Fx = Req("Fx")
	local Net = Req("Net")
	local TungModels = Req("TungModels")
	local Economy = Req("Economy")
	local DataService = Req("DataService")
	local CombatService = Req("CombatService")

	local Players = game:GetService("Players")
	local Debris = game:GetService("Debris")

	local NPCService = {}

	local waveRemote = Net.event("WaveState")
	local notifyRemote = Net.event("Notify")

	local WV = Config.Waves

	-- Raider swing poses, in body space: arm overhead, then swung through to just
	-- past the target. See SwingAnim for why these are expressed this way.
	local TOP_PITCH = 158
	local CONTACT_PITCH = 22

	local active: { [Model]: any } = {}
	local folder: Folder

	--- THE SCHEDULE.
	---
	--- `waveNumber` is only ever read to mint a record. Everything a wave needs to
	--- know about itself lives on the record, and every raider holds a reference to
	--- the one that spawned it — which is what makes `remaining` per-wave instead
	--- of a global count of every living raider on the map.
	---
	--- phase ∈ idle | resting | warning | spawning | active | clear
	---
	--- `spawning` is a separate phase from `active` on purpose: it makes the clear
	--- test `spawnFinished and alive <= 0`, so the moment mid-drip when the count
	--- legitimately touches zero is structurally unreachable rather than guarded
	--- against.
	local waveNumber = 0
	local phase = "idle"
	local phaseUntil = 0
	local liveWave: any = nil
	local emptySince: number? = nil
	local nextBroadcast = 0

	-- raider flavour escalates with the wave number
	local WAVE_VARIANTS = { "classic", "oak", "ash", "crimson", "neon", "void", "eclipse", "galaxy", "infinity" }

	local function variantForWave(wave: number, boss: boolean): string
		local index = math.clamp(math.floor((wave - 1) / 2) + 1, 1, #WAVE_VARIANTS)
		if boss then
			index = math.clamp(index + 2, 1, #WAVE_VARIANTS)
		end
		return WAVE_VARIANTS[index]
	end

	--- The packet describing where the raid currently is. Built from the live
	--- record rather than passed around, so there is one description of the truth
	--- and a late joiner can be handed exactly what everyone else last saw.
	local function wavePacket()
		local seconds = math.max(0, math.ceil(phaseUntil - os.clock()))
		if phase == "idle" then
			return { phase = "idle" }
		elseif phase == "resting" then
			return { phase = "resting", wave = waveNumber + 1, seconds = seconds }
		end
		local w = liveWave
		if not w then
			return { phase = "idle" }
		end
		return {
			phase = phase,
			wave = w.number,
			boss = w.boss,
			remaining = w.alive,
			total = w.expected,
			forced = w.forced,
			seconds = (phase == "warning" or phase == "clear") and seconds or nil,
		}
	end

	local function broadcast(payload)
		waveRemote:FireAllClients(payload or wavePacket())
	end

	-- ─────────────────────────────────────────────────────────────────────────────

	--- ONE snapshot of every live player, rebuilt at most every SnapshotInterval
	--- and read by every raider.
	---
	--- This used to be a scan per raider per repath, at four instance reads per
	--- player: 26 raiders x 10 players x ~1.7 Hz was about 1,700 property reads a
	--- second, and the tighter chase repath below would have made that worse
	--- rather than better. Rebuilding once a frame-ish makes it flat at ~400
	--- regardless of how many raiders are alive, and turns the per-raider work
	--- into float maths over a ten-entry array.
	---
	--- It is also the one place that decides what counts as a target, which is
	--- exactly the seam the `decoy` utility prototype needs — see the TODO in
	--- UpgradeService.
	local snapshot: { any } = {}
	local snapshotAt = 0

	local function refreshSnapshot(now: number)
		if now < snapshotAt then
			return
		end
		snapshotAt = now + WV.SnapshotInterval
		table.clear(snapshot)
		for _, player in ipairs(Players:GetPlayers()) do
			local character = player.Character
			local humanoid = character and character:FindFirstChildOfClass("Humanoid")
			local root = character and character:FindFirstChild("HumanoidRootPart")
			if humanoid and root and humanoid.Health > 0 then
				table.insert(snapshot, {
					player = player,
					character = character,
					root = root,
					position = root.Position,
					-- Recounted from scratch each rebuild by the tick below, so a
					-- raider that died or de-aggroed frees its slot without anyone
					-- having to remember to decrement anything.
					chasers = 0,
				})
			end
		end
	end

	--- The snapshot row for a character, or nil. Used to find the chaser slot a
	--- committed raider belongs to.
	local function snapshotFor(character: Model?)
		if not character then
			return nil
		end
		for _, entry in ipairs(snapshot) do
			if entry.character == character then
				return entry
			end
		end
		return nil
	end

	--- Counts, per player, how many raiders are currently chasing them. Rebuilt
	--- rather than maintained incrementally: a decrement that has to happen in
	--- four different places is a decrement that eventually does not.
	local function countChasers()
		for _, slot in ipairs(snapshot) do
			slot.chasers = 0
		end
		for _, entry in pairs(active) do
			if entry.ai == "chase" and not entry.dead then
				local slot = snapshotFor(entry.target)
				if slot then
					slot.chasers += 1
				end
			end
		end
	end

	--- Nearest live player to `position` within `maxDistance`, from the snapshot.
	--- Squared distances: nothing here needs the actual magnitude.
	--- The nearest live player's snapshot row within `maxDistance`, or nil. The row
	--- rather than the character, because the caller needs its chaser count too.
	--- Squared distances: nothing here needs the actual magnitude.
	local function nearestSnapshotEntry(position: Vector3, maxDistance: number)
		local best, bestD2 = nil, maxDistance * maxDistance
		for _, entry in ipairs(snapshot) do
			local offset = entry.position - position
			local d2 = offset.X * offset.X + offset.Y * offset.Y + offset.Z * offset.Z
			if d2 < bestD2 then
				best, bestD2 = entry, d2
			end
		end
		return best
	end

	--- Flat XZ distance. Every AI radius here is a ground distance — a raider on a
	--- ramp is not further away for being higher up.
	local function flatDistance(a: Vector3, b: Vector3): number
		local dx, dz = a.X - b.X, a.Z - b.Z
		return math.sqrt(dx * dx + dz * dz)
	end

	--- A point inside a disc of `radius` around `centre`. sqrt() on the random so
	--- points spread evenly over the area instead of clustering at the middle.
	local function pointInDisc(centre: Vector3, radius: number): Vector3
		local angle = math.random() * math.pi * 2
		local r = radius * math.sqrt(math.random())
		return Vector3.new(centre.X + math.sin(angle) * r, centre.Y, centre.Z + math.cos(angle) * r)
	end

	local function killReward(wave: number, boss: boolean): number
		local reward = WV.RewardBase * (WV.RewardGrowth ^ (wave - 1))
		if boss then
			reward *= WV.BossHealthMultiplier
		end
		return math.floor(reward)
	end

	local function onRaiderDied(npc: Model, entry)
		if entry.dead then
			return
		end
		entry.dead = true
		-- Decrement THIS raider's own wave. A straggler from wave N therefore
		-- decrements wave N, and because that record is not the live one it emits
		-- nothing at all — which is what stops leftovers being counted against,
		-- and labelled with, the wave that came after them.
		local record = entry.waveRecord
		if record then
			record.alive = math.max(0, record.alive - 1)
		end

		local humanoid = npc:FindFirstChildOfClass("Humanoid")
		local tag = humanoid and humanoid:FindFirstChild("creator") :: ObjectValue?
		local killer = tag and tag.Value

		local pivot = npc:GetPivot().Position
		local variant = Config.Variants[npc:GetAttribute("Variant") or "classic"] or Config.Variants.classic
		Fx.burst(pivot, variant.wood, entry.boss and 40 or 18, workspace)

		if killer and killer:IsA("Player") and killer.Parent then
			local reward = killReward(entry.wave, entry.boss)
			local gained = Economy.add(killer, reward, true)
			local profile = DataService.get(killer)
			if profile then
				profile.kills += 1
			end
			Economy.push(killer)
			Fx.floatingText(pivot + Vector3.new(0, 6, 0), "+" .. Util.abbreviate(gained), Color3.fromRGB(255, 205, 90), workspace)
			if entry.boss then
				notifyRemote:FireAllClients({
					kind = "boss",
					title = "BOSS DOWN",
					body = ("%s finished the wave %d boss."):format(killer.DisplayName, entry.wave),
				})
			end
		end

		-- flop over, then clean up
		for _, part in ipairs(npc:GetDescendants()) do
			if part:IsA("Motor6D") then
				part.Enabled = false
			end
		end
		Debris:AddItem(npc, 4)
		active[npc] = nil

		-- No FireAllClients here. This used to send one packet per death — up to 27
		-- a wave, and a whole burst on a single frame when an AoE lands. Mark the
		-- record dirty instead and let the tick flush at most every
		-- BroadcastInterval; the driver sends phase changes immediately, so the
		-- kill that ENDS a wave is still instant.
		if record == liveWave then
			record.dirty = true
		end
	end

	local function spawnRaider(record, index: number, count: number, boss: boolean, groupAngle: number?)
		local wave = record.number
		local variantName = variantForWave(wave, boss)
		local health = WV.BaseHealth * (WV.HealthGrowth ^ (wave - 1)) * (boss and WV.BossHealthMultiplier or 1)
		-- The cap is absolute. It used to be scaled by the boss multiplier along
		-- with the damage, which meant the ceiling written to stop a raider two-
		-- shotting a 100 HP player let a late boss hit for 61.
		local damage = math.min(
			WV.BaseDamage * (WV.DamageGrowth ^ (wave - 1)) * (boss and WV.BossDamageMultiplier or 1),
			boss and WV.MaxBossDamage or WV.MaxDamage)

		local npc = TungModels.buildNPC(variantName, {
			scale = boss and 2.1 or (0.9 + math.random() * 0.35),
			health = health,
			walkSpeed = WV.WalkSpeed + (boss and -2 or math.random() * 4),
			displayName = boss and ("SAHUR BOSS  •  wave " .. wave) or "Tung Tung Tung Sahur",
			boss = boss,
		})

		-- Land in CLUSTERS, not on one evenly-divided ring. A ring of 26 arrives as
		-- a wall closing from every direction at once; six clusters of four arrive
		-- as a raid. `groupAngle` is chosen per group by the caller and jittered
		-- per member here.
		--
		-- The boss used to be passed index 0, so it appeared at the same rim spot
		-- every single time; it gets its own bearing now.
		local angle = (groupAngle or 0) + (math.random() - 0.5) * 2 * WV.GroupArc
		local radius = Config.World.ArenaRadius - 18
		local position = Vector3.new(math.sin(angle) * radius, 8, math.cos(angle) * radius)
		npc:PivotTo(CFrame.new(position) * CFrame.Angles(0, math.random() * math.pi * 2, 0))
		npc.Parent = folder

		local humanoid = npc:FindFirstChildOfClass("Humanoid") :: Humanoid
		local torso = npc:FindFirstChild("Torso")
		-- The VISIBLE arm, not the R6 rig's. Every rig part is Transparency = 1
		-- (the rig exists so Humanoid/MoveTo/damage work); the guy you actually see
		-- is the Visual model, and TungArm is its one articulated joint.
		local visual = npc:FindFirstChild("Visual")
		local core = visual and visual.PrimaryPart
		local arm = core and core:FindFirstChild("TungArm")
		local entry = {
			wave = wave,
			waveRecord = record,
			-- Strictly later than the wave's own deadline, so the wave-level
			-- timeout always fires first and this only ever catches a raider whose
			-- record was somehow lost. It used to be a hardcoded 420, which was
			-- longer than the whole wave interval and is why waves overlapped.
			despawnAt = os.clock() + WV.MaxWaveTime + WV.StragglerGrace,
			boss = boss,
			damage = damage,
			-- AI state. NOT `entry.phase` — that name is already the waddle's sine
			-- phase a few lines down, and reusing it would desync the walk cycle
			-- every time the raider changed its mind.
			ai = "wander",
			-- The patch this raider calls home. Scattered around the ARENA CENTRE
			-- rather than sitting at the spawn point: raiders land on the rim and
			-- then walk inward to mill about, which is what makes them read as
			-- gathering in the middle rather than as a ring closing in.
			home = pointInDisc(Vector3.zero, WV.HomeSpread),
			wanderUntil = 0,
			nextAggroCheck = 0,
			-- Where on the approach ring this raider stands. Fixed per raider so a
			-- pack spreads deterministically instead of jostling for the same spot.
			slotAngle = (index / math.max(count, 1)) * math.pi * 2 + math.random() * 0.5,
			-- How long it must hold you inside AggroRadius before committing.
			-- Random per raider, so a pack that all crosses the threshold on one
			-- tick still commits raggedly over ~2 seconds.
			aggroDelay = math.random() * WV.AggroStagger,
			aggroSince = nil,
			nextAttack = 0,
			nextRepath = 0,
			sway = torso and torso:FindFirstChild("TungSway"),
			phase = math.random() * math.pi * 2,
			spawnedAt = os.clock(),
			dead = false,
			-- attack telegraph. Raiders are server-owned, so unlike player swings
			-- these Motor6D writes replicate on their own and no remote is needed.
			arm = arm,
			armBase = arm and arm.C0,
			walkSpeed = humanoid.WalkSpeed,
			windUp = WV.AttackWindUp * (boss and WV.BossWindUpScale or 1),
			swingAt = nil,
			rootedUntil = 0,
		}
		-- The waddle used to rewrite the sway joint's C0 from a hardcoded 0.7, but
		-- buildNPC sets it to 0.7 * scale — so a 2.1x boss dropped a stud and a half
		-- into its own legs on the first frame it moved.
		if entry.sway then
			entry.swayBase = entry.sway.C0
		end

		active[npc] = entry
		record.alive += 1
		record.spawned += 1

		humanoid.Died:Connect(function()
			onRaiderDied(npc, entry)
		end)

		-- boss aura
		if boss then
			local _, root = Util.getRig(npc)
			if root then
				local light = Instance.new("PointLight")
				light.Color = Color3.fromRGB(255, 90, 60)
				light.Range = 40
				light.Brightness = 3
				light.Parent = root
			end
		end
	end

	-- ─────────────────────────────────────────────────────────────────────────────

	local function tick(dt: number)
		local now = os.clock()
		refreshSnapshot(now)
		countChasers()
		for npc, entry in pairs(active) do
			if not npc.Parent or entry.dead then
				continue
			end
			local humanoid, root = Util.getRig(npc)
			if not humanoid or not root or humanoid.Health <= 0 then
				continue
			end

			-- waddle
			if entry.sway and entry.swayBase then
				entry.phase += dt * (6 + humanoid.WalkSpeed * 0.25)
				local lean = math.sin(entry.phase) * 0.18
				local bob = math.abs(math.cos(entry.phase)) * 0.22
				entry.sway.C0 = entry.swayBase * CFrame.new(0, bob, 0) * CFrame.Angles(0, 0, lean)
			end

			-- Raise the bat over the wind-up, hold at the top for an instant, then
			-- chop down through the hit. The shape matters more than the numbers:
			-- what makes a raider fair is that the arm is visibly UP before the
			-- damage lands, and that they are rooted while it is.
			if entry.arm and entry.armBase then
				-- Raise, hold, chop — and the chop has to finish BEFORE the damage
				-- lands, not after it. The whole point of a telegraph is that the
				-- bat is visibly on its way down when it connects.
				local pitch = 0
				if entry.swingAt then
					local w = 1 - math.clamp((entry.swingAt - now) / entry.windUp, 0, 1)
					if w < 0.55 then
						pitch = TOP_PITCH * (w / 0.55)                 -- raise
					elseif w < 0.72 then
						pitch = TOP_PITCH                              -- hold at the top
					else
						-- chop, arriving at the contact pose exactly on the hit
						local k = (w - 0.72) / 0.28
						pitch = TOP_PITCH + (CONTACT_PITCH - TOP_PITCH) * (k ^ 0.6)
					end
				elseif now < entry.rootedUntil then
					-- follow-through settling back to rest
					pitch = CONTACT_PITCH * math.clamp((entry.rootedUntil - now) / WV.AttackRecover, 0, 1)
				end
				-- The pitch is in BODY space; conjugating by the joint's own C0
				-- rotation converts it, so this reads the same way as the player
				-- swing poses in SwingAnim and doesn't depend on how the shoulder
				-- happens to be oriented. +X pitch raises the arm forward.
				local basis = entry.armBase.Rotation
				entry.arm.C0 = entry.armBase * (basis:Inverse() * CFrame.Angles(math.rad(pitch), 0, 0) * basis)
			end

			-- ── AI: wander / chase / return ──────────────────────────────────────
			--
			-- Evaluated only when the raider is free to move. The telegraph above
			-- runs regardless of state ON PURPOSE: gating it on "chase" would
			-- freeze a raider mid-swing with its bat overhead the instant it
			-- de-aggroed.
			if now >= entry.rootedUntil and not entry.swingAt then
				local homeDistance = flatDistance(root.Position, entry.home)

				if entry.ai == "chase" then
					local target = entry.target
					local targetRootPart = target and target.Parent
						and target:FindFirstChild("HumanoidRootPart")
					local targetHumanoid = target and target.Parent
						and target:FindFirstChildOfClass("Humanoid")
					local lost = not targetRootPart
						or not targetHumanoid
						or targetHumanoid.Health <= 0
						or flatDistance(targetRootPart.Position, root.Position) > WV.DeAggroRadius
						or homeDistance > WV.LeashRadius

					if lost then
						entry.ai = "return"
						entry.target = nil
						entry.nextRepath = 0
					end
				elseif entry.ai == "return" then
					if homeDistance <= WV.HomeArrive then
						entry.ai = "wander"
						entry.wanderUntil = 0
					end
				end

				-- Only a raider that is NOT already committed goes looking, and a
				-- returning one may not bite again until it is most of the way
				-- home — otherwise a player parked on the leash line yo-yos it.
				if entry.ai ~= "chase" and now >= entry.nextAggroCheck then
					entry.nextAggroCheck = now + WV.AggroCheck
					local mayAggro = entry.ai == "wander"
						or homeDistance <= WV.LeashRadius * WV.ReAggroFrac
					local slot = mayAggro and nearestSnapshotEntry(root.Position, WV.AggroRadius) or nil
					-- Cap how many may engage one player. The overflow keeps
					-- milling and steps in as slots free, which reads as
					-- reinforcements rather than as a queue.
					if slot and slot.chasers >= WV.MaxChasers then
						slot = nil
					end
					if slot then
						-- ...and even then, hold the player for this raider's own
						-- delay first. A pack that all crosses the threshold on one
						-- tick still commits raggedly.
						entry.aggroSince = entry.aggroSince or now
						if now - entry.aggroSince >= entry.aggroDelay then
							entry.ai = "chase"
							entry.target = slot.character
							entry.nextRepath = 0
							slot.chasers += 1
						end
					else
						entry.aggroSince = nil
					end
				end

				local interval = (entry.ai == "chase" and WV.RepathChase)
					or (entry.ai == "return" and WV.RepathReturn)
					or WV.RepathWander

				if now >= entry.nextRepath then
					entry.nextRepath = now + interval

					if entry.ai == "chase" then
						local targetRootPart = entry.target and entry.target.Parent
							and entry.target:FindFirstChild("HumanoidRootPart")
						if targetRootPart then
							-- A point on a ring AROUND the target, not the target
							-- itself. Twenty-six raiders all pathing to one stud
							-- is what made a wave read as a single blob standing
							-- inside itself.
							--
							-- ApproachStandoff is UNDER AttackRange, so a raider
							-- parked on its slot is already in swing range: the
							-- ring costs no damage output. The orbit term is
							-- folded into the repath rather than animated per
							-- frame, which at 0.35s is smooth enough and costs two
							-- trig calls per chasing raider per repath.
							local slotAngle = entry.slotAngle + now * WV.OrbitSpeed
							humanoid:MoveTo(targetRootPart.Position + Vector3.new(
								math.sin(slotAngle) * WV.ApproachStandoff,
								0,
								math.cos(slotAngle) * WV.ApproachStandoff))
						end
					elseif entry.ai == "return" then
						humanoid:MoveTo(entry.home)
					else
						-- Drift around the home patch. The old idle target was a
						-- hardcoded +/-60 world-space box unrelated to the arena,
						-- so idling raiders wandered off it.
						if now >= entry.wanderUntil then
							entry.wanderUntil = now
								+ WV.WanderDwellMin
								+ math.random() * (WV.WanderDwellMax - WV.WanderDwellMin)
							entry.wanderTarget = pointInDisc(entry.home, WV.WanderRadius)
						end
						humanoid:MoveTo(entry.wanderTarget or entry.home)
					end

					-- unstick
					if entry.lastPosition and (root.Position - entry.lastPosition).Magnitude < 1.5 then
						humanoid.Jump = true
					end
					entry.lastPosition = root.Position
				end
			end

			-- Rooted while winding up and recovering. This is the window a player
			-- punishes: before, the raider closed and dealt damage on the same
			-- tick, so being hit was pure proximity and there was nothing to read.
			--
			-- Still written EVERY frame, and still hard-zeroed while rooted. The
			-- per-state scale MULTIPLIES the captured entry.walkSpeed rather than
			-- replacing it, so each raider keeps the jitter buildNPC gave it.
			-- (UpgradeService's freeze verb anchors the assembly specifically
			-- because this write exists every frame — see the note there.)
			local speedScale = 1
			if entry.ai == "wander" then
				speedScale = WV.WanderSpeedScale
			elseif entry.ai == "return" then
				speedScale = WV.ReturnSpeedScale
			end
			humanoid.WalkSpeed = (now < entry.rootedUntil) and 0 or (entry.walkSpeed * speedScale)

			local target = entry.target
			local targetRoot = target and target.Parent and target:FindFirstChild("HumanoidRootPart")
			local inRange = targetRoot
				and (targetRoot.Position - root.Position).Magnitude <= WV.AttackRange

			if entry.swingAt and now >= entry.swingAt then
				entry.swingAt = nil
				-- The hit only lands if the target is STILL in range: walking out of
				-- a telegraphed swing has to actually work or the telegraph is a lie.
				if inRange then
					CombatService.npcAttack(npc, target, entry.damage)
					Fx.impact(root, 0.85)

					local victim = Players:GetPlayerFromCharacter(target)
					if victim then
						local stolen = Economy.steal(victim, WV.StealPerHit)
						if stolen > 0 then
							Fx.floatingText(targetRoot.Position + Vector3.new(0, 4, 0),
								"-" .. Util.abbreviate(stolen), Color3.fromRGB(255, 110, 110), workspace)
						end
					end
				end
			elseif not entry.swingAt and inRange and now >= entry.nextAttack then
				entry.swingAt = now + entry.windUp
				entry.rootedUntil = entry.swingAt + WV.AttackRecover
				entry.nextAttack = entry.rootedUntil + WV.AttackCooldown
				if targetRoot then
					-- face the target so the wind-up reads as aimed at you
					root.CFrame = CFrame.lookAt(root.Position,
						Vector3.new(targetRoot.Position.X, root.Position.Y, targetRoot.Position.Z))
				end
				Fx.impact(root, 1.5)
			end

			-- despawn stragglers so a wave can't hang forever
			if now >= entry.despawnAt then
				humanoid.Health = 0
			end
		end

		-- Flush the coalesced counter update. Two comparisons a frame, against one
		-- FireAllClients per death before.
		if liveWave and liveWave.dirty and now >= nextBroadcast then
			liveWave.dirty = false
			nextBroadcast = now + WV.BroadcastInterval
			broadcast()
		end
	end

	-- ─────────────────────────────────────────────────────────────────────────────

	local function setPhase(newPhase: string, seconds: number?)
		phase = newPhase
		phaseUntil = os.clock() + (seconds or 0)
		-- Phase changes bypass the broadcast throttle. These are the packets that
		-- must never be late: a banner that says "1 RAIDER LEFT" for half a second
		-- after you killed the last one is worse than no banner.
		broadcast()
	end

	--- Mints the record for the next wave and puts the warning up.
	local function beginWave()
		waveNumber += 1
		local count = math.min(WV.BaseCount + (waveNumber - 1) * WV.CountPerWave, WV.MaxCount)
		local boss = (waveNumber % WV.BossEvery == 0)

		liveWave = {
			number = waveNumber,
			boss = boss,
			count = count,
			expected = count + (boss and 1 or 0),
			spawned = 0,
			alive = 0,
			spawnFinished = false,
			cleared = false,
			forced = false,
			dirty = false,
			deadline = math.huge,
			-- Generous: the drip itself is count * SpawnGap, and this only exists
			-- so a thread that dies mid-drip cannot wedge the schedule.
			spawnDeadline = os.clock() + WV.WarningTime + count * WV.SpawnGap * 4 + 10,
		}

		setPhase("warning", WV.WarningTime)
		notifyRemote:FireAllClients({
			kind = boss and "boss" or "wave",
			title = ("SAHUR RAID %d INCOMING"):format(waveNumber),
			body = boss and "A BOSS is coming. tung tung tung."
				or ("%d raiders in %d seconds."):format(count, WV.WarningTime),
		})
	end

	--- Drips the wave in. Runs in its OWN thread and only sets a flag the driver
	--- polls, so the driver itself never blocks — the old loop ran the warning wait
	--- and the whole drip inside the pcall'd startWave, which meant an error
	--- anywhere in there took the schedule down with it.
	local function spawnWave(record)
		task.spawn(function()
			local groups = math.max(1, math.ceil(record.count / WV.SpawnGroupSize))
			local index = 0
			for group = 1, groups do
				-- A bearing per cluster, spread around the rim and jittered, so
				-- successive waves do not land in the same six places.
				local groupAngle = ((group - 1) / groups) * math.pi * 2 + math.random() * 0.6
				for _ = 1, WV.SpawnGroupSize do
					index += 1
					if index > record.count then
						break
					end
					if record ~= liveWave then
						return
					end
					spawnRaider(record, index, record.count, false, groupAngle)
					task.wait(WV.SpawnGap)
				end
				if group < groups then
					task.wait(WV.SpawnGroupGap)
				end
			end
			if record.boss and record == liveWave then
				spawnRaider(record, 0, record.count, true, math.random() * math.pi * 2)
			end
			record.spawnFinished = true
			record.deadline = os.clock() + WV.MaxWaveTime
		end)
	end

	--- Kills whatever is left of a wave that has run out of time.
	local function forceEnd(record)
		record.forced = true
		for npc, entry in pairs(active) do
			if entry.waveRecord == record and not entry.dead then
				local humanoid = npc:FindFirstChildOfClass("Humanoid")
				if humanoid then
					-- Through Died, so the flop and the Debris cleanup still run.
					-- No creator tag, so no reward is paid for a wave nobody
					-- finished — which is correct, not an oversight.
					humanoid.Health = 0
				end
			end
		end
	end

	function NPCService.clearAll()
		for npc in pairs(active) do
			npc:Destroy()
		end
		active = {}
		liveWave = nil
	end

	--- One step of the schedule. Polled rather than driven by signals: at 4 Hz the
	--- cost is nothing, and it keeps every transition in one readable place
	--- instead of spread across a death handler and three timers.
	local function step()
		local now = os.clock()
		local populated = #Players:GetPlayers() > 0

		-- An empty server runs no raid, and does not burn a wave number doing it.
		if not populated and phase ~= "idle" then
			NPCService.clearAll()
			emptySince = now
			setPhase("idle")
			return
		end

		if phase == "idle" then
			if populated then
				-- A server that sat empty long enough resets, so someone joining a
				-- stale one is not met by a wave-30 raider with 2.9k health.
				if emptySince and now - emptySince >= WV.EmptyResetAfter then
					waveNumber = 0
				end
				emptySince = nil
				setPhase("resting", WV.JoinGrace)
			end
			return
		end

		if phase == "resting" then
			if now >= phaseUntil then
				beginWave()
			end
			return
		end

		if phase == "warning" then
			if now >= phaseUntil then
				setPhase("spawning")
				spawnWave(liveWave)
			end
			return
		end

		if phase == "spawning" then
			-- The drip runs in its own thread, so an error inside it kills that
			-- thread and nothing else — `spawnFinished` would simply never arrive
			-- and the schedule would sit here forever. Time it out into `active`
			-- with whatever did spawn; if that is nothing, `active` clears it on
			-- the next step and the raid moves on.
			if liveWave.spawnFinished or now >= liveWave.spawnDeadline then
				liveWave.spawnFinished = true
				liveWave.deadline = math.min(liveWave.deadline, now + WV.MaxWaveTime)
				setPhase("active")
			end
			return
		end

		if phase == "active" then
			-- `spawnFinished` is what makes this safe. Without it the moment
			-- mid-drip when alive legitimately touches zero would read as a clear.
			if liveWave.alive <= 0 then
				setPhase("clear", WV.ClearBannerTime)
			elseif now >= liveWave.deadline then
				forceEnd(liveWave)
				setPhase("clear", WV.ClearBannerTime)
			end
			return
		end

		if phase == "clear" then
			if now >= phaseUntil then
				local rest = liveWave.boss and WV.RestTimeAfterBoss or WV.RestTime
				liveWave = nil
				setPhase("resting", rest)
			end
			return
		end
	end

	--- Hands a joining client the packet everyone else last saw, so a mid-wave
	--- joiner does not stare at a blank banner until the next death.
	function NPCService.pushTo(player: Player)
		waveRemote:FireClient(player, wavePacket())
	end

	function NPCService.start()
		folder = Instance.new("Folder")
		folder.Name = "SahurRaiders"
		folder.Parent = workspace

		game:GetService("RunService").Heartbeat:Connect(function(dt)
			local ok, err = pcall(tick, dt)
			if not ok then
				warn("[Tung] NPC tick error: " .. tostring(err))
			end
		end)

		Players.PlayerAdded:Connect(function(player)
			task.defer(NPCService.pushTo, player)
		end)

		if not WV.Enabled then
			return
		end

		task.spawn(function()
			task.wait(WV.FirstWaveDelay)
			while true do
				local ok, err = pcall(step)
				if not ok then
					warn("[Tung] wave step error: " .. tostring(err))
				end
				task.wait(0.25)
			end
		end)
	end

	function NPCService.currentWave(): number
		return liveWave and liveWave.number or waveNumber
	end

	--- How many raiders of the CURRENT wave are still standing. Nil when no wave
	--- is running, which is different from zero.
	function NPCService.remaining(): number?
		return liveWave and liveWave.alive or nil
	end

	return NPCService
end


__MODULES["PlotService"] = function()
	--[[
		PlotService.lua — owns the Tycoon instances and who is standing on what.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Net = Req("Net")
	local Tycoon = Req("Tycoon")
	local Economy = Req("Economy")

	local Players = game:GetService("Players")

	local PlotService = {}

	local plots: { any } = {}
	local byOwner: { [Player]: any } = {}
	local reserved: { [number]: { userId: number, until_: number } } = {}

	local plotAssigned = Net.event("PlotAssigned")

	function PlotService.build(parent: Instance)
		local folder = parent:FindFirstChild("Plots") or parent
		for index = 1, Config.World.PlotCount do
			local tycoon = Tycoon.new(index, folder)
			plots[index] = tycoon
			PlotService.hookClaimPad(tycoon)
		end
	end

	function PlotService.hookClaimPad(tycoon)
		local lastTouch = 0
		local function onTouch(hit)
			-- cheapest possible early-out: an owned plot ignores touches entirely
			if tycoon.owner then
				return
			end
			if os.clock() - lastTouch < 0.5 then
				return
			end
			lastTouch = os.clock()
			local player = tycoon:playerFromHit(hit)
			if player and not byOwner[player] then
				PlotService.claim(player, tycoon.index)
			end
		end

		-- The marked pad is the affordance, but the ENTIRE plot floor claims an
		-- unclaimed plot. Hunting for a specific tile to stand on is a bad first
		-- thirty seconds, and there is no downside: the plot is free either way.
		for _, part in ipairs({ tycoon.claimPad, tycoon.padPart }) do
			if part then
				part.Touched:Connect(onTouch)
			end
		end
	end

	--- Puts a player on their own plot. Used on claim and on every respawn, so
	--- dying never costs you a walk back across the map.
	function PlotService.teleportToPlot(player: Player): boolean
		local tycoon = byOwner[player]
		local character = player.Character
		if not tycoon or not character or not character.PrimaryPart then
			return false
		end
		character:PivotTo(tycoon:ownerSpawnCFrame())
		return true
	end

	function PlotService.plotOf(player: Player)
		return byOwner[player]
	end

	local function isReservedForSomeoneElse(index: number, player: Player): boolean
		local hold = reserved[index]
		if not hold then
			return false
		end
		if os.clock() > hold.until_ then
			reserved[index] = nil
			return false
		end
		return hold.userId ~= player.UserId
	end

	function PlotService.claim(player: Player, index: number): boolean
		if byOwner[player] then
			return false
		end
		local tycoon = plots[index]
		if not tycoon or tycoon.owner then
			return false
		end
		if isReservedForSomeoneElse(index, player) then
			Economy.notify(player, {
				kind = "warn",
				title = "Plot reserved",
				body = "That factory is being held for a player who just disconnected.",
			})
			return false
		end

		reserved[index] = nil
		if not tycoon:assign(player) then
			return false
		end
		byOwner[player] = tycoon

		plotAssigned:FireClient(player, index)
		Economy.notify(player, {
			kind = "claim",
			title = "PLOT " .. index .. " CLAIMED",
			body = "Buy the first dropper to start the tung.",
		})
		Economy.push(player)

		PlotService.teleportToPlot(player)
		return true
	end

	function PlotService.release(player: Player, hold: boolean?)
		local tycoon = byOwner[player]
		if not tycoon then
			return
		end
		byOwner[player] = nil
		if hold then
			reserved[tycoon.index] = {
				userId = player.UserId,
				until_ = os.clock() + Config.Economy.OfflineGraceSeconds,
			}
		end
		tycoon:release()
	end

	--- Auto-place a player on the first free plot (used on join for convenience).
	function PlotService.autoAssign(player: Player): boolean
		-- honour a reservation from a recent disconnect first
		for index, hold in pairs(reserved) do
			if hold.userId == player.UserId and os.clock() <= hold.until_ then
				if PlotService.claim(player, index) then
					return true
				end
			end
		end
		for index = 1, Config.World.PlotCount do
			local tycoon = plots[index]
			if tycoon and not tycoon.owner and not isReservedForSomeoneElse(index, player) then
				return PlotService.claim(player, index)
			end
		end
		Economy.notify(player, {
			kind = "warn",
			title = "All plots taken",
			body = "Hang out in the arena — a plot frees up when someone leaves.",
		})
		return false
	end

	function PlotService.rebirth(player: Player)
		local tycoon = byOwner[player]
		if not tycoon then
			return
		end
		tycoon:rebirth(player)
	end

	function PlotService.start()
		Net.event("RequestRebirth").OnServerEvent:Connect(function(player)
			PlotService.rebirth(player)
		end)

		Net.event("RequestReset").OnServerEvent:Connect(function(player)
			PlotService.release(player, false)
			Economy.notify(player, { kind = "info", title = "Plot released", body = "Your progress is saved. Claim any plot to resume." })
		end)

		Players.PlayerRemoving:Connect(function(player)
			PlotService.release(player, true)
		end)

		-- keep the signage honest
		task.spawn(function()
			while true do
				task.wait(3)
				for _, tycoon in ipairs(plots) do
					local ok, err = pcall(function()
						tycoon:updateSign()
						if tycoon.owner then
							tycoon:refreshButtons()
						end
					end)
					if not ok then
						warn("[Tung] plot refresh error: " .. tostring(err))
					end
				end
			end
		end)
	end

	return PlotService
end


__MODULES["SessionService"] = function()
	--[[
		SessionService.lua — offline earnings, the three session loops (daily
		streak, playtime ladder, boost button) and the three rebirth grants that
		Tycoon:rebirth() does not hand out.

		Three Config.Prototypes flags live here — Offline, Sessions and
		RebirthPerks — because they share one profile sub-table, one replicated
		payload and one panel. Each is checked independently, and with all three
		off every entry point returns before doing any work.

		TIME. Two rules, both of them bugs someone else already shipped:

		  * **os.time(), never tick().** tick() is the wall clock of whatever
		    machine the server happens to be running on. Storing one machine's
		    tick() and subtracting another's is how a developer accidentally
		    granted 1.6 billion from a few seconds of drift. os.time() is UTC
		    epoch seconds and is the same number everywhere.
		  * **Day buckets are math.floor(os.time() / 86400), never
		    os.date("%j").** The day-of-year restarts at 1 on January 1st, so a
		    streak keyed on it breaks for every player in the game on the same
		    night — and it breaks in the direction of resetting their streak.

		os.clock() still appears below, but only for monotonic in-session
		durations (activity sampling, rate limits) where it is the right tool and
		nothing is persisted.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Util = Req("Util")
	local Net = Req("Net")
	local DataService = Req("DataService")
	local Economy = Req("Economy")

	local Players = game:GetService("Players")

	local SessionService = {}

	local P = Config.Prototypes
	local S = Config.Sessions
	local O = Config.Offline
	local RP = Config.RebirthPerks

	local DAY = 86400
	local PUSH_SECONDS = 5        -- how often state is re-replicated if nothing changed
	local ACTIVITY_STUDS = 2      -- movement per sample that counts as "still playing"
	local CLAIM_COOLDOWN = 0.25   -- per-player floor between remote claims

	local sessionState = Net.event("SessionState")
	local requestClaim = Net.event("RequestClaim")
	local requestBoost = Net.event("RequestBoost")

	--- Anything on at all? The whole file is inert otherwise.
	local function enabled(): boolean
		return P.Offline or P.Sessions or P.RebirthPerks
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- per-session runtime state (never persisted)
	-- ─────────────────────────────────────────────────────────────────────────────

	type Live = {
		player: Player,
		activeSeconds: number,        -- session-scoped, and only counts while active
		lastPosition: Vector3?,
		lastClaim: number,
		claimedPlaytime: { [number]: boolean },
		offline: any,                 -- pending welcome-back grant, nil once claimed
		rebirths: number,             -- last seen count, to detect a rebirth landing
		dirty: boolean,
		lastPush: number,
	}

	local live: { [Player]: Live } = {}

	-- ─────────────────────────────────────────────────────────────────────────────
	-- profile shape
	-- ─────────────────────────────────────────────────────────────────────────────

	--- The `sessions` sub-table of a profile.
	---
	--- DataService.reconcile() only type-checks TOP-LEVEL keys, so a table field
	--- arrives from the DataStore exactly as it was written — including from a
	--- build where the shape was different. Every field is re-derived here on
	--- every read, which is cheap and means no other function in this file has to
	--- wonder whether a number is a number.
	local function sessions(profile)
		local s = profile.sessions
		if type(s) ~= "table" then
			s = {}
			profile.sessions = s
		end
		s.dailyDay = math.floor(tonumber(s.dailyDay) or 0)
		s.streak = math.max(0, math.floor(tonumber(s.streak) or 0))
		s.boostUntil = math.floor(tonumber(s.boostUntil) or 0)
		s.boostReadyAt = math.floor(tonumber(s.boostReadyAt) or 0)
		s.offlineCapLevel = math.clamp(math.floor(tonumber(s.offlineCapLevel) or 0), 0, #O.CapUpgradeHours)
		return s
	end

	local function dayNumber(): number
		return math.floor(os.time() / DAY)
	end

	--- UTC, because a server-wide "weekend" that depends on where the machine is
	--- would start at different times for different players.
	local function isWeekend(): boolean
		return S.WeekendDays[os.date("!*t").wday] == true
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- income, derived from the SAVED plot
	-- ─────────────────────────────────────────────────────────────────────────────

	--- Income per second computed from persisted plot state and nothing else.
	---
	--- Never from a value cached at logout (a stale multiplier survives a nerf and
	--- pays out forever) and never from anything the client said. An offline
	--- player has no Tycoon instance to ask, which is why this mirrors
	--- `Tycoon:incomePerSecond()` rather than calling it.
	---
	--- Deliberately EXCLUDES the session multipliers below: a 2x boost is bought
	--- with presence, and banking it while logged out is the opposite of the
	--- point. It includes the rebirth multiplier because that is a property of the
	--- factory, not of the session.
	function SessionService.incomePerSecondFor(profile): number
		if type(profile) ~= "table" then
			return 0
		end
		local upgradeMult, total = 1, 0
		for id, owned in pairs(profile.owned or {}) do
			local def = owned and Config.ButtonById[id]
			if def then
				if def.kind == "Upgrader" then
					upgradeMult *= def.multiplier
				elseif def.kind == "Dropper" then
					total += def.dropValue / def.dropRate
				end
			end
		end
		local rebirths = math.max(0, math.floor(tonumber(profile.rebirths) or 0))
		return total * upgradeMult * (Config.Rebirth.MultiplierPerRebirth ^ rebirths)
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- offline earnings
	-- ─────────────────────────────────────────────────────────────────────────────

	--- Hours of offline income this profile banks. The cap is a purchase, which is
	--- what turns it from a wall you resent into a goal you aim at.
	function SessionService.offlineCapHours(profile): number
		local level = sessions(profile).offlineCapLevel
		return O.CapUpgradeHours[level] or O.CapHours
	end

	--- The upgrade that WOULD have prevented the clip. Naming it on the panel is
	--- the difference between "we took your money" and "here is what to buy".
	local function nextCapUpgrade(profile)
		local level = sessions(profile).offlineCapLevel + 1
		local hours = O.CapUpgradeHours[level]
		if not hours then
			return nil
		end
		return {
			level = level,
			hours = hours,
			cost = O.CapUpgradeCost[level],
			name = ("Vault Timer %d"):format(level),
			label = ("Vault Timer %d — banks %dh offline instead of %dh"):format(
				level, hours, SessionService.offlineCapHours(profile)),
		}
	end

	--- What they earned while away. Returns nil when there is nothing worth
	--- showing a panel for — that is a real answer, not a failure.
	local function computeOffline(profile)
		if not P.Offline then
			return nil
		end
		local lastSeen = math.floor(tonumber(profile.lastSeen) or 0)
		if lastSeen <= 0 then
			return nil            -- no recorded logout: pre-prototype save, or a first session
		end

		local away = os.time() - lastSeen
		-- A clock that went backwards (host migration, NTP correction) must pay
		-- nothing rather than something huge with a sign error in it.
		if away < O.MinimumSeconds then
			return nil
		end

		local perSecond = SessionService.incomePerSecondFor(profile)
		if perSecond <= 0 then
			return nil            -- no factory yet; there is nothing to have missed
		end

		local capSeconds = SessionService.offlineCapHours(profile) * 3600
		local credited = math.min(away, capSeconds)
		local earned = math.floor(credited * perSecond * O.Rate)
		if earned <= 0 then
			return nil
		end

		return {
			seconds = away,
			creditedSeconds = credited,
			earned = earned,
			rate = O.Rate,
			perSecond = perSecond,
			capHours = capSeconds / 3600,
			clipped = away > capSeconds,
			lost = math.max(0, math.floor((away - credited) * perSecond * O.Rate)),
			upgrade = nextCapUpgrade(profile),
		}
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- daily streak
	-- ─────────────────────────────────────────────────────────────────────────────

	local function dailyRewardFor(streak: number)
		-- the ladder loops, so day 8 restarts at day 1's payout and the MILESTONES
		-- carry the long tail
		local index = ((math.max(1, streak) - 1) % #S.DailyRewards) + 1
		local base = S.DailyRewards[index]
		local milestone = S.DailyMilestones[streak]
		return base + (milestone or 0), index, milestone
	end

	--- Streak arithmetic in whole UTC day buckets.
	---
	--- Grace is expressed in buckets rather than hours on purpose: buckets are
	--- coarse (claim at 23:00 and again at 01:00 two buckets later is 26 real
	--- hours), and every rounding error in a grace period should fall on the
	--- player's side. Losing a 20-day streak to one missed evening is how you lose
	--- the player, not the streak.
	local function nextStreak(s): number
		local graceBuckets = 1 + math.floor(S.DailyGraceHours / 24)
		if s.dailyDay <= 0 then
			return 1
		end
		local gap = dayNumber() - s.dailyDay
		if gap <= graceBuckets then
			return s.streak + 1
		end
		return 1
	end

	local function dailyState(profile)
		local s = sessions(profile)
		local streak = nextStreak(s)
		local reward, index, milestone = dailyRewardFor(streak)
		return {
			available = s.dailyDay < dayNumber(),
			streak = s.streak,
			nextStreak = streak,
			dayIndex = index,
			ladder = #S.DailyRewards,
			reward = reward,
			milestone = milestone,
			graceHours = S.DailyGraceHours,
			-- seconds until the next bucket opens, for the "come back in" line
			resetIn = ((dayNumber() + 1) * DAY) - os.time(),
		}
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- playtime ladder
	-- ─────────────────────────────────────────────────────────────────────────────

	local function playtimeReward(index: number): number
		return math.floor(S.PlaytimeRewardBase * (S.PlaytimeRewardGrowth ^ (index - 1)))
	end

	local function playtimeState(entry: Live)
		local rungs = {}
		for index, minutes in ipairs(S.PlaytimeMinutes) do
			local required = minutes * 60
			local status = "locked"
			if entry.claimedPlaytime[index] then
				status = "claimed"
			elseif entry.activeSeconds >= required then
				status = "ready"
			end
			rungs[index] = {
				index = index,
				minutes = minutes,
				reward = playtimeReward(index),
				status = status,
			}
		end
		return {
			activeSeconds = math.floor(entry.activeSeconds),
			rungs = rungs,
		}
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- boost + weekend
	-- ─────────────────────────────────────────────────────────────────────────────

	--- Everything the session layer multiplies income by. Registered onto Economy
	--- at start(), so `Economy.multiplier()` — and therefore every payout and
	--- every income/sec readout — picks it up without Economy knowing this file
	--- exists.
	function SessionService.incomeMultiplier(player: Player): number
		if not P.Sessions then
			return 1
		end
		local profile = DataService.get(player)
		if not profile then
			return 1
		end
		local mult = 1
		if sessions(profile).boostUntil > os.time() then
			mult *= S.BoostMultiplier
		end
		if isWeekend() then
			mult *= S.WeekendMultiplier
		end
		return mult
	end

	local function boostState(profile)
		local s = sessions(profile)
		local now = os.time()
		return {
			active = s.boostUntil > now,
			secondsLeft = math.max(0, s.boostUntil - now),
			cooldownLeft = math.max(0, s.boostReadyAt - now),
			multiplier = S.BoostMultiplier,
			duration = S.BoostSeconds,
			cooldown = S.BoostCooldown,
			weekend = isWeekend(),
			weekendMultiplier = S.WeekendMultiplier,
		}
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- rebirth perks
	-- ─────────────────────────────────────────────────────────────────────────────

	--- The four things a rebirth pays, for a given profile's CURRENT rebirth count.
	---
	--- Exposed rather than applied wholesale because `Tycoon:rebirth()` is owned by
	--- another track and already applies two of them (it increments
	--- profile.rebirths, which is the multiplier, and resets cash to
	--- Config.Economy.StartingCash). This function is the single description of
	--- all four; Economy.applyRebirthGrants() consumes two more, and the fourth is
	--- the TODO below.
	---
	--- Safe to call with the flag off: you get the shipped behaviour (multiplier
	--- only, default starting cash), which is what makes it usable as the one
	--- source of truth for a HUD.
	function SessionService.rebirthPerksFor(profile)
		local n = math.max(0, math.floor(tonumber(profile and profile.rebirths) or 0))
		local perks = {
			rebirths = n,
			multiplier = Config.Rebirth.MultiplierPerRebirth ^ n,
			startingCash = Config.Economy.StartingCash,
			capacityBonus = 0,
			milestone = nil,
			unlocks = {},
		}
		if not P.RebirthPerks or n == 0 then
			return perks
		end

		-- Geometric like the cost curve it is paid against; a flat per-rebirth
		-- grant is invisible by rebirth four.
		perks.startingCash = math.max(
			Config.Economy.StartingCash,
			math.floor(RP.StartingCashPerRebirth * (RP.StartingCashGrowth ^ (n - 1))))

		-- TODO(capacity): the third grant is a PERMANENT CAPACITY BUMP and it is
		-- the one part of this that cannot be applied from outside the tycoon.
		-- The consumer is `Tycoon:spawnDrop()`, whose guard reads
		--
		--     if self.dropCount >= Config.Economy.MaxDropsPerPlot then
		--
		-- and needs to become
		--
		--     local perks = SessionService.rebirthPerksFor(DataService.get(self.owner))
		--     if self.dropCount >= Config.Economy.MaxDropsPerPlot + perks.capacityBonus then
		--
		-- Tycoon.lua is owned by another track, so the number is computed and
		-- replicated here and is simply not read yet. Belt occupancy is verified
		-- in tools/verify_config.lua, so raising the cap needs that check re-run.
		perks.capacityBonus = math.floor(n / RP.SlotEveryRebirths)

		perks.milestone = RP.Milestones[n]
		-- every milestone at or below the current count, so a player who somehow
		-- skipped one (a rollback, an admin grant) still owns everything they passed
		for at, milestone in pairs(RP.Milestones) do
			if n >= at then
				perks.unlocks[milestone.unlock] = milestone.label
			end
		end
		return perks
	end

	--- Has this profile been granted a milestone unlock? The persisted form is
	--- `profile.unlocks[id] = label`, written by Economy.applyRebirthGrants — this
	--- is the read side, for whoever consumes "mezzanine" / "utility2" /
	--- "goldplot" (FloorService and the utility slot own those, not this file).
	function SessionService.hasUnlock(profile, id: string): boolean
		return type(profile) == "table" and type(profile.unlocks) == "table" and profile.unlocks[id] ~= nil
	end

	--- Detected rather than called: Tycoon:rebirth() is off limits, so the rebirth
	--- count is polled once a second and the extra grants land right behind it.
	local function onRebirthDetected(player: Player, profile, entry: Live)
		local perks = SessionService.rebirthPerksFor(profile)
		local granted = Economy.applyRebirthGrants(player, perks)

		local lines = { ("All payouts x%.2f"):format(perks.multiplier) }
		if granted > 0 then
			table.insert(lines, ("Starting cash %s"):format(Util.abbreviate(granted)))
		end
		if perks.capacityBonus > 0 then
			table.insert(lines, ("+%d permanent slot%s"):format(
				perks.capacityBonus, perks.capacityBonus == 1 and "" or "s"))
		end
		if perks.milestone then
			table.insert(lines, ("Unlocked: %s"):format(perks.milestone.label))
		end

		Economy.notify(player, {
			kind = "rebirth",
			title = ("REBIRTH %d PERKS"):format(perks.rebirths),
			body = table.concat(lines, "  •  "),
		})
		entry.dirty = true
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- replication
	-- ─────────────────────────────────────────────────────────────────────────────

	--- The entire replicated payload for one player. Public because it is also the
	--- answer to "what does the server think my session is", which is the only
	--- useful thing to print when a claim button disagrees with the server.
	function SessionService.stateFor(player: Player)
		local entry = live[player]
		local profile = DataService.get(player)
		if not entry or not profile then
			return nil
		end
		return {
			enabled = { offline = P.Offline, sessions = P.Sessions, rebirth = P.RebirthPerks },
			daily = P.Sessions and dailyState(profile) or nil,
			playtime = P.Sessions and playtimeState(entry) or nil,
			boost = P.Sessions and boostState(profile) or nil,
			offline = entry.offline,
			rebirth = P.RebirthPerks and SessionService.rebirthPerksFor(profile) or nil,
		}
	end

	local function pushState(player: Player)
		local entry = live[player]
		local payload = SessionService.stateFor(player)
		if not entry or not payload then
			return
		end
		entry.dirty = false
		entry.lastPush = os.clock()
		sessionState:FireClient(player, payload)
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- claims (server-authoritative; the client sends an intent, never an amount)
	-- ─────────────────────────────────────────────────────────────────────────────

	local function claimOffline(player: Player, entry: Live)
		local pending = entry.offline
		if not P.Offline or not pending then
			return
		end
		-- cleared BEFORE the payout so a double-fired remote cannot pay twice
		entry.offline = nil

		Economy.add(player, pending.earned, false)   -- perSecond already carries the rebirth multiplier
		Economy.push(player)
		Economy.notify(player, {
			kind = "claim",
			title = "OFFLINE TUNG COLLECTED",
			body = ("%s banked from %s away."):format(
				Util.abbreviate(pending.earned), SessionService.describeDuration(pending.seconds)),
		})
		entry.dirty = true
	end

	local function claimDaily(player: Player, entry: Live, profile)
		if not P.Sessions then
			return
		end
		local s = sessions(profile)
		local today = dayNumber()
		if s.dailyDay >= today then
			return                      -- already claimed in this UTC bucket
		end

		local streak = nextStreak(s)
		local reward, _index, milestone = dailyRewardFor(streak)
		s.streak = streak
		s.dailyDay = today

		-- flat, unmultiplied: a login reward that scales with a 2x boost turns the
		-- boost button into a "wait before claiming" puzzle
		Economy.add(player, reward, false)
		Economy.push(player)
		Economy.notify(player, {
			kind = "claim",
			title = ("DAY %d STREAK"):format(streak),
			body = milestone
				and ("%s — including a %s milestone bonus."):format(Util.abbreviate(reward), Util.abbreviate(milestone))
				or ("%s. Come back tomorrow for more."):format(Util.abbreviate(reward)),
		})
		entry.dirty = true
	end

	local function claimPlaytime(player: Player, entry: Live, index: number)
		if not P.Sessions then
			return
		end
		local minutes = S.PlaytimeMinutes[index]
		if not minutes or entry.claimedPlaytime[index] then
			return
		end
		if entry.activeSeconds < minutes * 60 then
			return                      -- the client asked early; the server decides
		end

		entry.claimedPlaytime[index] = true
		local reward = playtimeReward(index)
		Economy.add(player, reward, false)
		Economy.push(player)
		Economy.notify(player, {
			kind = "claim",
			title = ("%d MINUTES PLAYED"):format(minutes),
			body = ("%s. The ladder resets when you leave."):format(Util.abbreviate(reward)),
		})
		entry.dirty = true
	end

	local function claimBoost(player: Player, entry: Live, profile)
		if not P.Sessions then
			return
		end
		local s = sessions(profile)
		local now = os.time()
		if s.boostReadyAt > now then
			return
		end
		s.boostUntil = now + S.BoostSeconds
		s.boostReadyAt = now + S.BoostCooldown

		Economy.push(player)            -- the multiplier readout changes immediately
		Economy.notify(player, {
			kind = "gear",
			title = ("x%g BOOST ACTIVE"):format(S.BoostMultiplier),
			body = ("All income x%g for %d minutes."):format(S.BoostMultiplier, S.BoostSeconds // 60),
		})
		entry.dirty = true
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- activity
	-- ─────────────────────────────────────────────────────────────────────────────

	--- The playtime ladder is gated on ACTIVITY, not wall clock. Paying for
	--- alt-tabbed minutes prices the reward against nothing and rewards the one
	--- behaviour a session loop exists to avoid.
	---
	--- Two signals, because either alone has a hole: position delta misses someone
	--- holding W into a wall, and MoveDirection misses someone being carried by a
	--- conveyor or a knockback. Neither misses someone actually playing.
	local function sampleActivity(entry: Live, dt: number)
		local character = entry.player.Character
		if not character then
			entry.lastPosition = nil
			return
		end
		local root = character:FindFirstChild("HumanoidRootPart")
		if not root then
			return
		end

		local active = false
		local position = (root :: BasePart).Position
		if entry.lastPosition and (position - entry.lastPosition).Magnitude >= ACTIVITY_STUDS then
			active = true
		end
		entry.lastPosition = position

		local humanoid = character:FindFirstChildOfClass("Humanoid")
		if humanoid and humanoid.MoveDirection.Magnitude > 0.1 then
			active = true
		end

		if active then
			local before = entry.activeSeconds
			entry.activeSeconds += dt
			-- a rung becoming claimable is the moment worth replicating
			for index, minutes in ipairs(S.PlaytimeMinutes) do
				local required = minutes * 60
				if before < required and entry.activeSeconds >= required and not entry.claimedPlaytime[index] then
					entry.dirty = true
					Economy.notify(entry.player, {
						kind = "claim",
						title = ("%d MINUTE REWARD READY"):format(minutes),
						body = ("Claim %s from the session panel."):format(Util.abbreviate(playtimeReward(index))),
					})
				end
			end
		end
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- public
	-- ─────────────────────────────────────────────────────────────────────────────

	--- "2 days, 3 hours" — the panel has to state how long they were away, and
	--- "173,244 seconds" is not that.
	function SessionService.describeDuration(seconds: number): string
		seconds = math.max(0, math.floor(seconds))
		local days = seconds // DAY
		local hours = (seconds % DAY) // 3600
		local minutes = (seconds % 3600) // 60
		if days > 0 then
			return ("%dd %dh"):format(days, hours)
		elseif hours > 0 then
			return ("%dh %dm"):format(hours, minutes)
		elseif minutes > 0 then
			return ("%dm"):format(minutes)
		end
		return ("%ds"):format(seconds)
	end

	--- One beat of one player's session. Pulled out of the loop below so the loop
	--- reads as a loop, and so the whole of this file can be driven a step at a
	--- time from outside Roblox.
	function SessionService.step(player: Player, dt: number)
		local entry = live[player]
		local profile = DataService.get(player)
		if not entry or not profile then
			return
		end

		-- Keep the logout stamp fresh every beat. PlayerRemoving also writes it,
		-- but DataService connects its own PlayerRemoving save first and signal
		-- handler order is not a guarantee — this is what actually makes the
		-- offline calculation correct, and it costs a server crash at most one
		-- second of a player's banked time.
		profile.lastSeen = os.time()

		if P.Sessions then
			sampleActivity(entry, dt)
		end

		if P.RebirthPerks then
			local rebirths = math.max(0, math.floor(tonumber(profile.rebirths) or 0))
			if rebirths > entry.rebirths then
				entry.rebirths = rebirths
				onRebirthDetected(player, profile, entry)
			end
		end

		if entry.dirty or os.clock() - entry.lastPush >= PUSH_SECONDS then
			pushState(player)
		end
	end

	function SessionService.onPlayer(player: Player)
		if not enabled() then
			return
		end
		local profile = DataService.get(player) or DataService.load(player)
		if not profile then
			return
		end

		local entry: Live = {
			player = player,
			activeSeconds = 0,
			lastPosition = nil,
			lastClaim = 0,
			claimedPlaytime = {},
			offline = nil,
			rebirths = math.floor(tonumber(profile.rebirths) or 0),
			dirty = true,
			lastPush = 0,
		}
		live[player] = entry

		-- Read lastSeen BEFORE stamping it, then stamp it: from here on this
		-- session owns the clock.
		entry.offline = computeOffline(profile)
		profile.lastSeen = os.time()

		if P.RebirthPerks and entry.rebirths > 0 then
			-- Retroactive unlock sync for a save made before this prototype
			-- existed. startingCash is deliberately zeroed: applyRebirthGrants
			-- tops cash UP to the number it is given, and a join must never be a
			-- way to refill your wallet.
			local perks = SessionService.rebirthPerksFor(profile)
			Economy.applyRebirthGrants(player, { startingCash = 0, unlocks = perks.unlocks })
		end

		if entry.offline then
			Economy.notify(player, {
				kind = "welcome",
				title = "WELCOME BACK",
				body = ("Your factory ran for %s while you were gone."):format(
					SessionService.describeDuration(entry.offline.seconds)),
			})
		end

		-- the client's panel is built on the first push, so send one promptly
		task.delay(1, function()
			if live[player] then
				pushState(player)
			end
		end)
	end

	function SessionService.start()
		if not enabled() then
			return
		end

		if P.Sessions then
			Economy.setMultiplierHook("sessions", SessionService.incomeMultiplier)
		end

		requestClaim.OnServerEvent:Connect(function(player, payload)
			local entry = live[player]
			local profile = DataService.get(player)
			if not entry or not profile or type(payload) ~= "table" then
				return
			end
			-- cheap flood guard: the claims below are all idempotent, but a remote
			-- that can be spammed is a remote that will be
			if os.clock() - entry.lastClaim < CLAIM_COOLDOWN then
				return
			end
			entry.lastClaim = os.clock()

			local kind = payload.kind
			if kind == "offline" then
				claimOffline(player, entry)
			elseif kind == "daily" then
				claimDaily(player, entry, profile)
			elseif kind == "playtime" then
				local index = math.floor(tonumber(payload.index) or 0)
				claimPlaytime(player, entry, index)
			end
			pushState(player)
		end)

		requestBoost.OnServerEvent:Connect(function(player)
			local entry = live[player]
			local profile = DataService.get(player)
			if not entry or not profile then
				return
			end
			if os.clock() - entry.lastClaim < CLAIM_COOLDOWN then
				return
			end
			entry.lastClaim = os.clock()
			claimBoost(player, entry, profile)
			pushState(player)
		end)

		Players.PlayerRemoving:Connect(function(player)
			local profile = DataService.get(player)
			if profile then
				-- Stamped here AND on the tick below. DataService connects its own
				-- PlayerRemoving save before this one and signal handlers are not
				-- ordered guarantees, so the tick is what actually makes this
				-- correct — this line just tightens the last few seconds.
				profile.lastSeen = os.time()
			end
			live[player] = nil
		end)

		-- One loop for everything: a 1-second beat is fine for session state and
		-- keeps the rebirth grant landing visibly right after the rebirth.
		task.spawn(function()
			while true do
				task.wait(1)
				for player in pairs(live) do
					if player.Parent then
						local ok, err = pcall(SessionService.step, player, 1)
						if not ok then
							warn("[Tung] session tick error: " .. tostring(err))
						end
					else
						live[player] = nil
					end
				end
			end
		end)
	end

	return SessionService
end


__MODULES["Tycoon"] = function()
	--[[
		Tycoon.lua — the standardized tycoon.

		One instance per plot. Everything it builds comes from Config.Buttons, so
		adding content is a data edit, never a code edit. The contract for a new
		entry is just:

			kind = "Dropper"   -> needs slot, variant, dropValue, dropRate
			kind = "Upgrader"  -> needs slot, variant, multiplier
			kind = "Belt"      -> needs speedBonus
			kind = "Structure" -> needs structure ("walls" | "roof")
			kind = "Gear"      -> needs grants (a Config.Bats id)

		Add a case to INSTALLERS below to invent a new kind.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Style = Req("Style")
	local Util = Req("Util")
	local Fx = Req("Fx")
	local TungModels = Req("TungModels")
	local Economy = Req("Economy")
	local DataService = Req("DataService")
	local CombatService = Req("CombatService")
	local MapBuilder = Req("MapBuilder")

	local RunService = game:GetService("RunService")

	local L = Config.Layout
	local BTN = Config.Style.Button
	local BTN_LOCKED = Config.Style.ButtonLocked
	local W = Config.World

	local Tycoon = {}
	Tycoon.__index = Tycoon

	--- Every plot built this session, in plot order. PlotService owns the plots and
	--- hands them out by player; a service that has to walk ALL of them (like
	--- FloorService) has nowhere else to get the list.
	local INSTANCES: { any } = {}

	function Tycoon.all(): { any }
		return INSTANCES
	end

	-- Buttons that aren't attached to a belt machine sit in a row on the open
	-- floor, spaced further apart than a button is wide. Positions live in Config
	-- so they scale with the plot instead of drifting into the wall when it grows.
	local MISC_SPOTS = L.MiscButtons

	local COLORS = {
		frame     = Color3.fromRGB(118, 122, 130),
		metal     = Color3.fromRGB(160, 164, 172),
		belt      = Color3.fromRGB(62, 62, 68),
		beltLine  = Color3.fromRGB(255, 176, 60),
		buttonOn  = Color3.fromRGB(110, 235, 150),
		buttonOff = Color3.fromRGB(230, 90, 90),
		preview   = Color3.fromRGB(126, 122, 146),
		vault     = Color3.fromRGB(146, 110, 72),
		gold      = Color3.fromRGB(255, 205, 90),
	}

	-- ─────────────────────────────────────────────────────────────────────────────
	-- construction helpers
	-- ─────────────────────────────────────────────────────────────────────────────

	local function newPart(parent, name, size, cf, color, material, collide)
		local p = Instance.new("Part")
		p.Name = name
		p.Size = size
		p.CFrame = cf
		p.Color = color
		p.Material = material or Enum.Material.SmoothPlastic
		p.Anchored = true
		p.CanCollide = collide ~= false
		p.TopSurface = Enum.SurfaceType.Smooth
		p.BottomSurface = Enum.SurfaceType.Smooth
		p.Parent = parent
		return p
	end

	-- ── machine geometry ─────────────────────────────────────────────────────────

	--- The masses a belt machine is made of: { name, size, offset, y, collide }.
	--- Offset is outboard of the belt, y is the centre height, both in the leg's
	--- own frame (see Tycoon:segmentCF).
	---
	--- This exists so the GHOST PREVIEW and the real machine are built from one
	--- description. A silhouette hand-copied from the installer is a silhouette
	--- that stops matching the machine the first time either is touched.
	local MACHINE_MASSES = {
		Dropper = function()
			-- Sized to Layout.MachineFootprint so neighbouring droppers can never
			-- overlap. The arm hangs directly over the running surface, so it is
			-- non-collidable: a tall drop has to pass under it untouched.
			local depth = L.MachineFootprint
			return {
				{ "Base", Vector3.new(depth, 3.6, depth), L.MachineOffset, 1.8, true },
				{ "Core", Vector3.new(depth - 1.4, 2.2, depth - 1.4), L.MachineOffset, 4.7, true },
				{ "Arm", Vector3.new(L.MachineOffset, 1, 1.4), L.MachineOffset / 2, L.BeltY + 5, false },
				{ "Spout", Vector3.new(2.4, 1.8, 2.4), 0, L.BeltY + 4.2, false },
				{ "Nozzle", Vector3.new(1.8, 0.5, 1.8), 0, L.BeltY + 3.2, false },
			}
		end,
		Upgrader = function()
			-- Single post on the OUTBOARD side with a cantilevered beam, rather
			-- than an arch straddling the belt: keeps the inboard walkway clear.
			local reach = L.MachineOffset + L.BeltWidth / 2
			return {
				{ "Post", Vector3.new(1.8, 6, 1.8), L.MachineOffset, 3, true },
				{ "Beam", Vector3.new(reach, 1.5, 2.2), (L.MachineOffset - L.BeltWidth / 2) / 2, L.BeltY + 4.6, false },
				{ "Scanner", Vector3.new(L.BeltWidth, 3.6, 1), 0, L.BeltY + 1.8, false },
			}
		end,
	}

	-- ── belt paths ───────────────────────────────────────────────────────────────

	--- Turns a path definition ({ id, y, points, outboard, collectorAt }) into
	--- resolved legs.
	---
	--- `outboard` is the SIDE each leg's machines stand on: its outboard normal is
	--- sign * (-dir.Z, 0, dir.X). It used to be inferred with
	--- `normal:Dot(midpoint) < 0` — "point away from the plot origin" — which holds
	--- only while every leg hugs an outer edge, and silently inverts for any leg
	--- whose midpoint doesn't. An upper floor's return leg runs back across the
	--- middle of its own deck, where the inferred side flips and puts the machines
	--- over the walkway and the buy buttons out in space. So the side is carried,
	--- not guessed. Both ground legs are +1, which is exactly what the old
	--- heuristic produced.
	local function resolvePath(def, outboard: { number }?)
		outboard = outboard or def.outboard
		local points = def.points
		assert(points and #points >= 2, "a belt path needs at least two points")

		local legs = {}
		for index = 1, #points - 1 do
			local a, b = points[index], points[index + 1]
			local delta = b - a
			local dir = delta.Unit
			local sign = (outboard and outboard[index]) or 1
			legs[index] = {
				a = a,
				b = b,
				dir = dir,
				length = delta.Magnitude,
				normal = Vector3.new(-dir.Z, 0, dir.X) * sign,
			}
		end

		return {
			id = def.id,
			y = def.y or 0,
			legs = legs,
			collectorAt = def.collectorAt,
			surfaces = {},
		}
	end

	--- Builds a machine's masses into `parent` and returns them keyed by name.
	function Tycoon:buildMasses(def, parent: Instance, color: Color3, material: Enum.Material)
		local shape = MACHINE_MASSES[def.kind]
		if not shape then
			return {}
		end
		local legIndex, distance, pathIndex = self:legOf(def)
		local parts = {}
		for _, mass in ipairs(shape()) do
			local name, size, offset, y, collide = mass[1], mass[2], mass[3], mass[4], mass[5]
			parts[name] = newPart(parent, name, size,
				self:segmentCF(legIndex, distance, offset, y, pathIndex), color, material, collide)
		end
		return parts, legIndex, distance, pathIndex
	end

	-- ─────────────────────────────────────────────────────────────────────────────

	function Tycoon.new(index: number, parent: Instance)
		local self = setmetatable({}, Tycoon)

		self.index = index
		self.owner = nil :: Player?
		self.owned = {}
		self.objects = {}
		self.generation = 0
		self.beltSpeed = L.BeltSpeed
		self.dropCount = 0

		-- Folders that come and go with the factory. Registered as they are built
		-- rather than listed in setFactoryVisible; see registerFactoryFolder.
		self.factoryFolders = {}
		self.factoryShown = true
		self.ownedChangedListeners = {}

		-- BELT PATHS ARE REGISTERED UP FRONT, all of them, including floors nobody
		-- has bought yet. A path is pure maths — legs, directions, normals — and
		-- registering it builds nothing. It has to happen here because buy buttons
		-- are built once, on first claim, and a button standing on the mezzanine
		-- needs that path to exist to know its own height. The floor's PARTS still
		-- wait for the purchase.
		self.paths = {}
		for _, path in ipairs(Config.BeltPaths) do
			self:addBeltPath(path)
		end

		local model, cf = MapBuilder.buildPlotPad(parent, index)
		self.model = model
		self.cf = cf
		self.padPart = model:FindFirstChild("Pad")

		self.machines = Instance.new("Folder")
		self.machines.Name = "Machines"
		self.machines.Parent = model
		self:registerFactoryFolder(self.machines)

		-- Side-track props: the cabinets and whatever stands on their shelves.
		-- A SEPARATE folder from self.machines specifically because rebirth does
		-- machines:ClearAllChildren() — putting a bat display in there would wipe
		-- the cabinet every prestige while its purchase survived in the profile.
		-- release() still clears this one: new owner, different tiers.
		self.props = Instance.new("Folder")
		self.props.Name = "Props"
		self.props.Parent = model
		self:registerFactoryFolder(self.props)

		self.buttonsFolder = Instance.new("Folder")
		self.buttonsFolder.Name = "Buttons"
		self.buttonsFolder.Parent = model

		self.drops = Instance.new("Folder")
		self.drops.Name = "Drops"
		self.drops.Parent = model

		self:buildBelt(1)
		self:buildCollector(1, nil, true)
		self:buildRebirthPad()
		self:buildClaimPad()
		self:ensureCabinets()

		-- An unclaimed plot shows a bare pad and a claim marker, nothing else.
		-- Leaving the vault and belt standing on an empty plot is what makes it
		-- look like there's a big block parked in front of the thing you're
		-- meant to walk onto.
		self:setFactoryVisible(false)
		self:updateSign()

		table.insert(INSTANCES, self)
		return self
	end

	--- Listener for "what this plot owns has changed" — a purchase, a claim, a
	--- release, a rebirth. FloorService hangs the mezzanine off this rather than
	--- polling every plot on a timer. One listener, because there is exactly one
	--- consumer; make it a list the day there are two.
	--- A LIST, as the comment here has been asking for. It was one slot with
	--- "make it a list the day there are two" written over it, and FloorService
	--- held it. There are two now.
	function Tycoon:onOwnedChanged(fn: ((any) -> ())?)
		if fn then
			table.insert(self.ownedChangedListeners, fn)
		end
	end

	function Tycoon:fireOwnedChanged()
		for _, fn in ipairs(self.ownedChangedListeners) do
			-- pcall'd per listener: one that throws must take neither the purchase
			-- nor the listeners after it down with it
			local ok, err = pcall(fn, self)
			if not ok then
				warn("[Tung] owned-changed listener error on plot " .. self.index .. ": " .. tostring(err))
			end
		end
	end

	--- Buy buttons are built on first claim, not at server start: every plot x 21
	--- buttons is a lot of instances to create just to immediately hide them.
	function Tycoon:ensureButtons()
		if self.buttonsBuilt then
			return
		end
		self.buttonsBuilt = true
		self:buildButtons()
	end

	--- Adds a folder to the set that appears and disappears with the factory.
	---
	--- Registration rather than a literal list, because setFactoryVisible used to
	--- walk `for i = 1, 4` over one: the fifth folder anyone added was silently
	--- left standing on an unclaimed plot, which is the exact bug the hidden
	--- factory exists to prevent. A folder registered while the factory is hidden
	--- is hidden immediately, so late arrivals (an upper floor) can't leak either.
	function Tycoon:registerFactoryFolder(folder: Instance)
		table.insert(self.factoryFolders, folder)
		if not self.factoryShown then
			folder.Parent = nil
		end
	end

	--- Shows/hides the whole factory. Machinery lives in folders so this is a
	--- reparent rather than a rebuild.
	function Tycoon:setFactoryVisible(visible: boolean)
		self.factoryShown = visible
		local target = visible and self.model or nil
		for _, folder in ipairs(self.factoryFolders) do
			folder.Parent = target
		end
	end

	function Tycoon:at(x: number, y: number, z: number): CFrame
		return self.cf * CFrame.new(x, y, z)
	end

	--- Where the owner is placed on claim and on every respawn: just inside the
	--- gateway, on the open aisle, looking down plot-local -Z. A CFrame looks
	--- along its own -Z by default, so with no rotation you land facing the length
	--- of the factory with the belt on your left and the buy buttons ahead of you.
	function Tycoon:ownerSpawnCFrame(): CFrame
		local spot = L.OwnerSpawnAt
		return self:at(spot.X, spot.Y, spot.Z)
	end

	-- ── belt ─────────────────────────────────────────────────────────────────────

	--- Builds the running surface, the corner sensors and the flow markers for one
	--- belt path. Called once for the ground floor at construction, and once more
	--- per floor above it — `parent` lets a floor keep its belt in its own folder
	--- so tearing the floor down takes the belt with it.
	function Tycoon:buildBelt(pathIndex: number?, parent: Instance?)
		pathIndex = pathIndex or 1

		local folder = parent
		if not folder then
			folder = Instance.new("Folder")
			folder.Name = "Belt"
			folder.Parent = self.model
			self.beltFolder = folder
			self:registerFactoryFolder(folder)
		end

		local width = L.BeltWidth
		local half = width / 2
		local surfaceY = L.BeltY
		local legs = self:legCount(pathIndex)

		--[[
			SEAMLESS CORNER, AND NOTHING SOLID NEAR THE BELT.

			The drops are driven by a LinearVelocity in Plane mode, which pins
			their lateral velocity to exactly zero — they physically cannot drift
			sideways off the belt. Side rails were therefore never load-bearing,
			and because each leg's rails ran its FULL length, leg 2's inboard rail
			crossed leg 1's path and vice versa: two solid walls straight across
			the conveyor, plus an 11x11 corner block sitting on the bend. That is
			what the drops were piling up against.

			So: the running surface is the only collidable thing here. The edge
			trim is decoration with CanCollide off, and every leg's surface runs
			THROUGH its corner square so there is no separate plate to seam
			against — the next leg simply starts a little way inside it.
		]]
		local function buildRun(index, fromDist, toDist)
			local length = toDist - fromDist
			local mid = (fromDist + toDist) / 2

			newPart(folder, "BeltBase" .. index, Vector3.new(width + 1.2, surfaceY - 0.2, length),
				self:segmentCF(index, mid, 0, (surfaceY - 0.2) / 2, pathIndex), COLORS.frame, Enum.Material.DiamondPlate)

			local surface = newPart(folder, "BeltSurface" .. index, Vector3.new(width, 0.4, length),
				self:segmentCF(index, mid, 0, surfaceY - 0.2, pathIndex), COLORS.belt, Enum.Material.SmoothPlastic)
			surface.CustomPhysicalProperties = PhysicalProperties.new(0.7, 0.02, 0.05, 1, 1)

			local texture = Instance.new("Texture")
			texture.Face = Enum.NormalId.Top
			texture.Texture = "rbxasset://textures/particles/sparkles_main.dds"
			texture.Transparency = 0.75
			texture.StudsPerTileU = 5
			texture.StudsPerTileV = 5
			texture.Color3 = COLORS.beltLine
			texture.Parent = surface

			-- Decorative edge trim ONLY on the outer side of the L, and never
			-- collidable. The inner side is left completely open so the two legs
			-- flow into each other.
			local trim = newPart(folder, "Trim" .. index, Vector3.new(0.5, 0.5, length),
				self:segmentCF(index, mid, half + 0.25, surfaceY + 0.15, pathIndex),
				COLORS.beltLine, Enum.Material.Neon, false)
			trim.CanQuery = false

			return surface
		end

		local path = self:beltPath(pathIndex)
		local surfaces = {}
		for index = 1, legs do
			local _, _, _, length = self:leg(index, pathIndex)
			-- The first leg starts a stud behind the first dropper; every other one
			-- starts just INSIDE the corner square its predecessor already covers,
			-- overlapping slightly so the two surfaces share a face rather than
			-- meeting at a hairline seam.
			local fromDist = (index == 1) and -1 or (half - 0.6)
			-- Every leg but the last owns the square at its far end: it runs half a
			-- belt-width past the bend so there is no separate corner plate.
			local toDist = (index == legs) and length or (length + half)
			surfaces[index] = buildRun(index, fromDist, toDist)
		end
		path.surfaces = surfaces

		-- Visual end cap behind the first dropper. Non-collidable: nothing should
		-- ever reach it, and if something does we want it to slide off, not wedge.
		local cap = newPart(folder, "BeltCap", Vector3.new(width + 1.2, 1.6, 0.6),
			self:segmentCF(1, -1.2, 0, surfaceY + 0.8, pathIndex), COLORS.metal, Enum.Material.Metal, false)
		cap.CanQuery = false

		-- One trigger per bend, spanning the belt, handing a drop from leg i's
		-- direction to leg i+1's. No geometry, just a retarget — so an N-legged
		-- path costs N-1 triggers and still no per-frame work.
		for index = 1, legs - 1 do
			local _, _, _, length = self:leg(index, pathIndex)
			local turn = newPart(folder, "TurnSensor" .. index, Vector3.new(width + 1, 6, 2.5),
				self:segmentCF(index, length, 0, surfaceY + 3, pathIndex),
				Color3.new(1, 1, 1), Enum.Material.Neon, false)
			turn.Transparency = 1
			turn.CanQuery = false
			turn.CanTouch = true
			turn.Touched:Connect(function(hit)
				self:onTurn(hit, pathIndex, index)
			end)
		end

		self:buildFlowMarkers(folder, pathIndex)
	end

	--- Chevrons painted on the floor beside the belt, pointing downstream.
	---
	--- An L-shaped conveyor with machinery on both sides does not tell you which
	--- end is the start. Following the arrows takes you from the first dropper to
	--- the vault, which is also the order the buy buttons come in — so "walk the
	--- arrows" is the whole tutorial for reading a plot.
	function Tycoon:buildFlowMarkers(parent: Instance, pathIndex: number?)
		local SPACING = 18
		local INBOARD = -(L.BeltWidth / 2 + 2.5)   -- clear of the belt, clear of the buttons

		for legIndex = 1, self:legCount(pathIndex) do
			local _, _, _, length = self:leg(legIndex, pathIndex)
			local at = SPACING * 0.5
			while at < length do
				-- two bars meeting at a point: a wedge read from above is just a
				-- rectangle, so the arrowhead has to be drawn rather than modelled
				for _, side in ipairs({ 1, -1 }) do
					local bar = newPart(parent, "Flow", Vector3.new(0.7, 0.25, 4),
						self:segmentCF(legIndex, at, INBOARD, 0.12, pathIndex)
							* CFrame.new(side * 1.1, 0, -1.1)
							* CFrame.Angles(0, math.rad(side * 32), 0),
						COLORS.beltLine, Enum.Material.Neon, false)
					bar.Transparency = 0.25
					bar.CanQuery = false
					bar.CanTouch = false
				end
				at += SPACING
			end
		end
	end

	--- Hands a drop from leg `fromLeg` of a path onto leg `fromLeg + 1`. Every
	--- corner on every floor shares this; the sensor closes over which one it is,
	--- so nothing here knows how many legs the path has.
	function Tycoon:onTurn(hit: BasePart, pathIndex: number, fromLeg: number)
		local drop = hit.Parent
		if not drop or not drop:IsA("Model") then
			return
		end
		if drop:GetAttribute("PlotIndex") ~= self.index then
			return
		end
		-- Drops that predate multi-floor have no Path attribute; treat them as the
		-- ground floor rather than dropping them on the corner.
		if (drop:GetAttribute("Path") or 1) ~= pathIndex or drop:GetAttribute("Leg") ~= fromLeg then
			return
		end
		local toLeg = fromLeg + 1
		drop:SetAttribute("Leg", toLeg)

		local body = drop.PrimaryPart
		if not body then
			return
		end
		local mover = body:FindFirstChild("BeltMover")
		local upkeep = body:FindFirstChild("StayUpright")
		local direction = self:legDirectionWorld(toLeg, pathIndex)

		if mover and mover:IsA("LinearVelocity") then
			mover.PrimaryTangentAxis = direction
			mover.SecondaryTangentAxis = self:legNormalWorld(toLeg, pathIndex)
			mover.PlaneVelocity = Vector2.new(self.beltSpeed, 0)
		end
		if upkeep and upkeep:IsA("AlignOrientation") then
			upkeep.CFrame = TungModels.dropOrientation(direction)
		end
	end

	-- ── belt geometry ────────────────────────────────────────────────────────────
	-- A belt is a POLYLINE, not an L. `points` is the corner list and everything —
	-- runs, corner sensors, machines, buttons, flow markers — derives from leg(i),
	-- so a path with five corners builds exactly like the shipped two-legged one.
	-- The ground floor is Config.BeltPaths[1], which is itself written in terms of
	-- Layout.BeltStart / BeltCorner / BeltEnd so the two cannot drift apart.

	--- Registers a belt path and returns its index. Idempotent by id, because a
	--- floor that is torn down and rebuilt must not stack up a second copy of its
	--- own geometry — the path is pure maths, only the parts get rebuilt.
	function Tycoon:addBeltPath(def, outboard: { number }?): number
		for index, existing in ipairs(self.paths) do
			if existing.id == def.id then
				return index
			end
		end
		table.insert(self.paths, resolvePath(def, outboard or def.outboard))
		return #self.paths
	end

	function Tycoon:beltPath(pathIndex: number?)
		return self.paths[pathIndex or 1]
	end

	function Tycoon:legCount(pathIndex: number?): number
		return #self:beltPath(pathIndex).legs
	end

	--- start, finish, unit direction, length and the outboard normal of a leg,
	--- all in PLOT-LOCAL space, plus the path it belongs to.
	function Tycoon:leg(index: number, pathIndex: number?)
		local path = self:beltPath(pathIndex)
		local leg = path.legs[index]
		return leg.a, leg.b, leg.dir, leg.length, leg.normal, path
	end

	--- A point `distance` along a leg, offset sideways. Positive offset is
	--- outboard (toward the plot edge), negative is inboard (toward the floor).
	--- The path's own height is baked in, so a leg on the mezzanine lands on the
	--- mezzanine without every caller having to know which floor it is on.
	function Tycoon:pointOnLeg(index: number, distance: number, offset: number, pathIndex: number?): Vector3
		local a, _, dir, _, normal, path = self:leg(index, pathIndex)
		return a + dir * distance + normal * (offset or 0) + Vector3.new(0, path.y, 0)
	end

	function Tycoon:legDirectionWorld(index: number, pathIndex: number?): Vector3
		local _, _, dir = self:leg(index, pathIndex)
		return self.cf:VectorToWorldSpace(dir).Unit
	end

	function Tycoon:legNormalWorld(index: number, pathIndex: number?): Vector3
		local _, _, _, _, normal = self:leg(index, pathIndex)
		return self.cf:VectorToWorldSpace(normal).Unit
	end

	--- Which leg (and which floor's belt) a machine lives on: droppers on the back
	--- edge of the ground floor, upgraders on its left edge.
	---
	--- A def may pin itself instead, which is how FloorService stands a dropper on
	--- an upper floor without inventing a second slot table.
	function Tycoon:legOf(def): (number, number, number)
		if def.legIndex then
			return def.legIndex, def.legDistance or 0, self:pathIndexOf(def)
		end
		if def.kind == "Dropper" then
			return 1, L.DropperDist[def.slot], 1
		end
		return 2, L.UpgraderDist[def.slot], 1
	end

	--- Which registered path a def means. A button carries `path` as an ID rather
	--- than an index, because the index is assigned at runtime by addBeltPath and
	--- Config has no way to know it. Falls back to the ground floor, which is what
	--- every button without a `path` means.
	function Tycoon:pathIndexOf(def): number
		if def.pathIndex then
			return def.pathIndex
		end
		if def.path then
			for index, path in ipairs(self.paths) do
				if path.id == def.path then
					return index
				end
			end
			warn("[Tung] button " .. tostring(def.id) .. " names belt path " .. tostring(def.path) .. ", which is not registered")
		end
		return 1
	end

	--- World CFrame of a box lying along a leg.
	function Tycoon:segmentCF(index: number, distance: number, offset: number, y: number, pathIndex: number?): CFrame
		local _, _, dir = self:leg(index, pathIndex)
		local point = self:pointOnLeg(index, distance, offset, pathIndex) + Vector3.new(0, y, 0)
		return self.cf * CFrame.lookAt(point, point + dir)
	end

	--- Every live belt surface on the plot, on every floor. Skips destroyed ones:
	--- tearing a floor down leaves its surfaces referenced but dead, and writing a
	--- property on a destroyed part throws.
	function Tycoon:eachBeltSurface(fn: (BasePart) -> ())
		for _, path in ipairs(self.paths) do
			for _, surface in ipairs(path.surfaces) do
				if surface.Parent then
					fn(surface)
				end
			end
		end
	end

	-- ── collector ────────────────────────────────────────────────────────────────

	--- Run-off ramp, collect sensor and the body that catches the drops, at the end
	--- of a path's last leg.
	---
	--- `headline` adds the vault dressing — gold trim, statue, income sign. Only
	--- the ground floor gets it: a second statue on every upper floor is noise, and
	--- the income readout on it would be wrong anyway (it reports the whole plot).
	function Tycoon:buildCollector(pathIndex: number?, parent: Instance?, headline: boolean?)
		pathIndex = pathIndex or 1
		local path = self:beltPath(pathIndex)

		local folder = parent
		if not folder then
			folder = Instance.new("Folder")
			folder.Name = "Collector"
			folder.Parent = self.model
			self.collectorFolder = folder
			self:registerFactoryFolder(folder)
		end

		-- The catcher sits past the end of the last leg. Its shell must stay
		-- entirely DOWNSTREAM of the sensor: a solid body overlapping the run-off
		-- walls the belt off and nothing can ever be collected.
		local _, beltEnd, exitDir = self:leg(self:legCount(pathIndex), pathIndex)
		local bodyDepth = headline and 10 or 8
		local bodyWidth = headline and 18 or 13
		local bodyHeight = headline and 9 or 6.5
		local centre = path.collectorAt
		local runOff = (centre - beltEnd).Magnitude
		assert(runOff > bodyDepth / 2 + 3,
			("Collector body overlaps the belt run-off on path %q; move its collectorAt further out"):format(tostring(path.id)))

		-- Path-local: `y` is measured from the floor this belt runs on, exactly as
		-- it is everywhere else on the path.
		local function alongExit(distance, y, lateral)
			local point = beltEnd + exitDir * distance + Vector3.new(0, y + path.y, 0)
				+ Vector3.new(-exitDir.Z, 0, exitDir.X) * (lateral or 0)
			return self.cf * CFrame.lookAt(point, point + exitDir)
		end

		newPart(folder, "VaultBase", Vector3.new(bodyWidth, bodyHeight, bodyDepth),
			alongExit(runOff, bodyHeight / 2, 0), COLORS.vault, Enum.Material.WoodPlanks)
		newPart(folder, "VaultTrim", Vector3.new(bodyWidth + 1, 1.2, bodyDepth + 1),
			alongExit(runOff, bodyHeight + 0.4, 0), COLORS.gold, Enum.Material.Metal)

		-- funnel mouth facing back down the belt
		local mouth = newPart(folder, "Mouth", Vector3.new(bodyWidth - 6, 6, 1.5),
			alongExit(runOff - bodyDepth / 2 - 0.5, L.BeltY + 3, 0),
			Color3.fromRGB(30, 24, 40), Enum.Material.Neon, false)
		mouth.Transparency = 0.5

		-- run-off ramp carrying drops off the end of the belt into the sensor
		local ramp = newPart(folder, "Ramp", Vector3.new(L.BeltWidth, 0.6, 5), alongExit(2.4, L.BeltY - 0.2, 0),
			COLORS.belt, Enum.Material.SmoothPlastic)
		ramp.CustomPhysicalProperties = PhysicalProperties.new(0.7, 0.05, 0.1, 1, 1)

		local sensor = newPart(folder, "Sensor", Vector3.new(L.BeltWidth + 3, 7, 2.5), alongExit(2, L.BeltY + 3, 0),
			Color3.fromRGB(255, 255, 255), Enum.Material.Neon, false)
		sensor.Transparency = 1
		sensor.CanTouch = true

		sensor.Touched:Connect(function(hit)
			self:onCollect(hit)
		end)

		if not headline then
			return
		end

		-- sign
		local signAnchor = newPart(folder, "SignAnchor", Vector3.new(1, 1, 1), alongExit(runOff, 12, 0), COLORS.vault, nil, false)
		signAnchor.Transparency = 1

		local billboard = Style.billboard(signAnchor, {
			name = "Sign", width = 20, height = 6, distance = "plot",
		})
		local label = Style.text(billboard, {
			name = "Rate", text = "SAHUR VAULT", color = COLORS.gold,
		})
		self.vaultLabel = label

		local statue = TungModels.buildStatue("classic", 1.6)
		statue:PivotTo(alongExit(runOff, 13.5, 0) * CFrame.Angles(0, math.pi, 0))
		statue.Parent = folder
		self.vaultStatue = statue
	end

	function Tycoon:onCollect(hit: BasePart)
		local model = hit.Parent
		if not model or not model:IsA("Model") then
			return
		end
		local rawValue = model:GetAttribute("Value")
		if not rawValue then
			return
		end
		if model:GetAttribute("PlotIndex") ~= self.index then
			return
		end
		model:SetAttribute("Value", nil)  -- claim it immediately, touch fires twice

		-- THE MEZZANINE FEEDS THE SAME REFINERY.
		--
		-- Upgraders are physical scanners on the ground floor's leg 2, so a drop
		-- from an upper floor crosses none of them and arrives at its raw value.
		-- Left that way the second floor is an ADDITIVE term against a curve that
		-- multiplies: modelled, the mezzanine's dropper is 17% of plot income the
		-- minute you buy it, 4% one button later, and 0.02% by the end of the
		-- build. You would buy a storey at minute forty and watch it become noise.
		--
		-- So a path with no upgraders of its own is refined by the plot's, at the
		-- one place income is realised. Three lines, and it makes the existing
		-- "sum the droppers, multiply by the upgraders" shape — which Tycoon,
		-- SessionService and the verifier's economy sim each implement separately
		-- — correct for both floors with no change to any of them.
		local value = self:refineryMultiplierFor(model:GetAttribute("Path")) * rawValue

		local owner = self.owner
		self.dropCount = math.max(0, self.dropCount - 1)

		if owner and owner.Parent then
			local gained = Economy.add(owner, value, true)
			-- late game the vault eats ~10 drops/sec; throttle the confetti so a
			-- finished factory doesn't spam hundreds of billboards per minute
			local now = os.clock()
			if now - (self.lastPayoutFx or 0) > 0.3 then
				self.lastPayoutFx = now
				Fx.floatingText(hit.Position + Vector3.new(0, 3, 0), "+" .. Util.abbreviate(gained), COLORS.gold, self.model)
				Fx.tung(hit, 0.9 + math.random() * 0.35, 0.18)
			end
		end
		model:Destroy()
	end

	-- ── claim pad ────────────────────────────────────────────────────────────────

	function Tycoon:buildClaimPad()
		local folder = Instance.new("Folder")
		folder.Name = "Claim"
		folder.Parent = self.model
		self.claimFolder = folder

		local frontX, frontZ = L.ClaimPadAt.X, L.ClaimPadAt.Z

		-- The pad itself. Safe to centre now that the factory is hidden while
		-- unclaimed -- there is nothing standing on the frontage to hide behind.
		local pad = newPart(folder, "ClaimPad", Vector3.new(34, 1.2, 20),
			self:at(frontX, 0.6, frontZ), Color3.fromRGB(120, 230, 160), Enum.Material.Neon)
		pad.CanCollide = false
		pad:SetAttribute("PlotIndex", self.index)
		self.claimPad = pad

		-- A beacon, because a flat pad on the floor is invisible from more than a
		-- few studs away or from any angle that isn't directly above it. THIS is
		-- the thing you actually navigate by.
		local beacon = newPart(folder, "ClaimBeacon", Vector3.new(7, 80, 7),
			self:at(frontX, 40, frontZ), Color3.fromRGB(120, 255, 170), Enum.Material.Neon, false)
		beacon.Transparency = 0.55
		beacon.CanQuery = false

		local halo = newPart(folder, "ClaimHalo", Vector3.new(0.6, 44, 44),
			self:at(frontX, 0.35, frontZ) * CFrame.Angles(0, 0, math.pi / 2),
			Color3.fromRGB(80, 220, 130), Enum.Material.Neon, false)
		halo.Shape = Enum.PartType.Cylinder
		halo.Transparency = 0.4
		halo.CanQuery = false

		-- Sign high up the beacon so it clears the walls of neighbouring plots and
		-- is readable from the arena.
		local signAnchor = newPart(folder, "ClaimSign", Vector3.new(1, 1, 1),
			self:at(frontX, 62, frontZ), Color3.new(1, 1, 1), nil, false)
		signAnchor.Transparency = 1
		signAnchor.CanQuery = false

		-- `world`, not `plot`: a free plot has to be findable from anywhere on the
		-- ring, and the two furthest-apart plots are a full diameter apart. This is
		-- the one label whose old 1200 was doing a real job rather than being the
		-- number somebody happened to type.
		local billboard = Style.billboard(signAnchor, {
			name = "ClaimSign", width = 34, height = 12, distance = "world",
		})
		local label = Style.text(billboard, {
			text = "PLOT " .. self.index .. "\nFREE — WALK ON IT",
			color = Color3.fromRGB(190, 255, 215),
		})
		self.claimLabel = label
	end

	-- ── rebirth pad ──────────────────────────────────────────────────────────────

	--- The side-track cabinets: a display case standing behind each track's column
	--- of buy buttons.
	---
	--- These carry the wayfinding that the side tracks would otherwise have to
	--- take from `pointAt`. There is exactly ONE Highlight per plot and it belongs
	--- to the factory (Highlight is capped at 255 per client and disabled ones
	--- still occupy a slot), so a cabinet announces itself with a sign instead —
	--- which is better anyway, because a sign can say what it is and a glow
	--- cannot.
	--- Builds the cabinets a plot has earned, and takes down the ones it has not.
	---
	--- Called from the constructor and again on every ownership change, because a
	--- cabinet is no longer permanent plot furniture: it arrives with the second
	--- floor, it goes when the plot is released, and it survives a rebirth on the
	--- strength of the tiers you keep. Idempotent, so calling it on every purchase
	--- costs a table walk and nothing else.
	function Tycoon:ensureCabinets()
		self.cabinetSigns = self.cabinetSigns or {}

		for _, track in ipairs(Config.TrackOrder) do
			if track ~= "factory" and Config.Layout.Tracks[track] then
				local existing = self.props:FindFirstChild("Cabinet_" .. track)
				local wanted = Config.trackUnlocked(track, self.owned)

				if not wanted then
					if existing then
						existing:Destroy()
						self.cabinetSigns[track] = nil
					end
					continue
				end
				if existing then
					continue
				end

				local centre, size = Config.trackCabinet(track)
				local model = Instance.new("Model")
				model.Name = "Cabinet_" .. track
				model.Parent = self.props

				local baseCF = self:at(centre.X, 0, centre.Z)
				newPart(model, "Back", size, baseCF * CFrame.new(0, size.Y / 2, 0),
					COLORS.metal, Enum.Material.Metal, true)
				newPart(model, "Trim", Vector3.new(size.X + 1.2, 0.8, size.Z + 1.2),
					baseCF * CFrame.new(0, size.Y + 0.4, 0), COLORS.gold, Enum.Material.Metal, false)

				local anchor = newPart(model, "SignAnchor", Vector3.new(1, 1, 1),
					baseCF * CFrame.new(0, size.Y + 2.5, 0), COLORS.metal, Enum.Material.Metal, false)
				anchor.Transparency = 1

				local billboard = Style.billboard(anchor, {
					name = "Sign", width = 18, height = 4, distance = "prop",
				})
				local label = Style.text(billboard, {
					name = "Label", color = COLORS.gold,
					text = (Config.TrackLabel[track] or track:upper()) .. " CABINET",
				})

				self.cabinetSigns[track] = label
			end
		end
	end

	--- Keeps each cabinet sign honest about how far up its track you are.
	function Tycoon:updateCabinetSigns()
		if not self.cabinetSigns then
			return
		end
		for track, label in pairs(self.cabinetSigns) do
			-- a cabinet that has been taken down leaves its sign behind in this map
			if not label.Parent then
				self.cabinetSigns[track] = nil
				continue
			end
			local defs = Config.Tracks[track]
			local owned = 0
			for _, def in ipairs(defs) do
				if self.owned[def.id] then
					owned += 1
				end
			end
			label.Text = ("%s CABINET  •  %d/%d"):format(
				Config.TrackLabel[track] or track:upper(), owned, #defs)
		end
	end

	function Tycoon:buildRebirthPad()
		local folder = Instance.new("Folder")
		folder.Name = "Rebirth"
		folder.Parent = self.model
		self.rebirthFolder = folder
		self:registerFactoryFolder(folder)

		local spot = L.RebirthPadAt
		local pad = newPart(folder, "RebirthPad", Vector3.new(12, 1.2, 12),
			self:at(spot.X, 0.9, spot.Z), Color3.fromRGB(200, 120, 255), Enum.Material.Neon)
		pad.CanCollide = false
		self.rebirthPad = pad

		local ring = newPart(folder, "RebirthRing", Vector3.new(0.4, 16, 16),
			self:at(spot.X, 0.3, spot.Z) * CFrame.Angles(0, 0, math.pi / 2),
			Color3.fromRGB(120, 60, 200), Enum.Material.Neon, false)
		ring.Shape = Enum.PartType.Cylinder

		local billboard = Style.billboard(pad, {
			name = "Sign", width = 16, height = 6, distance = "prop", offset = 6,
		})
		self.rebirthLabel = Style.text(billboard, {
			name = "Label", text = "SAHUR REBIRTH",
			color = Color3.fromRGB(235, 200, 255),
		})

		-- keyed by UserId, not by Player, so leaving players aren't kept alive
		local debounce: { [number]: number } = {}
		pad.Touched:Connect(function(hit)
			local player = self:playerFromHit(hit)
			if not player or player ~= self.owner then
				return
			end
			local last = debounce[player.UserId]
			if last and os.clock() - last < 3 then
				return
			end
			debounce[player.UserId] = os.clock()
			Economy.notify(player, {
				kind = "rebirthPrompt",
				title = "SAHUR REBIRTH",
				body = ("Wipe your factory for a permanent x%.2f payout boost?"):format(Config.Rebirth.MultiplierPerRebirth),
				cost = Economy.rebirthCost(player),
			})
		end)
	end

	-- ── buttons ──────────────────────────────────────────────────────────────────

	--- Buy buttons line the INBOARD side of the belt, next to the machine they
	--- build, so the row you walk along is the row you buy from.
	function Tycoon:buttonPosition(def): Vector3
		if def.kind == "Dropper" or def.kind == "Upgrader" then
			local legIndex, distance, pathIndex = self:legOf(def)
			return self:pointOnLeg(legIndex, distance, -L.ButtonOffset, pathIndex)
		end
		-- Side tracks stand in their own derived column at their cabinet, so a new
		-- tier needs no coordinate anywhere. Only the factory's non-belt buttons
		-- are still hand-placed in Layout.MiscButtons.
		if def.track and def.track ~= "factory" then
			return Config.trackButtonPosition(def.track, def.trackOrder)
		end
		return MISC_SPOTS[def.id] or Vector3.new(0, 0, 0)
	end

	--- Where a buy button's pedestal actually stands, height included.
	---
	--- This exists because the conversion from "button position" to "CFrame" was
	--- written twice, and both copies threw the Y away — `self:at(pos.X, 0, pos.Z)`.
	--- `buttonPosition` has always returned the right height for a machine on any
	--- belt path (pointOnLeg bakes in `path.y`), so the floors prototype could
	--- never have a purchasable thing standing on it: everything it priced would
	--- have been built on the ground floor underneath the deck. One line, and it
	--- was the single blocker for a real second storey.
	---
	--- No-op today. Every source of a button position returns Y = 0 while there is
	--- one ground-level path: BeltPaths[1].y is 0, trackButtonPosition hardcodes
	--- its Y, and every Layout.MiscButtons entry is on the floor.
	function Tycoon:buttonBaseCF(def): CFrame
		local pos = self:buttonPosition(def)
		return self:at(pos.X, pos.Y, pos.Z)
	end

	function Tycoon:buildButtons()
		for _, def in ipairs(Config.Buttons) do
			local base = self:buttonBaseCF(def)

			local holder = Instance.new("Model")
			holder.Name = "Btn_" .. def.id
			holder.Parent = self.buttonsFolder

			-- Total height is Layout.ButtonHeight (1.4 studs). A Roblox humanoid
			-- steps over ~2 studs without jumping, so you can run straight across
			-- these instead of having to hop onto each one.
			local plinth = L.ButtonHeight * 0.55
			newPart(holder, "Pedestal", Vector3.new(5, plinth, 5), base * CFrame.new(0, plinth / 2, 0),
				COLORS.frame, Enum.Material.DiamondPlate)

			local pad = newPart(holder, "Pad", Vector3.new(4.6, L.ButtonHeight - plinth, 4.6),
				base * CFrame.new(0, (L.ButtonHeight + plinth) / 2, 0), COLORS.buttonOn, Enum.Material.Neon)
			pad.CanCollide = false
			pad:SetAttribute("ButtonId", def.id)

			local light = Instance.new("PointLight")
			light.Color = COLORS.buttonOn
			light.Range = 11
			light.Brightness = 1.4
			light.Shadows = false
			light.Parent = pad

			-- NOT AlwaysOnTop. Hiding behind a wall you are on the wrong side of is
			-- correct; hiding behind a machine two feet away is not, and the x-ray
			-- was covering the second case at the cost of the first — every locked
			-- pad on the plot showed through everything, which is most of why the
			-- plot read as a wall of labels. The label clears the machinery on its
			-- own now, by standing above it (Style.Button.lift, asserted against
			-- Layout.MachineTopY).
			local billboard = Style.billboard(pad, {
				name = "Info", width = BTN.width, height = BTN.height,
				distance = BTN.distance, offset = BTN.lift,
			})

			local frame = Instance.new("Frame")
			frame.Size = UDim2.fromScale(1, 1)
			frame.BackgroundColor3 = Color3.fromRGB(20, 16, 30)
			frame.BackgroundTransparency = BTN.panelAlpha
			frame.BorderSizePixel = 0
			frame.Parent = billboard
			Util.roundedFrame(frame, 10)

			local stroke = Instance.new("UIStroke")
			stroke.Color = COLORS.buttonOn
			stroke.Thickness = BTN.strokeThickness
			stroke.Parent = frame

			-- Four lines, in the order you ask the questions: where am I in the
			-- build, what is this, what does it do for me, what does it cost.
			--
			-- The track name, not a global ordinal. "STEP 21 OF 30" on a pedestal
			-- in front of a weapons cabinet tells you nothing; "WEAPONS 2/5" is
			-- the whole feature explained in three words.
			local step = Style.text(frame, {
				name = "Step", weight = "body",
				size = UDim2.fromScale(0.94, 0.18), position = UDim2.fromScale(0.03, 0.02),
				text = ("%s %d/%d"):format(
					Config.TrackLabel[def.track] or "STEP", def.trackOrder, #Config.Tracks[def.track]),
				color = Color3.fromRGB(150, 142, 172),
			})

			local title = Style.text(frame, {
				name = "Title",
				size = UDim2.fromScale(0.94, 0.32), position = UDim2.fromScale(0.03, 0.2),
				text = def.name, color = Color3.fromRGB(255, 240, 210),
			})

			local effect = Style.text(frame, {
				name = "Effect", weight = "body",
				size = UDim2.fromScale(0.94, 0.22), position = UDim2.fromScale(0.03, 0.52),
				text = def.blurb or "", color = Color3.fromRGB(150, 235, 190),
			})

			local price = Style.text(frame, {
				name = "Price", weight = "body",
				size = UDim2.fromScale(0.94, 0.24), position = UDim2.fromScale(0.03, 0.74),
				color = COLORS.buttonOn,
			})
			price.Text = "$" .. Util.abbreviate(def.price)

			local lastTouch = 0
			pad.Touched:Connect(function(hit)
				if os.clock() - lastTouch < 0.35 then
					return
				end
				lastTouch = os.clock()
				local player = self:playerFromHit(hit)
				if player then
					self:tryPurchase(player, def.id)
				end
			end)

			-- The half of "buttons honour their height" that no config check can
			-- reach: whether the part that got built is actually where
			-- buttonPosition said. Free in production, and it fails loudly the day
			-- somebody reintroduces the flattening on a floor that has content.
			if RunService:IsStudio() then
				local want = (self:buttonBaseCF(def)).Position.Y
				assert(math.abs(pad.Position.Y - want) < L.ButtonHeight + 0.01,
					("[Tung] button %s built at y=%.2f but buttonPosition says y=%.2f")
						:format(def.id, pad.Position.Y, want))
			end

			self.objects[def.id] = {
				def = def,
				holder = holder,
				pad = pad,
				pedestal = holder:FindFirstChild("Pedestal"),
				billboard = billboard,
				frame = frame,
				stroke = stroke,
				priceLabel = price,
				effectLabel = effect,
				stepLabel = step,
				titleLabel = title,
				-- every label the two voices have to fade together
				labels = { step, title, effect, price },
				light = light,
				machine = nil,
				ghost = nil,
			}
		end
	end

	--- Whether the floor a button stands on has actually been built.
	---
	--- A previewed button is a dimmed pad with a ghost of its machine standing
	--- where it will go, which is the right answer on the ground floor and a
	--- terrible one twenty-two studs up in open air: before the deck exists there
	--- is nothing under it, so it reads as a bug rather than as a plan. Buttons on
	--- an unbuilt floor are HIDDEN, and appear with the deck.
	function Tycoon:floorBuiltFor(def): boolean
		if not def.path then
			return true
		end
		for _, floor in ipairs(Config.Floors) do
			if floor.id == def.path then
				return self.owned[floor.button] == true
			end
		end
		return true
	end

	function Tycoon:requirementsMet(id: string): boolean
		local def = Config.ButtonById[id]
		if not def then
			return false
		end
		-- ANDed in here rather than only in refreshButtons, so a stale Touched on a
		-- pad that is about to be hidden cannot buy through the gate.
		if not Config.trackUnlocked(def.track, self.owned) then
			return false
		end
		for _, req in ipairs(Config.requirementsOf(def)) do
			if not self.owned[req] then
				return false
			end
		end
		return true
	end

	--- A translucent stand-in for a machine you haven't bought yet, built from the
	--- same MACHINE_MASSES description as the real thing.
	---
	--- Showing the next few purchases as ghosts turns the plot into a plan you are
	--- filling in, rather than a row of anonymous pads with prices on them. It also
	--- answers the standing complaint about tycoon infrastructure — "why am I
	--- buying walls before I can buy upgraders" stops being a fair question once
	--- you can see the upgraders standing there waiting.
	function Tycoon:buildGhost(def)
		if not MACHINE_MASSES[def.kind] then
			return nil
		end
		local variant = Config.Variants[def.variant] or Config.Variants.classic

		local model = Instance.new("Model")
		model.Name = "Ghost_" .. def.id

		local parts = self:buildMasses(def, model, variant.wood, Enum.Material.ForceField)
		for _, part in pairs(parts) do
			part.Transparency = 0.72
			-- A ghost must never be walked into, stood on, or hit by a drop: it is
			-- a drawing, and the belt has to run through where it will stand.
			part.CanCollide = false
			part.CanTouch = false
			part.CanQuery = false
			part.CastShadow = false
		end
		return model
	end

	--- Buy buttons have three states, because the two obvious designs both fail:
	--- showing every button at once gives the plot no focal point, and showing
	--- only the next one hides the shape of the build from you.
	---
	---   available   full colour, lit, touchable, and the cheapest one wears a
	---               Highlight and a beacon so it is findable from anywhere
	---   preview     the next few steps: dimmed, inert, with a ghost of the
	---               machine standing where it will go
	---   hidden      everything further out, and everything already owned
	--- How far past its own frontier each track previews.
	---
	--- 3 on the factory keeps the shipped plot exactly as it reads today. 2 on the
	--- side tracks because they are short: at 3 a five-rung cabinet would preview
	--- its entire ladder from the moment the plot is claimed, the "hidden" state
	--- would stop existing there, and the case would stop reading as something you
	--- are climbing.
	local TRACK_PREVIEW = { factory = 3, weapons = 2, armor = 2 }

	--- Which track the "buy this next" beacon prefers. The beacon picks the
	--- cheapest AVAILABLE button, and a cabinet's first rung is cheap — so without
	--- a track preference the marker would hop off the factory and onto a bat the
	--- moment the plot was claimed. Rank by (track, price), factory first.
	local TRACK_RANK = { factory = 1, weapons = 2, armor = 3 }

	--- Switches a buy button's label between its two voices.
	---
	--- `locked` is a Config.Style.ButtonLocked table, or nil for the full-volume
	--- one. Five properties move together because any one of them alone is a nudge
	--- and the point is a difference you cannot miss: the label shrinks, its panel
	--- fades, its outline thins, its text fades (outline along with it, or a dimmed
	--- label keeps a hard edge and reads as MORE contrasty than the bright one),
	--- and it stops drawing at a shorter range so a plot full of locked pads
	--- clears out as you walk away from it.
	function Tycoon:setButtonVoice(entry, locked)
		local scale = locked and locked.scale or 1
		entry.billboard.Size = UDim2.fromScale(BTN.width * scale, BTN.height * scale)
		Style.setDistance(entry.billboard, locked and locked.distance or BTN.distance)
		entry.frame.BackgroundTransparency = locked and locked.panelAlpha or BTN.panelAlpha
		entry.stroke.Thickness = locked and locked.strokeThickness or BTN.strokeThickness
		local alpha = locked and locked.textAlpha or 0
		for _, label in ipairs(entry.labels) do
			Style.fade(label, alpha)
		end
	end

	function Tycoon:refreshButtons()
		if not self.owner then
			for _, entry in pairs(self.objects) do
				entry.holder.Parent = nil
				if entry.ghost then
					entry.ghost:Destroy()
					entry.ghost = nil
				end
			end
			if self.marker then
				self:pointAt(nil)
			end
			return
		end

		local cash = Economy.get(self.owner)

		-- How far along EACH track the player has got. One frontier per track is a
		-- strict generalisation of the old single scan: with one track it produces
		-- exactly the numbers that loop produced.
		local frontier = {}
		for track, defs in pairs(Config.Tracks) do
			frontier[track] = #defs + 1
			for _, def in ipairs(defs) do
				if not self.owned[def.id] then
					frontier[track] = def.trackOrder
					break
				end
			end
		end

		local target, targetRank, targetPrice = nil, math.huge, math.huge

		for id, entry in pairs(self.objects) do
			local def = entry.def
			local owned = self.owned[id] == true
			-- A gated track is HIDDEN, not previewed, and it takes no ghost: the
			-- point of gating the cabinets is that the right half of the plot is
			-- empty ground until you have earned it, and nine dimmed pads with
			-- ghost bats standing on them is the same wall of labels with the
			-- brightness turned down.
			local standing = self:floorBuiltFor(def) and Config.trackUnlocked(def.track, self.owned)
			local available = (not owned) and standing and self:requirementsMet(id)
			local preview = (not owned) and (not available) and standing
				and (def.trackOrder <= frontier[def.track] + (TRACK_PREVIEW[def.track] or 3))

			entry.holder.Parent = (available or preview) and self.buttonsFolder or nil

			if preview then
				-- inert: a preview pad you can buy from would just spam "you can't
				-- afford that yet" every time you crossed it
				entry.pad.CanTouch = false
				entry.pad.Color = COLORS.preview
				entry.pad.Transparency = 0.45
				if entry.pedestal then
					entry.pedestal.Transparency = 0.55
					entry.pedestal.CanCollide = false
				end
				entry.light.Enabled = false
				-- SMALLER, FAINTER, THINNER, AND IT GIVES UP SOONER. Colour on its
				-- own was never going to carry this: it is the first signal lost to
				-- a bright sky or a neon variant standing behind the label, and it
				-- was the ONLY thing separating a locked pad from the one you can
				-- press.
				self:setButtonVoice(entry, BTN_LOCKED)
				entry.stroke.Color = COLORS.preview
				entry.stepLabel.TextColor3 = COLORS.preview
				entry.titleLabel.TextColor3 = COLORS.preview
				-- Name the thing you have to buy, not an ordinal. "step N" meant
				-- one thing when there was one chain; with three tracks the global
				-- order is meaningless on a pedestal and the per-track one is
				-- ambiguous across cabinets. The requirement is right here, so say
				-- it: "locked — buy Oak Sahur Bat first".
				local blocker
				for _, req in ipairs(Config.requirementsOf(def)) do
					if not self.owned[req] then
						blocker = Config.ButtonById[req]
						break
					end
				end
				entry.effectLabel.Text = blocker
					and ("locked — buy %s first"):format(blocker.name)
					or "locked"
				entry.effectLabel.TextColor3 = COLORS.preview
				entry.priceLabel.Text = "$" .. Util.abbreviate(def.price)
				entry.priceLabel.TextColor3 = COLORS.preview
			elseif available then
				local affordable = cash >= def.price
				local color = affordable and COLORS.buttonOn or COLORS.buttonOff
				entry.pad.CanTouch = true
				entry.pad.Transparency = 0
				entry.pad.Color = color
				if entry.pedestal then
					entry.pedestal.Transparency = 0
					entry.pedestal.CanCollide = true
				end
				entry.light.Enabled = true
				entry.light.Color = color
				self:setButtonVoice(entry, nil)
				entry.stroke.Color = color
				entry.stepLabel.TextColor3 = Color3.fromRGB(150, 142, 172)
				entry.titleLabel.TextColor3 = Color3.fromRGB(255, 240, 210)
				entry.effectLabel.Text = self:effectLine(def)
				entry.effectLabel.TextColor3 = Color3.fromRGB(150, 235, 190)
				entry.priceLabel.TextColor3 = color
				entry.priceLabel.Text = affordable
					and ("$" .. Util.abbreviate(def.price))
					or ("NEED " .. Util.abbreviate(def.price - cash) .. " MORE")

				-- (track, price) lexicographically. Cheapest-overall would park the
				-- beacon on the first cabinet rung for the whole early game, since
				-- a bat costs less than the next dropper for most of it.
				local rank = TRACK_RANK[def.track] or 99
				if rank < targetRank or (rank == targetRank and def.price < targetPrice) then
					target, targetRank, targetPrice = entry, rank, def.price
				end
			end

			-- ghosts stand for anything not yet built, available or previewed
			local wantsGhost = (available or preview) and MACHINE_MASSES[def.kind] ~= nil
			if wantsGhost and not entry.ghost then
				entry.ghost = self:buildGhost(def)
				if entry.ghost then
					entry.ghost.Parent = self.machines
				end
			elseif not wantsGhost and entry.ghost then
				entry.ghost:Destroy()
				entry.ghost = nil
			end
		end

		self:pointAt(target)
		-- Here rather than as a second ownedChanged listener: refreshButtons
		-- already runs on install, assign, release and rebirth — every event that
		-- can open or close a track — and updateCabinetSigns has always lived on
		-- the end of it. ensureCabinets is idempotent, so the periodic refresh
		-- costs a FindFirstChild per track.
		self:ensureCabinets()
		self:updateCabinetSigns()
	end

	--- Moves the "buy this next" marker onto `entry`. One Highlight and one light
	--- column per plot, reparented, rather than one of each per button: Highlight
	--- is capped at 255 per client and disabled ones still occupy a slot.
	function Tycoon:pointAt(entry)
		if not self.marker then
			local marker = Instance.new("Model")
			marker.Name = "NextMarker"

			local beam = newPart(marker, "Beam", Vector3.new(4, 26, 4), CFrame.new(),
				COLORS.gold, Enum.Material.Neon, false)
			beam.Transparency = 0.75
			beam.CanQuery = false

			local highlight = Instance.new("Highlight")
			highlight.FillColor = COLORS.gold
			highlight.FillTransparency = 0.65
			highlight.OutlineColor = Color3.fromRGB(255, 255, 255)
			-- through your own machinery: the point of the marker is that you can
			-- find it from the far end of a plot you have already half filled
			highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
			highlight.Parent = marker

			self.marker = marker
			self.markerBeam = beam
			self.markerHighlight = highlight
		end

		if not entry then
			self.marker.Parent = nil
			self.markerHighlight.Adornee = nil
			return
		end

		self.markerHighlight.Adornee = entry.holder
		self.markerBeam.CFrame = entry.pad.CFrame * CFrame.new(0, 13, 0)
		self.marker.Parent = self.buttonsFolder
	end

	-- ── purchasing ───────────────────────────────────────────────────────────────

	function Tycoon:playerFromHit(hit: BasePart): Player?
		local character = hit and hit:FindFirstAncestorOfClass("Model")
		if not character then
			return nil
		end
		local humanoid = character:FindFirstChildOfClass("Humanoid")
		if not humanoid or humanoid.Health <= 0 then
			return nil
		end
		return game:GetService("Players"):GetPlayerFromCharacter(character)
	end

	function Tycoon:tryPurchase(player: Player, id: string)
		if player ~= self.owner then
			return
		end
		local def = Config.ButtonById[id]
		if not def or self.owned[id] then
			return
		end
		if not self:requirementsMet(id) then
			return
		end
		if not Economy.spend(player, def.price) then
			local short = def.price - Economy.get(player)
			Economy.notify(player, {
				kind = "warn",
				title = "Not enough Tung",
				body = ("You need %s more for %s."):format(Util.abbreviate(short), def.name),
			})
			return
		end

		local profile = DataService.get(player)
		if profile then
			profile.owned[id] = true
		end

		self:install(id, false)

		Economy.notify(player, {
			kind = "buy",
			title = def.name,
			body = def.blurb or "",
			price = def.price,
		})
		Economy.push(player)
	end

	--- Applies a purchase. `silent` skips effects (used when loading a save).
	function Tycoon:install(id: string, silent: boolean?)
		local def = Config.ButtonById[id]
		if not def or self.owned[id] then
			return
		end
		self.owned[id] = true

		local entry = self.objects[id]
		if entry then
			entry.holder.Parent = nil
		end

		local installer = Tycoon.INSTALLERS[def.kind]
		if installer then
			installer(self, def, silent)
		else
			warn("[Tung] no installer for kind " .. tostring(def.kind))
		end

		if not silent then
			-- The twin of the bug buttonBaseCF fixes: the purchase confetti used a
			-- literal world 5 rather than five studs above the button, so a
			-- mezzanine purchase would have burst on the ground floor underneath it.
			local variant = Config.Variants[def.variant or "classic"]
			Fx.burst((self:buttonBaseCF(def) * CFrame.new(0, 5, 0)).Position, variant.wood, 18, self.model)
		end

		self:refreshButtons()
		self:fireOwnedChanged()
	end

	-- ── installers ───────────────────────────────────────────────────────────────

	Tycoon.INSTALLERS = {}

	--- The dropper machine itself: masses, dressing, nameplate. Shared by the buy
	--- button installer and by FloorService, which stands one on each upper floor —
	--- a floor's dropper is not a button, so it cannot go through INSTALLERS.
	--- Returns the model, its nozzle, and the leg and path it feeds.
	function Tycoon:buildDropperMachine(def, parent: Instance)
		local variant = Config.Variants[def.variant] or Config.Variants.classic

		local model = Instance.new("Model")
		model.Name = "Dropper_" .. def.id
		model.Parent = parent

		local parts, legIndex, _, pathIndex = self:buildMasses(def, model, COLORS.frame, Enum.Material.DiamondPlate)

		local core = parts.Core
		core.Color = variant.wood
		core.Material = variant.material
		Fx.applyVariant(core, variant)

		parts.Arm.Color = COLORS.metal
		parts.Arm.Material = Enum.Material.Metal
		parts.Spout.Color = COLORS.metal
		parts.Spout.Material = Enum.Material.Metal

		local nozzle = parts.Nozzle
		nozzle.Color = variant.light and variant.light.color or variant.wood
		nozzle.Material = Enum.Material.Neon

		local billboard = Style.billboard(core, {
			name = "Plate", width = 9, height = 2.6, distance = "machine", offset = 3.4,
		})
		Style.text(billboard, {
			weight = "body", color = Color3.fromRGB(255, 250, 235),
			text = def.name .. "  •  $" .. Util.abbreviate(def.dropValue),
		})

		return model, nozzle, legIndex, pathIndex
	end

	--- Starts a dropper's drop loop. `alive` is polled each cycle so the caller
	--- decides what ends it: a bought dropper dies when its button is wiped by a
	--- rebirth, a floor's dropper dies when the floor is torn down (its model is
	--- destroyed, which the model.Parent check catches on its own).
	function Tycoon:startDropLoop(def, model: Model, nozzle: BasePart, legIndex: number, pathIndex: number?, alive: (() -> boolean)?)
		local generation = self.generation
		task.spawn(function()
			-- stagger so ten droppers don't fire on the same frame
			task.wait(math.random() * def.dropRate)
			while self.generation == generation and model.Parent and (alive == nil or alive()) do
				self:spawnDrop(def, nozzle, legIndex, pathIndex)
				task.wait(def.dropRate)
			end
		end)
	end

	Tycoon.INSTALLERS.Dropper = function(self, def, silent)
		local model, nozzle, legIndex, pathIndex = self:buildDropperMachine(def, self.machines)

		local entry = self.objects[def.id]
		if entry then
			entry.machine = model
		end

		self:startDropLoop(def, model, nozzle, legIndex, pathIndex, function()
			return self.owned[def.id] == true
		end)
	end

	Tycoon.INSTALLERS.Upgrader = function(self, def, silent)
		local variant = Config.Variants[def.variant] or Config.Variants.classic

		local model = Instance.new("Model")
		model.Name = "Upgrader_" .. def.id
		model.Parent = self.machines

		local parts = self:buildMasses(def, model, COLORS.metal, Enum.Material.Metal)

		local beam = parts.Beam
		beam.Color = variant.wood
		beam.Material = variant.material
		Fx.applyVariant(beam, variant)

		local scanner = parts.Scanner
		scanner.Color = variant.light and variant.light.color or variant.wood
		scanner.Material = Enum.Material.Neon
		scanner.Transparency = 0.55
		scanner.CanTouch = true

		local billboard = Style.billboard(beam, {
			name = "Plate", width = 11, height = 3, distance = "machine", offset = 3,
		})
		Style.text(billboard, {
			text = ("%s  x%.2g"):format(def.name, def.multiplier),
			color = Color3.fromRGB(255, 240, 210),
		})

		local flagName = "up_" .. def.id
		scanner.Touched:Connect(function(hit)
			local drop = hit.Parent
			if not drop or not drop:IsA("Model") then
				return
			end
			if drop:GetAttribute("PlotIndex") ~= self.index then
				return
			end
			local value = drop:GetAttribute("Value")
			if not value or drop:GetAttribute(flagName) then
				return
			end
			drop:SetAttribute(flagName, true)
			drop:SetAttribute("Value", value * def.multiplier)

			local body = drop.PrimaryPart or drop:FindFirstChild("Body")
			if body and body:IsA("BasePart") then
				body.Color = Util.lerpColor(body.Color, variant.wood, 0.55)
				body.Material = variant.material
				Fx.burst(body.Position, variant.wood, 4, self.model)
				Fx.tung(body, 1.15 + math.random() * 0.2, 0.12)
			end
		end)

		local entry = self.objects[def.id]
		if entry then
			entry.machine = model
		end
	end

	Tycoon.INSTALLERS.Belt = function(self, def, silent)
		self.beltSpeed += def.speedBonus
		-- one speed for the whole plot, every floor included
		self:eachBeltSurface(function(surface)
			surface.Color = Color3.fromRGB(92, 70, 40)
		end)
		-- retro-apply to drops already rolling
		for _, drop in ipairs(self.drops:GetChildren()) do
			local mover = drop:FindFirstChildWhichIsA("LinearVelocity", true)
			if mover then
				mover.PlaneVelocity = Vector2.new(self.beltSpeed, 0)
			end
		end
	end

	--- A bought tier's display, standing on its own shelf of the track's cabinet.
	---
	--- Parented into self.props, NOT self.machines: rebirth clears machines, and a
	--- weapon you keep across a rebirth must not lose its shelf.
	function Tycoon:buildShelfDisplay(def, variant: string, label: string)
		local model = Instance.new("Model")
		model.Name = "Shelf_" .. def.id
		model.Parent = self.props

		local spot = Config.trackShelfPosition(def.track, def.trackOrder)
		local shelfCF = self:at(spot.X, spot.Y, spot.Z)
		newPart(model, "Shelf", Vector3.new(5, 0.6, 8), shelfCF, COLORS.metal, Enum.Material.Metal)

		-- 0.85 rather than the 1.1 the old free-standing anvil used: the display
		-- now stands INSIDE a 13-stud case, and the tallest variants scale up by a
		-- further 1.5 on top of whatever is asked for here.
		local display = TungModels.buildStatue(variant, 0.85)
		display:PivotTo(shelfCF * CFrame.new(0, 3.2, 0))
		display.Parent = model

		local plate = newPart(model, "Plate", Vector3.new(0.4, 1.6, 7),
			shelfCF * CFrame.new(-2.2, 1, 0), COLORS.metal, Enum.Material.Metal, false)
		local billboard = Style.billboard(plate, {
			name = "Plate", width = 7, height = 1.4, distance = "machine", offset = 1.6,
		})
		Style.text(billboard, { weight = "body", text = label, color = COLORS.gold })

		return model
	end

	Tycoon.INSTALLERS.Gear = function(self, def, silent)
		local owner = self.owner
		if owner then
			CombatService.grantBat(owner, def.grants)
		end

		local batDef = Config.BatById[def.grants]
		local model = self:buildShelfDisplay(def, batDef and batDef.variant or "classic",
			batDef and batDef.name or def.name)

		local entry = self.objects[def.id]
		if entry then
			entry.machine = model
		end
	end

	Tycoon.INSTALLERS.Armor = function(self, def, silent)
		local owner = self.owner
		if owner then
			CombatService.grantArmor(owner, def.grants)
		end

		local tierDef = Config.ArmorById[def.grants]
		local model = self:buildShelfDisplay(def, tierDef and tierDef.variant or "classic",
			tierDef and tierDef.name or def.name)

		local entry = self.objects[def.id]
		if entry then
			entry.machine = model
		end
	end

	--- A DOCUMENTED NO-OP. The deck is built by FloorService off the
	--- ownedChanged signal, not from here, because the deck outlives this
	--- purchase: release, rebirth and re-claim all have to rebuild or drop it and
	--- none of them go through install(). This exists so install() does not
	--- warn("no installer for kind Floor") on a button that worked perfectly.
	Tycoon.INSTALLERS.Floor = function(self, def, silent)
	end

	Tycoon.INSTALLERS.Structure = function(self, def, silent)
		local model = Instance.new("Model")
		model.Name = "Structure_" .. def.id
		model.Parent = self.machines

		local halfX = W.PlotSize.X / 2 - 1
		local halfZ = W.PlotSize.Z / 2 - 1

		if def.structure == "walls" then
			local h = 13
			-- The gateway sits over the open floor on the right, NOT at x = 0:
			-- the belt and vault occupy the left half, so a centred gate would
			-- open onto machinery. Config owns the numbers so they scale with
			-- the plot and can be checked against the aisle by the verifier.
			local gateCentre, gateWidth = L.GateCentre, L.GateWidth
			local gateLeft = gateCentre - gateWidth / 2
			local gateRight = gateCentre + gateWidth / 2
			local leftSpan = gateLeft + halfX
			local rightSpan = halfX - gateRight
			local specs = {
				{ Vector3.new(W.PlotSize.X, h, 2), CFrame.new(0, h / 2, -halfZ) },
				{ Vector3.new(2, h, W.PlotSize.Z), CFrame.new(halfX, h / 2, 0) },
				{ Vector3.new(2, h, W.PlotSize.Z), CFrame.new(-halfX, h / 2, 0) },
				-- front wall in two pieces, leaving the gateway over the aisle
				{ Vector3.new(leftSpan, h, 2), CFrame.new(gateLeft - leftSpan / 2, h / 2, halfZ) },
				{ Vector3.new(rightSpan, h, 2), CFrame.new(gateRight + rightSpan / 2, h / 2, halfZ) },
			}
			for i, spec in ipairs(specs) do
				newPart(model, "Wall" .. i, spec[1], self.cf * spec[2], Color3.fromRGB(150, 111, 74), Enum.Material.WoodPlanks)
				newPart(model, "Trim" .. i, spec[1] + Vector3.new(0.4, -h + 1, 0.4),
					self.cf * spec[2] * CFrame.new(0, h / 2, 0), COLORS.beltLine, Enum.Material.Neon, false)
			end
		elseif def.structure == "roof" then
			self:buildRoofModel(model, halfX, halfZ)
		end

		local entry = self.objects[def.id]
		if entry then
			entry.machine = model
		end
	end

	--- The roof slab, its columns and the company sign.
	---
	--- Extracted from the installer because the roof's SHAPE depends on something
	--- bought later. The mezzanine deck is the roof of the back half of the plot,
	--- so with the floor up the roof stops short of it with a couple of studs of
	--- daylight; roofing it twice interpenetrates two slabs a third of a stud apart
	--- and hides a floor under a roof nobody can see.
	---
	--- That used to key off the prototype flag, which was the same answer for
	--- everybody forever. Now that the floor is a purchase in the middle of the
	--- build, the roof at minute 28 and the floor at minute 40 are fifteen minutes
	--- apart — so the roof has to be REBUILT when the floor lands, or every player
	--- gets a half-roof over an empty back half for the gap between them.
	function Tycoon:buildRoofModel(model: Instance, halfX: number, halfZ: number)
		model:ClearAllChildren()

		local front = W.PlotSize.Z / 2
		local back = -W.PlotSize.Z / 2
		local floorDef = Config.Floors[1]
		if floorDef and self.owned[floorDef.button] then
			back = floorDef.deckAt.Z + floorDef.deckSize.Z / 2 + 2
		end

		do
			-- Heights come from Layout now rather than being literals here, because
			-- the mezzanine deck sits at 22 and these columns are 20 tall — a
			-- relationship nothing was checking, on two pieces of geometry that
			-- already reach into each other.
			local roof = newPart(model, "Roof", Vector3.new(W.PlotSize.X, L.RoofThickness, front - back),
				self:at(0, L.RoofY, (front + back) / 2), Color3.fromRGB(138, 88, 58), Enum.Material.WoodPlanks)
			roof.CanCollide = true
			for _, sign in ipairs({ -1, 1 }) do
				for _, signZ in ipairs({ -1, 1 }) do
					newPart(model, "Column", Vector3.new(L.RoofColumn, L.RoofY, L.RoofColumn),
						self:at(sign * (halfX - L.RoofColumnInset), L.RoofY / 2, signZ * (halfZ - L.RoofColumnInset)),
						Color3.fromRGB(150, 111, 74), Enum.Material.Wood)
				end
			end

			local signAnchor = newPart(model, "SignAnchor", Vector3.new(1, 1, 1), self:at(0, 27, 0), COLORS.frame, nil, false)
			signAnchor.Transparency = 1
			local billboard = Style.billboard(signAnchor, {
				name = "Sign", width = 46, height = 12, distance = "plot",
			})
			self.roofSign = Style.text(billboard, {
				text = "TUNG TUNG TUNG SAHUR CO.", color = COLORS.gold,
			})
			self:updateSign()
		end
	end

	--- Reshapes an already-built roof. Called when the floor lands under it.
	function Tycoon:refreshRoof()
		local entry = self.objects.roof
		local model = entry and entry.machine
		if model and model.Parent then
			self:buildRoofModel(model, W.PlotSize.X / 2 - 1, W.PlotSize.Z / 2 - 1)
		end
	end

	-- ── drops ────────────────────────────────────────────────────────────────────

	function Tycoon:spawnDrop(def, nozzle: BasePart, legIndex: number, pathIndex: number?)
		pathIndex = pathIndex or 1
		if not self.owner then
			return
		end
		if self.dropCount >= Config.Economy.MaxDropsPerPlot then
			return
		end
		self.dropCount += 1

		local drop = TungModels.buildDrop(def.variant, 0.62)
		drop:SetAttribute("Value", def.dropValue)
		drop:SetAttribute("PlotIndex", self.index)
		drop:SetAttribute("Variant", def.variant)

		-- Which belt, and how far along it: the corner sensors and the collector
		-- all filter on these, so a drop on the mezzanine is invisible to the
		-- ground floor's geometry and vice versa.
		drop:SetAttribute("Leg", legIndex)
		drop:SetAttribute("Path", pathIndex)

		local body = drop.PrimaryPart :: BasePart
		local direction = self:legDirectionWorld(legIndex, pathIndex)
		local across = self:legNormalWorld(legIndex, pathIndex)
		local jitter = (math.random() - 0.5) * (L.BeltWidth * 0.35)

		-- NOTE: the model's pivot is the body, so PivotTo overwrites the body's
		-- rotation outright. The upright orientation has to be baked into the
		-- target CFrame or every drop spawns lying on its side.
		local upright = TungModels.dropOrientation(direction)
		local spawnPosition = nozzle.Position + across * jitter - Vector3.new(0, 1.6, 0)
		drop:PivotTo(CFrame.new(spawnPosition) * upright)

		local attachment = Instance.new("Attachment")
		attachment.Name = "BeltAttach"
		attachment.Parent = body

		-- conveyor motion, done with a constraint so there is no per-frame script
		local mover = Instance.new("LinearVelocity")
		mover.Name = "BeltMover"
		mover.Attachment0 = attachment
		mover.RelativeTo = Enum.ActuatorRelativeTo.World
		mover.VelocityConstraintMode = Enum.VelocityConstraintMode.Plane
		mover.PrimaryTangentAxis = direction
		mover.SecondaryTangentAxis = across
		mover.PlaneVelocity = Vector2.new(self.beltSpeed, 0)
		mover.MaxForce = 120000
		mover.Parent = body

		-- keep the little guy standing up and facing back down the belt, so you
		-- see a queue of angry faces instead of a pile of rolling logs
		local upkeep = Instance.new("AlignOrientation")
		upkeep.Name = "StayUpright"
		upkeep.Mode = Enum.OrientationAlignmentMode.OneAttachment
		upkeep.Attachment0 = attachment
		upkeep.RigidityEnabled = true
		upkeep.CFrame = upright
		upkeep.Parent = body

		drop.Parent = self.drops

		Fx.tung(body, 1.6 + math.random() * 0.3, 0.08)

		task.delay(Config.Economy.DropLifetime, function()
			if drop.Parent then
				self.dropCount = math.max(0, self.dropCount - 1)
				drop:Destroy()
			end
		end)
	end

	function Tycoon:clearDrops()
		for _, drop in ipairs(self.drops:GetChildren()) do
			drop:Destroy()
		end
		self.dropCount = 0
	end

	-- ── income readout ───────────────────────────────────────────────────────────

	--- Estimated Tung/second with everything currently installed.
	---
	--- `extraId` pretends one more button is owned, which is how a buy button can
	--- advertise "+$28/sec" instead of only a price. A price alone is a cost with
	--- no stated benefit, and for an Upgrader the benefit is not even guessable —
	--- x1.85 of an unknown number is not information.
	function Tycoon:incomePerSecond(extraId: string?): number
		local function has(id: string): boolean
			return self.owned[id] == true or id == extraId
		end

		local upgradeMult = 1
		local total = 0
		for id, def in pairs(Config.ButtonById) do
			if has(id) then
				if def.kind == "Upgrader" then
					upgradeMult *= def.multiplier
				elseif def.kind == "Dropper" then
					total += (def.dropValue / def.dropRate)
				end
			end
		end
		local rebirthMult = self.owner and Economy.multiplier(self.owner) or 1
		return total * upgradeMult * rebirthMult
	end

	--- What a drop arriving from `pathId` is multiplied by at the vault.
	---
	--- Lives next to incomePerSecond deliberately: the pair of them are the model
	--- and the reality of the same number, and the whole reason the mezzanine is
	--- refined at all is so those two can keep agreeing. A path that carries its
	--- own upgraders would return 1 here and be multiplied on the belt like the
	--- ground floor is; today only the ground floor has any, so every other path
	--- borrows the stack.
	function Tycoon:refineryMultiplierFor(pathIndex: number?): number
		-- a drop carries its path as the runtime INDEX (see spawnDrop); path 1 is
		-- always the ground floor, and it crossed the scanners on the way down
		if (pathIndex or 1) == 1 then
			return 1
		end
		local path = self.paths[pathIndex]
		local pathId = path and path.id
		local ground = Config.BeltPaths[1].id

		local mult = 1
		for id, def in pairs(Config.ButtonById) do
			if def.kind == "Upgrader" and self.owned[id] then
				if (def.path or ground) == pathId then
					-- this path has its own; it has already been refined
					return 1
				end
				mult *= def.multiplier
			end
		end
		return mult
	end

	--- One line of plain English for what a button actually does for you. Income
	--- kinds get the measured delta; the rest get their blurb, because "walls" has
	--- no income to quote.
	function Tycoon:effectLine(def): string
		if def.kind == "Dropper" or def.kind == "Upgrader" then
			local delta = self:incomePerSecond(def.id) - self:incomePerSecond()
			if delta > 0 then
				return ("+%s/sec"):format(Util.abbreviate(delta))
			end
		elseif def.kind == "Belt" then
			return ("belt +%d studs/sec"):format(def.speedBonus)
		elseif def.kind == "Gear" then
			-- Same rule as the income kinds: quote the measured effect, not the
			-- flavour text. A bat's whole value is its numbers.
			local bat = Config.BatById[def.grants]
			if bat then
				return ("%d dmg  •  %.0f%% crit"):format(bat.damage, bat.crit * 100)
			end
		elseif def.kind == "Armor" then
			local tier = Config.ArmorById[def.grants]
			if tier then
				local previous = Config.Armor.Tiers[tier.tier - 1]
				return ("%d max health  (+%d)"):format(tier.health, tier.health - (previous and previous.health or 0))
			end
		end
		return def.blurb or ""
	end

	function Tycoon:updateSign()
		local ownerName = self.owner and self.owner.DisplayName or nil
		local sign = self.model:FindFirstChild("Totem")
		local billboard = sign and sign:FindFirstChild("Sign")
		-- the label lives inside a Frame inside the BillboardGui, so this lookup
		-- has to be recursive or it silently returns nil forever
		local label = billboard and billboard:FindFirstChild("Owner", true)
		if label then
			if ownerName then
				label.Text = ("%s's TUNG FACTORY\n%s Tung/sec"):format(ownerName, Util.abbreviate(self:incomePerSecond()))
			else
				label.Text = ("UNCLAIMED PLOT %d\nstep on the pad to claim"):format(self.index)
			end
		end
		if self.vaultLabel then
			self.vaultLabel.Text = ownerName
				and ("SAHUR VAULT  •  %s/sec"):format(Util.abbreviate(self:incomePerSecond()))
				or "SAHUR VAULT"
		end
		-- the whole claim rig (pad, beacon, halo, sign) appears and disappears
		-- together, so an owned plot never shows a stray "free" marker
		if self.claimFolder then
			self.claimFolder.Parent = (ownerName == nil) and self.model or nil
		end
		if self.rebirthLabel and self.owner then
			self.rebirthLabel.Text = ("SAHUR REBIRTH\n%s"):format(Util.abbreviate(Economy.rebirthCost(self.owner)))
		end
	end

	-- ── ownership ────────────────────────────────────────────────────────────────

	function Tycoon:assign(player: Player)
		if self.owner then
			return false
		end
		self.owner = player
		self.generation += 1
		self:ensureButtons()
		self:setFactoryVisible(true)

		local profile = DataService.get(player)
		if profile then
			-- rebuild everything they had, cheapest-first so requirements resolve
			local ids = {}
			for id, owned in pairs(profile.owned) do
				if owned and Config.ButtonById[id] then
					table.insert(ids, id)
				end
			end
			table.sort(ids, function(a, b)
				return Config.ButtonById[a].order < Config.ButtonById[b].order
			end)
			for _, id in ipairs(ids) do
				self:install(id, true)
			end
		end

		self:refreshButtons()
		self:updateSign()
		self:fireOwnedChanged()
		return true
	end

	function Tycoon:release()
		self.owner = nil
		self.generation += 1
		self.owned = {}
		self.beltSpeed = L.BeltSpeed

		for _, entry in pairs(self.objects) do
			if entry.machine then
				entry.machine:Destroy()
				entry.machine = nil
			end
		end
		self.machines:ClearAllChildren()
		-- Cabinet bodies USED to be permanent plot furniture and only the shelves
		-- came down. They are earned now, so they go with everything else: a fresh
		-- plot has to read as bare ground on the right-hand side, which is the
		-- entire point of gating them. assign() rebuilds whatever the next owner
		-- has earned, and ensureCabinets is idempotent.
		self.props:ClearAllChildren()
		self.cabinetSigns = {}
		self:clearDrops()
		self:setFactoryVisible(false)

		self:eachBeltSurface(function(surface)
			surface.Color = COLORS.belt
		end)
		self.roofSign = nil

		self:refreshButtons()
		self:updateSign()
		self:fireOwnedChanged()
	end

	--- Wipes the factory but keeps the player, and hands out a rebirth.
	function Tycoon:rebirth(player: Player): boolean
		if player ~= self.owner then
			return false
		end
		local profile = DataService.get(player)
		if not profile then
			return false
		end
		local cost = Economy.rebirthCost(player)
		if profile.rebirths >= Config.Rebirth.MaxRebirths then
			Economy.notify(player, { kind = "warn", title = "Max rebirths", body = "You have ascended as far as sahur allows." })
			return false
		end
		if profile.cash < cost then
			Economy.notify(player, {
				kind = "warn",
				title = "Not enough Tung",
				body = ("Rebirth costs %s."):format(Util.abbreviate(cost)),
			})
			return false
		end

		profile.rebirths += 1
		profile.cash = Config.Economy.StartingCash

		-- A rebirth is a FACTORY reset, not an account reset. The cabinets are
		-- bought with the same wallet but they are not part of the thing being
		-- rebuilt, and re-earning your bat every prestige is exactly the coupling
		-- this split exists to remove.
		--
		-- This also closes a live bug. Rebirth used to wipe `owned` wholesale
		-- while leaving profile.batTier alone, and CombatService.grantBat is
		-- monotonic — so re-buying batforge afterwards took your money and did
		-- nothing at all.
		local kept = {}
		for id in pairs(profile.owned) do
			local def = Config.ButtonById[id]
			if def and def.track ~= "factory" then
				kept[id] = true
			end
		end
		profile.owned = kept

		self.generation += 1
		self.owned = Util.shallowCopy(kept)
		self.beltSpeed = L.BeltSpeed
		for _, entry in pairs(self.objects) do
			-- Side-track props live in self.props and are not cleared below, so
			-- their entries must keep their handle or the model outlives its
			-- reference and can never be cleaned up.
			if entry.def.track == "factory" then
				entry.machine = nil
			end
		end
		self.machines:ClearAllChildren()
		self:clearDrops()

		self:refreshButtons()
		self:updateSign()
		self:fireOwnedChanged()
		Economy.push(player)

		Economy.notify(player, {
			kind = "rebirth",
			title = "SAHUR REBIRTH #" .. profile.rebirths,
			body = ("All payouts are now x%.2f."):format(Economy.multiplier(player)),
		})

		local character = player.Character
		if character and character.PrimaryPart then
			Fx.burst(character:GetPivot().Position, Color3.fromRGB(200, 120, 255), 60, workspace)
		end
		return true
	end

	--- The plot's own part constructor, exposed so FloorService builds its deck out
	--- of the same defaults (anchored, smooth surfaces, collidable unless told
	--- otherwise) instead of a second near-identical local copy that drifts.
	Tycoon.part = newPart

	return Tycoon
end


__MODULES["UpgradeService"] = function()
	--[[
		UpgradeService.lua — PROTOTYPE. Two features that share one profile field:

		  * the player upgrade shop  (Config.Prototypes.PlayerUpgrades)
		  * the utility slot         (Config.Prototypes.Utilities)

		Both are gated; with both flags off every entry point returns on its first
		line and nothing here is ever constructed.

		Server-authoritative in the usual shape: the client may only ever ask. It
		sends RequestUpgrade with an id and gets a fresh UpgradeState back — it is
		never told "yes", it is told what the state now is, so a rejected purchase
		and a lost race look identical from the client's side.

		The utility slot is a KEYBIND, not a second Tool. A Tool would be the
		obvious reading of "second slot", and Roblox's hotbar would carry it for
		free — but only one Tool can be equipped at a time, so firing the utility
		would mean putting the bat away, which is exactly the moment you need it.
		The verbs here (freeze a pack of raiders, shove them off you) are things you
		do mid-swing. So: Q on desktop, an on-screen chip on touch, both routed
		through the UseUtility remote, and the equipped utility is chosen in the
		shop panel rather than by which Tool is in your hand.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Util = Req("Util")
	local Fx = Req("Fx")
	local Net = Req("Net")
	local Utilities = Req("Utilities")
	local DataService = Req("DataService")
	local Economy = Req("Economy")
	local CombatService = Req("CombatService")

	local Players = game:GetService("Players")
	local Debris = game:GetService("Debris")

	local UpgradeService = {}

	local SHOP_ON = Config.Prototypes.PlayerUpgrades
	local UTILITY_ON = Config.Prototypes.Utilities
	local ENABLED = SHOP_ON or UTILITY_ON

	-- Reach and force are per-verb and live on the Config.Utilities row, because
	-- "how far does the shove reach" is a property of the shove: the moment they
	-- are shared constants the next utility has to fight them.
	local function reachOf(id: string, fallback: number): number
		local def = Config.Utilities and Utilities.UtilityById[id]
		return (def and def.radius) or fallback
	end
	local function forceOf(id: string, fallback: number): number
		local def = Config.Utilities and Utilities.UtilityById[id]
		return (def and def.force) or fallback
	end

	local USE_THROTTLE = 0.15       -- floor on UseUtility, independent of cooldowns
	local ICE = Color3.fromRGB(150, 220, 255)

	local upgradeState = Net.event("UpgradeState")
	local requestUpgrade = Net.event("RequestUpgrade")
	local useUtility = Net.event("UseUtility")
	local knockbackRemote = Net.event("Knockback")

	-- os.clock() timestamps, dropped when the player leaves.
	local cooldowns: { [Player]: { [string]: number } } = {}
	local lastUse: { [Player]: number } = {}

	-- ─────────────────────────────────────────────────────────────────────────────
	-- profile state
	--
	-- PERSISTENCE. DataService whitelists what it saves twice over: reconcile()
	-- only copies keys that exist in defaultProfile(), and save() builds an
	-- explicit payload table. A new profile field is invisible until it is added
	-- to BOTH, which is why `upgrades` and `utilityEquipped` appear in each.
	--
	-- utilityEquipped defaults to "" rather than nil, and that matters: reconcile
	-- carries a saved value across only when type(saved[k]) == type(default[k]),
	-- and a nil default is not even iterated by pairs(), so a nil default would
	-- silently discard the field on every load. "" reads as "nothing equipped".
	-- Everything below also tolerates the fields being absent, so a profile saved
	-- before this prototype existed loads either way.
	-- ─────────────────────────────────────────────────────────────────────────────

	--- Levels for BOTH tables live in one map. Ids can't collide (speed/magnet/
	--- payout/autocollect vs freeze/shove/decoy) and it keeps the persistence ask
	--- down to a single new field. A utility is level 0 or 1.
	local function ensure(player: Player)
		local profile = DataService.get(player)
		if not profile then
			return nil
		end
		if type(profile.upgrades) ~= "table" then
			profile.upgrades = {}
		end
		if type(profile.utilityEquipped) ~= "string" then
			profile.utilityEquipped = ""
		end
		-- A save written before a Config edit can carry a level above the new cap,
		-- or an id that no longer exists. Sanitising on read means every consumer
		-- below can trust the number.
		for id, level in pairs(profile.upgrades) do
			local def = Utilities.UpgradeById[id]
			local utility = Utilities.UtilityById[id]
			if def then
				profile.upgrades[id] = math.clamp(math.floor(tonumber(level) or 0), 0, def.levels)
			elseif utility then
				profile.upgrades[id] = math.clamp(math.floor(tonumber(level) or 0), 0, 1)
			else
				profile.upgrades[id] = nil
			end
		end
		if profile.utilityEquipped ~= "" and (profile.upgrades[profile.utilityEquipped] or 0) < 1 then
			profile.utilityEquipped = ""
		end
		return profile
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- public read API — for Tycoon / Economy / anyone else
	-- ─────────────────────────────────────────────────────────────────────────────

	function UpgradeService.levelOf(player: Player, id: string): number
		if not ENABLED then
			return 0
		end
		local profile = DataService.get(player)
		if not profile or type(profile.upgrades) ~= "table" then
			return 0
		end
		return tonumber(profile.upgrades[id]) or 0
	end

	--- The value of an upgrade's stat right now (WalkSpeed in studs/sec, magnet
	--- radius in studs, payout as a multiplier…). Level 0 returns the def's base,
	--- so this is safe to call for a player who has bought nothing.
	function UpgradeService.valueOf(player: Player, id: string): number
		local def = Utilities.UpgradeById[id]
		if not def then
			return 0
		end
		if not SHOP_ON then
			return def.base
		end
		return Utilities.valueAt(def, UpgradeService.levelOf(player, id))
	end

	--- Cash multiplier from the `payout` track. 1.0 when the prototype is off.
	---
	--- Registered with Economy.setMultiplierHook("upgrades") in start(), so this
	--- folds into every payout beside the rebirth multiplier. The registry is keyed
	--- so the session track's hook and this one compose rather than clobber.
	function UpgradeService.multiplierFor(player: Player): number
		if not SHOP_ON then
			return 1
		end
		return UpgradeService.valueOf(player, "payout")
	end

	--- Pickup radius from the `magnet` track, in studs.
	---
	--- TODO(consumer): Tycoon.lua's collector should sweep drops within this
	--- radius of the owner instead of requiring a touch, or the drop's own
	--- proximity check should widen by it. Tycoon.lua belongs to another track.
	function UpgradeService.magnetRadius(player: Player): number
		if not SHOP_ON then
			return 0
		end
		return UpgradeService.valueOf(player, "magnet")
	end

	--- Whether the vault empties itself.
	---
	--- TODO(consumer): Tycoon.lua's vault loop should, when this is true, pay the
	--- owner out on a timer rather than waiting for them to walk into the
	--- collector. Tycoon.lua belongs to another track.
	function UpgradeService.autoCollects(player: Player): boolean
		if not SHOP_ON then
			return false
		end
		return UpgradeService.levelOf(player, "autocollect") >= 1
	end

	function UpgradeService.equippedUtility(player: Player): string?
		if not UTILITY_ON then
			return nil
		end
		local profile = DataService.get(player)
		local id = profile and profile.utilityEquipped
		if type(id) == "string" and id ~= "" then
			return id
		end
		return nil
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- replication
	-- ─────────────────────────────────────────────────────────────────────────────

	local function cooldownRemaining(player: Player, id: string): number
		local byId = cooldowns[player]
		local readyAt = byId and byId[id]
		if not readyAt then
			return 0
		end
		return math.max(0, readyAt - os.clock())
	end

	function UpgradeService.push(player: Player)
		if not ENABLED or not player.Parent then
			return
		end
		local profile = ensure(player)
		if not profile then
			return
		end

		local levels: { [string]: number } = {}
		local costs: { [string]: number } = {}
		-- utilities gated behind a tycoon button they haven't bought yet, mapped to
		-- the name of the thing that unlocks them so the row can say why it's dead
		local locked: { [string]: string } = {}

		if SHOP_ON then
			for _, def in ipairs(Config.PlayerUpgrades) do
				local level = tonumber(profile.upgrades[def.id]) or 0
				levels[def.id] = level
				-- nil cost means maxed out; the client draws that as "MAX"
				costs[def.id] = Utilities.costAt(def, level)
			end
		end

		local equipped = ""
		if UTILITY_ON then
			for _, def in ipairs(Config.Utilities) do
				local level = tonumber(profile.upgrades[def.id]) or 0
				levels[def.id] = level
				costs[def.id] = Utilities.utilityCostAt(def, level)
				if level < 1 and def.requires and not (profile.owned and profile.owned[def.requires]) then
					local button = Config.ButtonById[def.requires]
					locked[def.id] = button and button.name or def.requires
				end
			end
			equipped = profile.utilityEquipped or ""
		end

		local cooldown, cooldownTotal = 0, 0
		if equipped ~= "" then
			local def = Utilities.UtilityById[equipped]
			cooldown = cooldownRemaining(player, equipped)
			cooldownTotal = def and def.cooldown or 0
		end

		-- The declared payload is { levels, costs }; the rest is additive and a
		-- client that ignores it still draws a correct shop.
		upgradeState:FireClient(player, {
			levels = levels,
			costs = costs,
			locked = locked,
			equipped = equipped,
			-- seconds remaining at the moment this was sent. The client counts it
			-- down locally rather than trusting os.clock() to mean the same thing
			-- on both machines — it doesn't.
			cooldown = cooldown,
			cooldownTotal = cooldownTotal,
		})
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- applying the stat upgrades
	-- ─────────────────────────────────────────────────────────────────────────────

	--- WalkSpeed is the only upgrade with a live effect on the character; the rest
	--- are read by other services through the API above.
	local function applySpeed(player: Player, character: Model?)
		if not SHOP_ON then
			return
		end
		character = character or player.Character
		local humanoid = character and character:FindFirstChildOfClass("Humanoid")
		if not humanoid then
			return
		end
		humanoid.WalkSpeed = UpgradeService.valueOf(player, "speed")

		-- Mirrored onto the player so anything that wants the stat — the client,
		-- a future Tycoon collector sweep — can read it without a round trip. The
		-- server is still the only writer.
		player:SetAttribute("TungMagnetRadius", UpgradeService.magnetRadius(player))
		player:SetAttribute("TungCashMultiplier", UpgradeService.multiplierFor(player))
		player:SetAttribute("TungAutoCollect", UpgradeService.autoCollects(player))
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- the utility verbs
	-- ─────────────────────────────────────────────────────────────────────────────

	--- NPCService parents every raider to workspace.SahurRaiders and exposes no
	--- accessor for the live set, so we read the folder. TODO(NPCService): a
	--- `NPCService.raidersNear(position, radius)` would let this stop reaching
	--- into the workspace by name. The IsSahurNPC attribute check is the same one
	--- CombatService.canDamage uses, so a stray Model in the folder can't be
	--- frozen by accident.
	local function raidersNear(position: Vector3, radius: number): { Model }
		local folder = workspace:FindFirstChild("SahurRaiders")
		local found: { Model } = {}
		if not folder then
			return found
		end
		for _, child in ipairs(folder:GetChildren()) do
			if child:IsA("Model") and child:GetAttribute("IsSahurNPC") then
				local humanoid, root = Util.getRig(child)
				if humanoid and root and humanoid.Health > 0
					and (root.Position - position).Magnitude <= radius
				then
					table.insert(found, child)
				end
			end
		end
		return found
	end

	type FrozenEntry = { root: BasePart, wasAnchored: boolean, thawAt: number, highlight: Highlight? }
	local frozen: { [Model]: FrozenEntry } = {}

	local function thaw(npc: Model)
		local entry = frozen[npc]
		if not entry then
			return
		end
		-- a second freeze landed while this one was pending; let the later one own
		-- the thaw so overlapping casts extend rather than cut each other short
		local remaining = entry.thawAt - os.clock()
		if remaining > 0.05 then
			task.delay(remaining, thaw, npc)
			return
		end
		frozen[npc] = nil
		if entry.highlight then
			entry.highlight:Destroy()
		end
		if entry.root.Parent then
			entry.root.Anchored = entry.wasAnchored
		end
	end

	--- Roots a raider by ANCHORING it, not by zeroing WalkSpeed.
	---
	--- NPCService's tick writes `humanoid.WalkSpeed` on every Heartbeat, so a
	--- WalkSpeed of 0 set from out here survives for less than a frame. Anchoring
	--- the root part anchors the whole welded assembly and no amount of MoveTo
	--- moves it, which is the only way to root a raider without editing
	--- NPCService. Side effect worth knowing: a raider frozen mid-air hangs there
	--- and drops when it thaws, and a frozen raider still swings if you stand in
	--- its reach — freeze buys you movement, not safety.
	local function freezeRaider(npc: Model, seconds: number)
		local humanoid, root = Util.getRig(npc)
		if not humanoid or not root then
			return
		end

		local entry = frozen[npc]
		if entry then
			entry.thawAt = math.max(entry.thawAt, os.clock() + seconds)
			return
		end

		-- Highlights are capped at 255 per client and disabled ones still hold a
		-- slot, so these are created per freeze and destroyed on thaw rather than
		-- living on every raider. A wave is capped well under the limit.
		local highlight = Instance.new("Highlight")
		highlight.FillColor = ICE
		highlight.FillTransparency = 0.55
		highlight.OutlineColor = Color3.fromRGB(235, 250, 255)
		highlight.DepthMode = Enum.HighlightDepthMode.Occluded
		highlight.Adornee = npc
		highlight.Parent = npc

		frozen[npc] = {
			root = root,
			wasAnchored = root.Anchored,
			thawAt = os.clock() + seconds,
			highlight = highlight,
		}
		root.Anchored = true
		Fx.burst(root.Position, ICE, 6, workspace)

		task.delay(seconds, thaw, npc)
	end

	local VERBS: { [string]: (Player, Model, BasePart, any) -> boolean } = {}

	VERBS.freeze = function(player: Player, character: Model, root: BasePart, def): boolean
		local targets = raidersNear(root.Position, reachOf("freeze", 34))
		for _, npc in ipairs(targets) do
			freezeRaider(npc, def.duration)
		end
		Fx.burst(root.Position, ICE, reachOf("freeze", 34) * 0.9, workspace)
		Fx.impact(root, 1.9)
		Economy.notify(player, {
			kind = "info",
			title = "SAHUR FREEZE",
			body = #targets == 0
				and "Nothing in range."
				or ("%d raider%s frozen for %ds."):format(#targets, #targets == 1 and "" or "s", def.duration),
		})
		return true
	end

	VERBS.shove = function(player: Player, character: Model, root: BasePart, def): boolean
		local origin = root.Position
		local pushed = 0

		local function impulseFor(victimRoot: BasePart): Vector3
			local direction = victimRoot.Position - origin
			direction = Vector3.new(direction.X, 0, direction.Z)
			if direction.Magnitude < 0.1 then
				direction = root.CFrame.LookVector * Vector3.new(1, 0, 1)
			end
			direction = direction.Unit
			-- same shape as CombatService.damage's knockback so a shove reads as a
			-- very heavy bat hit rather than as a different physics system
			return (direction * forceOf("shove", 130) + Vector3.new(0, forceOf("shove", 130) * 0.45, 0))
				* victimRoot.AssemblyMass * 0.6
		end

		for _, npc in ipairs(raidersNear(origin, reachOf("shove", 26))) do
			local _, npcRoot = Util.getRig(npc)
			-- A frozen raider is anchored, so an impulse does nothing to it. That
			-- interaction is deliberate: freeze pins them, shove scatters them, and
			-- you have to pick.
			if npcRoot and not npcRoot.Anchored then
				npcRoot:ApplyImpulse(impulseFor(npcRoot))
				pushed += 1
			end
		end

		for _, other in ipairs(Players:GetPlayers()) do
			local otherChar = other.Character
			local victimHumanoid, victimRoot = Util.getRig(otherChar)
			if other ~= player and otherChar and victimHumanoid and victimRoot and victimHumanoid.Health > 0
				and (victimRoot.Position - origin).Magnitude <= reachOf("shove", 26)
				-- Shove deals no damage, but it still displaces someone, so it obeys
				-- the same geography rule as the bat: only inside the arena, never
				-- onto someone standing on their own plot.
				and CombatService.canDamage(player, otherChar)
			then
				-- The victim's client owns their character's physics; a server
				-- ApplyImpulse here is discarded on the next replication tick, so
				-- the impulse is computed on the server and applied by them.
				knockbackRemote:FireClient(other, impulseFor(victimRoot))
				pushed += 1
			end
		end

		Fx.burst(origin, Color3.fromRGB(255, 190, 120), reachOf("shove", 26) * 0.9, workspace)
		Fx.impact(root, 0.7)
		Economy.notify(player, {
			kind = "info",
			title = "TUNG SHOVE",
			body = pushed == 0 and "Nothing in range." or ("Shoved %d."):format(pushed),
		})
		return true
	end

	--- STUB. It builds and shows the decoy, and raiders completely ignore it.
	---
	--- Making it real is a change in NPCService, not here, and that change now has
	--- exactly one site: `refreshSnapshot()` builds the single list of everything
	--- raiders consider a target, and `nearestSnapshotEntry()` reads it. Adding
	--- models tagged IsSahurDecoy to that list — plus a Humanoid on the decoy so
	--- raider swings have something to connect with — is the whole hook.
	---
	--- Left as a stub on purpose: faking it here (e.g. teleporting raiders at the
	--- decoy) would look right for one wave and fight the AI forever after.
	VERBS.decoy = function(player: Player, character: Model, root: BasePart, def): boolean
		local dummy = Instance.new("Part")
		dummy.Name = "TungDecoy"
		dummy.Anchored = true
		dummy.CanCollide = false
		dummy.Material = Enum.Material.Neon
		dummy.Color = Color3.fromRGB(255, 150, 60)
		dummy.Size = Vector3.new(2.4, 5.6, 2.4)
		dummy.CFrame = root.CFrame * CFrame.new(0, 0, -reachOf("decoy", 6))
		dummy:SetAttribute("IsSahurDecoy", true)
		dummy:SetAttribute("Owner", player.UserId)
		dummy.Parent = workspace
		Debris:AddItem(dummy, def.duration)

		Economy.notify(player, {
			kind = "warn",
			title = "DECOY (PROTOTYPE)",
			body = "The decoy spawns, but raiders don't target it yet.",
		})
		return true
	end

	--- Runs the equipped verb if it is off cooldown. Returns whether it fired, so
	--- a refusal never starts a cooldown.
	function UpgradeService.useUtility(player: Player): boolean
		if not UTILITY_ON then
			return false
		end
		local now = os.clock()
		if now - (lastUse[player] or 0) < USE_THROTTLE then
			return false
		end
		lastUse[player] = now

		local id = UpgradeService.equippedUtility(player)
		if not id then
			return false
		end
		local def = Utilities.UtilityById[id]
		if not def or UpgradeService.levelOf(player, id) < 1 then
			return false
		end
		if cooldownRemaining(player, id) > 0 then
			-- the client hides this case already; a stale or hostile one gets a
			-- state push back so its readout resyncs instead of silence
			UpgradeService.push(player)
			return false
		end

		local character = player.Character
		local humanoid, root = Util.getRig(character)
		if not character or not humanoid or not root or humanoid.Health <= 0 then
			return false
		end

		local verb = VERBS[def.verb]
		if not verb then
			warn(("[Tung] utility %q has no verb implementation"):format(def.verb))
			return false
		end

		local ok, err = pcall(verb, player, character, root, def)
		if not ok then
			warn(("[Tung] utility %s failed: %s"):format(id, tostring(err)))
			return false
		end

		local byId = cooldowns[player]
		if not byId then
			byId = {}
			cooldowns[player] = byId
		end
		byId[id] = os.clock() + def.cooldown
		UpgradeService.push(player)
		return true
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- purchases
	-- ─────────────────────────────────────────────────────────────────────────────

	local function buyUpgrade(player: Player, profile, def): boolean
		local level = tonumber(profile.upgrades[def.id]) or 0
		local cost = Utilities.costAt(def, level)
		if not cost then
			return false
		end
		if not Economy.spend(player, cost) then
			Economy.notify(player, {
				kind = "warn",
				title = "NOT ENOUGH TUNG",
				body = ("%s costs %s."):format(def.name, Util.abbreviate(cost)),
			})
			return false
		end

		profile.upgrades[def.id] = level + 1
		applySpeed(player)

		Economy.notify(player, {
			kind = "buy",
			title = ("%s  Lv %d"):format(def.name, level + 1),
			body = Utilities.describe(def, level + 1),
		})
		local _, root = Util.getRig(player.Character)
		if root then
			Fx.burst(root.Position, Color3.fromRGB(190, 130, 255), 8, workspace)
		end
		return true
	end

	--- One remote does buy AND equip: clicking a utility you don't own buys it,
	--- clicking one you do own equips it. The alternative is a second C->S remote
	--- for equipping, and "the row you tap is the utility you get" is a simpler
	--- contract than two verbs on one row.
	local function buyOrEquipUtility(player: Player, profile, def): boolean
		local level = tonumber(profile.upgrades[def.id]) or 0
		if level >= 1 then
			if profile.utilityEquipped == def.id then
				return false
			end
			profile.utilityEquipped = def.id
			Economy.notify(player, {
				kind = "gear",
				title = "EQUIPPED: " .. def.name,
				body = ("Press Q  •  %ds cooldown"):format(def.cooldown),
			})
			return true
		end

		if def.requires and not (profile.owned and profile.owned[def.requires]) then
			local button = Config.ButtonById[def.requires]
			Economy.notify(player, {
				kind = "warn",
				title = "LOCKED",
				body = ("%s needs %s first."):format(def.name, button and button.name or def.requires),
			})
			return false
		end

		if not Economy.spend(player, def.price) then
			Economy.notify(player, {
				kind = "warn",
				title = "NOT ENOUGH TUNG",
				body = ("%s costs %s."):format(def.name, Util.abbreviate(def.price)),
			})
			return false
		end

		profile.upgrades[def.id] = 1
		-- equip it immediately: buying a verb and then having to select it is a
		-- second step nobody expects
		profile.utilityEquipped = def.id
		Economy.notify(player, {
			kind = "gear",
			title = "UTILITY: " .. def.name,
			body = ("Press Q  •  %ds cooldown"):format(def.cooldown),
		})
		return true
	end

	function UpgradeService.request(player: Player, id: string)
		if not ENABLED or type(id) ~= "string" then
			return
		end
		local profile = ensure(player)
		if not profile then
			return
		end

		local upgrade = SHOP_ON and Utilities.UpgradeById[id]
		local utility = UTILITY_ON and Utilities.UtilityById[id]
		if upgrade then
			buyUpgrade(player, profile, upgrade)
		elseif utility then
			buyOrEquipUtility(player, profile, utility)
		end

		-- Push regardless of the outcome. The client's own copy of the state is
		-- only ever a redraw of ours, so a rejected click resyncs it rather than
		-- leaving it showing a price it can't pay.
		UpgradeService.push(player)
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- lifecycle
	-- ─────────────────────────────────────────────────────────────────────────────

	function UpgradeService.onPlayer(player: Player)
		if not ENABLED then
			return
		end
		task.spawn(function()
			-- the profile can still be loading on first join; the shop is not worth
			-- blocking the boot for, so wait for it out of band
			local deadline = os.clock() + 12
			while not DataService.get(player) and player.Parent and os.clock() < deadline do
				task.wait(0.25)
			end
			if not player.Parent then
				return
			end
			ensure(player)
			applySpeed(player)
			UpgradeService.push(player)
		end)
	end

	function UpgradeService.onCharacter(player: Player, character: Model)
		if not ENABLED then
			return
		end
		if not character:FindFirstChildOfClass("Humanoid") then
			character:WaitForChild("Humanoid", 10)
		end
		applySpeed(player, character)
		-- CombatService.onCharacter also writes WalkSpeed, and on respawn the order
		-- of the two is not guaranteed by anything stronger than Main's call order.
		-- Re-applying once a beat later is a cheap way to always win that race.
		task.delay(0.75, function()
			if player.Character == character then
				applySpeed(player, character)
			end
		end)
		UpgradeService.push(player)
	end

	function UpgradeService.start()
		if not ENABLED then
			return
		end

		-- Fold the `payout` track into every payout. The registry is keyed so the
		-- session track's own hook and this one compose instead of clobbering each
		-- other, and registering here rather than in Economy keeps Economy from
		-- having to know a prototype exists.
		if SHOP_ON then
			Economy.setMultiplierHook("upgrades", UpgradeService.multiplierFor)
		end

		requestUpgrade.OnServerEvent:Connect(function(player, id)
			UpgradeService.request(player, id)
		end)

		useUtility.OnServerEvent:Connect(function(player)
			UpgradeService.useUtility(player)
		end)

		Players.PlayerRemoving:Connect(function(player)
			cooldowns[player] = nil
			lastUse[player] = nil
		end)

		print(("[Tung] UpgradeService: %d upgrades, %d utilities%s")
			:format(SHOP_ON and #Config.PlayerUpgrades or 0,
				UTILITY_ON and #Config.Utilities or 0,
				UTILITY_ON and "" or " (utility slot off)"))
	end

	return UpgradeService
end


-- ── entry point ───────────────────────────────────────────────


--[[
	Main.server.lua — Tung Tung Tycoon boot sequence.

	Order matters: data before economy (leaderstats read profiles), world
	before plots, plots before players are let in.
]]

local Req = __Req
local Config = Req("Config")
Req("Net")  -- creates the RemoteEvent folder before any client asks for it
local MapBuilder = Req("MapBuilder")
local DataService = Req("DataService")
local Economy = Req("Economy")
local CombatService = Req("CombatService")
local PlotService = Req("PlotService")
local NPCService = Req("NPCService")

-- Prototype services. Each one is a no-op unless its Config.Prototypes flag is
-- on, so this list costs nothing in a shipping build.
local UpgradeService = Req("UpgradeService")
local SessionService = Req("SessionService")
local FloorService = Req("FloorService")

local Players = game:GetService("Players")

local START = os.clock()

Players.CharacterAutoLoads = true

-- 1. world
local world = MapBuilder.build()

-- 2. services
DataService.start()
Economy.start()
CombatService.start()

-- 3. plots
PlotService.build(world)
PlotService.start()

-- 4. raids
NPCService.start()

-- 5. prototypes, each gated on its own flag
UpgradeService.start()
SessionService.start()
FloorService.start()

-- 6. players
local function onCharacterAdded(player: Player, character: Model)
	-- keep players from clipping into the belt machinery on spawn
	character:WaitForChild("HumanoidRootPart", 10)

	-- Respawn on your own plot rather than the arena. Roblox picks the spawn
	-- before we get here, so this is a reposition, not a SpawnLocation: a
	-- per-plot SpawnLocation would land in the random-spawn pool and start
	-- sending other players to your factory.
	task.defer(PlotService.teleportToPlot, player)

	CombatService.onCharacter(player, character)
	UpgradeService.onCharacter(player, character)
	Economy.push(player)
end

local function onPlayerAdded(player: Player)
	DataService.load(player)
	Economy.setupLeaderstats(player)
	Economy.push(player)
	UpgradeService.onPlayer(player)
	SessionService.onPlayer(player)

	player.CharacterAdded:Connect(function(character)
		task.spawn(onCharacterAdded, player, character)
	end)
	if player.Character then
		task.spawn(onCharacterAdded, player, player.Character)
	end

	-- give them a factory right away if one is free
	task.delay(1.5, function()
		if player.Parent and not PlotService.plotOf(player) then
			PlotService.autoAssign(player)
		end
	end)

	Economy.notify(player, {
		kind = "welcome",
		title = "TUNG TUNG TYCOON",
		body = "Buy droppers. Upgrade the tung. Defend the Sahur raid.",
	})
end

Players.PlayerAdded:Connect(onPlayerAdded)
for _, player in ipairs(Players:GetPlayers()) do
	task.spawn(onPlayerAdded, player)
end

print(("[Tung] Tung Tung Tycoon booted in %.2fs — %d plots, %d buttons, %d bats.")
	:format(os.clock() - START, Config.World.PlotCount, #Config.Buttons, #Config.Bats))
